    private const string T =
        "self.__next_f.push([1,\"5:[\"$\",\"div\",null,{\"className\":\"flex flex-col w-full h-full\",\"children\":[\"$\",\"$L14\",null,{\"params\":{\"sSort\":\"pDate\",\"pSort\":\"p\",\"sortDirection\":\"desc\",\"search\":\"Профессор Икс\",\"editor\":\"\",\"solo\":false,\"or\":false,\"author\":\"\",\"ansSearch\":true,\"textSearch\":true,\"commSearch\":true,\"sourceSearch\":false,\"fromD\":\"0\",\"toD\":\"100\",\"limit\":100,\"uD\":true,\"withdrawn\":false,\"page\":1,\"fromTrueDL\":\"0\",\"toTrueDL\":\"10\",\"uDL\":true,\"startPlayed\":\"\",\"endPlayed\":\"\",\"type\":\"questions\"},\"questions\":[{\"id\":416426,\"number\":23,\"text\":\"Профессорка Маргарет Коллинз более десяти лет проработала в\u00a0Гайане, а\u00a0после даже консультировала местных военных по\u00a0вопросам строительства. Маргарет называли повелительницей ИКСОВ. Назовите ИКСОВ словом латинского происхождения.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"термиты.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Коллинз\u00a0— первая афроамериканка, получившая степень доктора энтомологии. В\u00a0Гайане она изучала термитов и\u00a0после консультировала местную армию, как\u00a0строить, минимизируя риски повреждений от\u00a0насекомых. Также она предлагала использовать выделения термитов для\u00a0укрепления строительных материалов.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. https://en.wikipedia.org/wiki/Margaret_S._Collins\\\\n2. https://thebiologist.rsb.org.uk/biologist-features/the-termite-lady-pioneering-biologist-and-activist-margaret-collins\",\"authors\":[{\"id\":12163,\"name\":\"Сергей Никольский\",\"gender\":\"HE\"}],\"editors\":[{\"id\":12163,\"name\":\"Сергей Никольский\",\"gender\":\"HE\"}],\"tour\":{\"id\":26707,\"number\":2,\"title\":\"\"},\"packId\":6318,\"packTitle\":\"Балтийский Бриз. Masters VI\",\"controversials\":[{\"id\":257469,\"answer\":\"москито\",\"status\":\"D\",\"comment\":\"None\",\"appealJuryComment\":\"None\"},{\"id\":258517,\"answer\":\"Муравьи\",\"status\":\"D\",\"comment\":\"None\",\"appealJuryComment\":\"None\"}],\"appeals\":[],\"totalLikes\":4,\"totalDislikes\":6,\"pubDate\":\"2025-05-13 19:16:04.581547\",\"endDate\":\"2025-04-23 23:55:00\",\"uploader\":65,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[243,50],\"complexity\":[46.5,66],\"correct_answers\":[113,33],\"tournaments\":[{\"id\":10997,\"title\":\"Балтийский Бриз. Masters VI\",\"typeoft\":{\"id\":3,\"title\":\"Синхрон\"}},{\"id\":10998,\"title\":\"Балтийский Бриз. Masters VI (асинхрон/онлайн)\",\"typeoft\":{\"id\":8,\"title\":\"Асинхрон\"}}]},{\"id\":413263,\"number\":21,\"text\":\"Герой одной видеоигры утешает бывшего спецназовца, который из-за травм больше не может участвовать в сражениях. Подчёркивая его важность для команды, герой говорит, что если раньше тот был Капитаном Америка, то теперь он икс. Какое слово с удвоенной согласной мы пропустили?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"профессор\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"из-за полученных ранений бывший спецназовец теперь вынужден перейти на штабную работу и помогать команде головой, а не своими выдающимися боевыми навыками. Профессор Ксавье, также известный как профессор Икс, – основатель команды Люди-Икс, супергерой с парализованной нижней частью тела, сделавший своим главным оружием ум.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. https://www.youtube.com/watch?v=r37ZNhmhkVA\\u0026t=133s\\\\r\\\\n2. https://callofduty.fandom.com/wiki/Frank_Woods\",\"authors\":[{\"id\":2422,\"name\":\"Валентин Копочель\",\"gender\":\"HE\"}],\"editors\":[{\"id\":136,\"name\":\"Андрей Акимов\",\"gender\":\"HE\"},{\"id\":874,\"name\":\"Василий Бобков\",\"gender\":\"HE\"},{\"id\":2422,\"name\":\"Валентин Копочель\",\"gender\":\"HE\"},{\"id\":12486,\"name\":\"Владислав Пупшинович\",\"gender\":\"HE\"},{\"id\":12487,\"name\":\"Дмитрий Красковский\",\"gender\":\"HE\"},{\"id\":12488,\"name\":\"Иннокентий Петровский\",\"gender\":\"HE\"}],\"tour\":{\"id\":26405,\"number\":2,\"title\":\"Второй тур\"},\"packId\":6237,\"packTitle\":\"Школьная лига Евразии. V тур\",\"controversials\":[{\"id\":253719,\"answer\":\"мистер икс\",\"status\":\"D\",\"comment\":\"None\",\"appealJuryComment\":\"None\"},{\"id\":252607,\"answer\":\"Ксавьер\",\"status\":\"D\",\"comment\":\"None\",\"appealJuryComment\":\"None\"}],\"appeals\":[],\"totalLikes\":4,\"totalDislikes\":7,\"pubDate\":\"2025-03-07 12:09:32\",\"endDate\":\"2025-02-16 19:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[1214],\"complexity\":[8.4],\"correct_answers\":[102],\"tournaments\":[{\"id\":11185,\"title\":\"Школьная лига Евразии. V тур\",\"typeoft\":{\"id\":8,\"title\":\"Асинхрон\"}}]},{\"id\":411385,\"number\":23,\"text\":\"Профессор Артуро Розенблют собирал на своих семинарах самых способных учёных из разных областей. Для встреч Артуро использовал ИКС в Вандербилт-холле. Назовите ИКС двумя словами.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"круглый стол.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"неизвестно, выбрал ли Артуро Розенблют такой формат с оглядкой на свое имя, или так проще было выслушивать каждого. Формат оказался удачным - среди ученых, на которых он повлиял, был, например, отец кибернетики Норберт Винер.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"Arturo Rosenblueth and Norbert Wiener: Two Scientists in the Historiography of Contemporary Education (researchgate.net)\",\"authors\":[{\"id\":112,\"name\":\"Владимир Островский\",\"gender\":\"HE\"}],\"editors\":[{\"id\":112,\"name\":\"Владимир Островский\",\"gender\":\"HE\"}],\"tour\":{\"id\":26227,\"number\":2,\"title\":\"\"},\"packId\":6185,\"packTitle\":\"Балтийский Бриз. Masters IV\",\"controversials\":[{\"id\":249900,\"answer\":\"овальный кабинет\",\"status\":\"D\",\"comment\":\"None\",\"appealJuryComment\":\"None\"},{\"id\":249433,\"answer\":\"шведский стол\",\"status\":\"D\",\"comment\":\"None\",\"appealJuryComment\":\"None\"}],\"appeals\":[],\"totalLikes\":6,\"totalDislikes\":3,\"pubDate\":\"2025-02-04 20:06:47.352417\",\"endDate\":\"2025-02-01 23:55:00\",\"uploader\":65,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[265,44],\"complexity\":[41.51,52.27],\"correct_answers\":[110,23],\"tournaments\":[{\"id\":11001,\"title\":\"Балтийский Бриз. Masters IV\",\"typeoft\":{\"id\":3,\"title\":\"Синхрон\"}},{\"id\":11002,\"title\":\"Балтийский Бриз. Masters IV (асинхрон/онлайн)\",\"typeoft\":{\"id\":8,\"title\":\"Асинхрон\"}}]},{\"id\":408595,\"number\":23,\"text\":\"Герой фантастического романа потратил много сил, чтобы его компьютер стал вести себя как девушка. Женская ипостась компьютера в шутку упрекала героя в комплексе ИКСА. ИКС — название астероида из группы Аму\u0301ров. Какое имя заменено словом «ИКС»?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Пигмалио\u0301н.\",\"answerPic\":\"\",\"zachet\":\"точный ответ.\",\"nezachet\":\"\",\"comment\":\"в греческой мифологии скульптор Пигмалион влюбился в статую, после чего она ожила. Аллюзией на этот сюжет стала пьеса Бе\u0301рнарда Шо\u0301у «Пигмалион», в которой профессор превращает простую цветочницу в леди. Отголоски этого сюжета можно найти и в поведении героя. Амур — бог любви, так что название астероида в честь одного из самых известных мифологических влюблённых довольно символично.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. Н. Горькавый. Курьер 619 (Юпитер — Челябинск); https://tinyurl.com/snnf3awk\\\\n2. https://ru.wikipedia.org/wiki/Пигмалион\\\\n3. https://ru.wikipedia.org/wiki/(96189)_Пигмалион\",\"authors\":[{\"id\":267,\"name\":\"Максим Мерзляков\",\"gender\":\"HE\"}],\"editors\":[{\"id\":267,\"name\":\"Максим Мерзляков\",\"gender\":\"HE\"}],\"tour\":{\"id\":26011,\"number\":2,\"title\":\"\"},\"packId\":6133,\"packTitle\":\"«Лига плюша-1: Баранка»\",\"controversials\":[],\"appeals\":[],\"totalLikes\":3,\"totalDislikes\":2,\"pubDate\":\"2024-12-27 11:48:57.168301\",\"endDate\":\"2024-10-25 23:55:00\",\"uploader\":218,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[190,106],\"complexity\":[77.37,83.96],\"correct_answers\":[147,89],\"tournaments\":[{\"id\":11065,\"title\":\"Лига Плюша-1: Баранка (синхрон)\",\"typeoft\":{\"id\":3,\"title\":\"Синхрон\"}},{\"id\":11066,\"title\":\"Лига Плюша-1: Баранка (асинхрон)\",\"typeoft\":{\"id\":8,\"title\":\"Асинхрон\"}}]},{\"id\":408225,\"number\":13,\"text\":\"Говоря о самоотверженности профессора Малло\u0301уэна, биограф приводит случай, когда ИКС не смог заставить его прекратить лекцию — Маллоуэн продолжил, опустившись на стул. Из ИКСА можно собрать «стул». Назовите ИКС.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"инсульт.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"только после окончания лекции профессор дал отвезти себя в больницу. Из букв слова «инсульт» можно составить слово «стул».\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"Александр Ливергант. Агата Кристи: свидетель обвинения.\",\"authors\":[{\"id\":6,\"name\":\"Сергей Терентьев\",\"gender\":\"HE\"}],\"editors\":[{\"id\":6,\"name\":\"Сергей Терентьев\",\"gender\":\"HE\"}],\"tour\":{\"id\":25979,\"number\":3,\"title\":\"\"},\"packId\":6123,\"packTitle\":\"Солнечный Филин\",\"controversials\":[{\"id\":232112,\"answer\":\"скулшутер\",\"status\":\"D\",\"comment\":\"None\",\"appealJuryComment\":\"None\"}],\"appeals\":[],\"totalLikes\":4,\"totalDislikes\":2,\"pubDate\":\"2024-12-15 10:03:22.967922\",\"endDate\":\"2024-08-18 23:00:00\",\"uploader\":178,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[73,37],\"complexity\":[93.15,91.89],\"correct_answers\":[68,34],\"tournaments\":[{\"id\":10867,\"title\":\"Солнечный Филин\",\"typeoft\":{\"id\":3,\"title\":\"Синхрон\"}},{\"id\":11042,\"title\":\"Солнечный Филин (онлайн/асинхрон) \",\"typeoft\":{\"id\":8,\"title\":\"Асинхрон\"}}]},{\"id\":402706,\"number\":20,\"text\":\"В фильме 1963 года учёный получает возможность видеть сквозь стены. По совпадению, он является однофамильцем Чарльза, известного с того же года. Напишите их общую фамилию.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Ксавье\u0301.\",\"answerPic\":\"\",\"zachet\":\"Ксавье\u0301р.\",\"nezachet\":\"\",\"comment\":\"по сюжету фильма, учёный получает рентгеновское зрение. По совпадению, в том же году в комиксах дебютировал Профессор Икс. Общая фамилия учёных – Ксавье\u0301.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. https://en.wikipedia.org/wiki/X:_The_Man_with_the_X-ray_Eyes\\\\n2. https://ru.wikipedia.org/wiki/Профессор_Икс\",\"authors\":[{\"id\":12332,\"name\":\"Павел Парфианович\",\"gender\":\"HE\"}],\"editors\":[{\"id\":12332,\"name\":\"Павел Парфианович\",\"gender\":\"HE\"}],\"tour\":{\"id\":25476,\"number\":2,\"title\":\"\"},\"packId\":5992,\"packTitle\":\"Джем. Этап 6: Ежевичный\",\"controversials\":[{\"id\":228150,\"answer\":\"Хавьер\",\"status\":\"D\",\"comment\":\"None\",\"appealJuryComment\":\"None\"},{\"id\":228153,\"answer\":\"Эксабиар\",\"status\":\"D\",\"comment\":\"None\",\"appealJuryComment\":\"None\"}],\"appeals\":[],\"totalLikes\":3,\"totalDislikes\":1,\"pubDate\":\"2024-09-12 09:45:18.926718\",\"endDate\":\"2024-06-08 19:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[94,39],\"complexity\":[37.23,48.72],\"correct_answers\":[35,19],\"tournaments\":[{\"id\":9326,\"title\":\"Джем. Этап 6: Ежевичный\",\"typeoft\":{\"id\":3,\"title\":\"Синхрон\"}},{\"id\":9332,\"title\":\"Джем. Этап 6: Ежевичный (асинхрон)\",\"typeoft\":{\"id\":8,\"title\":\"Асинхрон\"}}]},{\"id\":406954,\"number\":48,\"text\":\"Британская реформа, сократившая «гнилые местечки», снизила коррупцию. Следующие парламентские выборы прозвали «ТАКИМИ», поскольку прежние методы работы с избирателями стали неактуальны. Около ста лет назад йельский профессор предсказал выгоду от ТАКОГО ИКСА в несколько миллиардов долларов в год. Назовите ТАКОЙ ИКС.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"сухой закон.\",\"answerPic\":\"\",\"zachet\":\"точный ответ.\",\"nezachet\":\"\",\"comment\":\"до реформы избирателей подкупали, а чаще всего банально спаивали. Экономист И\u0301рвинг Фи\u0301шер, который был сторонником трезвости, вычислил выгоду от введения сухого закона, но, судя по всему, в своих расчётах был предвзят.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. https://ru.wikipedia.org/wiki/Гнилые_местечки\\\\n2. П. Акройд. Расцвет империи. От битвы при Ватерлоо до Бриллиантового юбилея королевы Виктории; https://tinyurl.com/as6zbzbe\\\\n3. https://ru.wikipedia.org/wiki/Сухой_закон_в_США\",\"authors\":[{\"id\":267,\"name\":\"Максим Мерзляков\",\"gender\":\"HE\"}],\"editors\":[{\"id\":267,\"name\":\"Максим Мерзляков\",\"gender\":\"HE\"}],\"tour\":{\"id\":25859,\"number\":4,\"title\":\"\"},\"packId\":6092,\"packTitle\":\"XVI Открытый Чемпионат Великобритании по Интеллектуальным Играм\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2024-12-02 16:51:57.064600\",\"endDate\":\"2024-05-04 20:00:00\",\"uploader\":1580,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[23],\"complexity\":[56.52],\"correct_answers\":[13],\"tournaments\":[{\"id\":10237,\"title\":\"Чемпионат Великобритании\",\"typeoft\":{\"id\":2,\"title\":\"Обычный\"}}]},{\"id\":413504,\"number\":31,\"text\":\"Профессор Чарльз Ко\u0301упленд в здании Кембриджского колледжа предпочитал занимать маленькую и не слишком удобную комнату. Поясняя это решение, Коупленд говорил о Боге как о своём единственном ИКСЕ — очень занятом и очень тихом. Назовите ИКСА двумя словами, которые начинаются на одну и ту же букву.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"сосед сверху\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Для профессора была очень важна тишина, и в здании Кембриджского колледжа он занимал комнату практически под крышей.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"https://www.newspapers.com/newspage/532324517/\",\"authors\":[{\"id\":105,\"name\":\"Антон Саксонов\",\"gender\":\"HE\"}],\"editors\":[{\"id\":105,\"name\":\"Антон Саксонов\",\"gender\":\"HE\"}],\"tour\":{\"id\":26427,\"number\":3,\"title\":\"\"},\"packId\":6244,\"packTitle\":\"Островок Бесконечности: февраль (2024)\",\"controversials\":[{\"id\":217083,\"answer\":\"скромный сосед\",\"status\":\"D\",\"comment\":\"Выбор комнаты под крышей здания Чарльз Коупленд объяснял именно тем, что выше него в этом здании никто не живёт. Поэтому ответ команды является менее точным, чем ответ \\\"сосед сверху\\\".\",\"appealJuryComment\":\"None\"},{\"id\":217088,\"answer\":\"святой сосед\",\"status\":\"D\",\"comment\":\"Выбор комнаты под крышей здания Чарльз Коупленд объяснял именно тем, что выше него в этом здании никто не живёт. Поэтому ответ команды является менее точным, чем ответ \\\"сосед сверху\\\".\",\"appealJuryComment\":\"None\"},{\"id\":217142,\"answer\":\"спящем сосееде\",\"status\":\"D\",\"comment\":\"Выбор комнаты под крышей здания Чарльз Коупленд объяснял именно тем, что выше него в этом здании никто не живёт. Поэтому ответ команды является менее точным, чем ответ \\\"сосед сверху\\\".\",\"appealJuryComment\":\"None\"},{\"id\":216818,\"answer\":\"сосед собеседник\",\"status\":\"D\",\"comment\":\"Выбор комнаты под крышей здания Чарльз Коупленд объяснял именно тем, что выше него в этом здании никто не живёт. Поэтому ответ команды является менее точным, чем ответ \\\"сосед сверху\\\".\",\"appealJuryComment\":\"None\"},{\"id\":216757,\"answer\":\"спокойный сосед\",\"status\":\"D\",\"comment\":\"Выбор комнаты под крышей здания Чарльз Коупленд объяснял именно тем, что выше него в этом здании никто не живёт. Поэтому ответ команды является менее точным, чем ответ \\\"сосед сверху\\\".\",\"appealJuryComment\":\"None\"}],\"appeals\":[],\"totalLikes\":3,\"totalDislikes\":1,\"pubDate\":\"2025-03-14 11:30:42.050424\",\"endDate\":\"2024-02-17 08:00:00\",\"uploader\":36,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[236],\"complexity\":[52.54],\"correct_answers\":[124],\"tournaments\":[{\"id\":9655,\"title\":\"Островок Бесконечности: февраль (синхрон)\",\"typeoft\":{\"id\":3,\"title\":\"Синхрон\"}}]},{\"id\":389855,\"number\":24,\"text\":\"Певица Алекса\u0301ндра Хьюз говорит, что в своём творчестве пытается найти неизвестную частицу себя. Александра выступает под псевдонимом А\u0301лли. Профессор появился уже в самом первом выпуске. Что мы дважды пропустили в вопросе?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"X\",\"answerPic\":\"\",\"zachet\":\"икс\",\"nezachet\":\"\",\"comment\":\"в математике буквой Х [икс] обозначают нечто неизвестное. Александра выступает под псевдонимом Allie X [алли икс]. Лидер и основатель команды супергероев-мутантов Профессор Икс появился в первом выпуске комиксов об их приключениях.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. https://www.vice.com/en/article/rq4bam/allie-x-interview-2015\\\\r\\\\n2. https://en.wikipedia.org/wiki/Allie_X\\\\r\\\\n3. https://ru.wikipedia.org/wiki/Профессор_Икс\",\"authors\":[{\"id\":48,\"name\":\"Анвар Мухаметкалиев\",\"gender\":\"HE\"}],\"editors\":[{\"id\":48,\"name\":\"Анвар Мухаметкалиев\",\"gender\":\"HE\"},{\"id\":56,\"name\":\"Игорь Пятов\",\"gender\":\"HE\"}],\"tour\":{\"id\":24364,\"number\":2,\"title\":\"Второй тур\"},\"packId\":5705,\"packTitle\":\"Школьная лига. III тур\",\"controversials\":[],\"appeals\":[],\"totalLikes\":3,\"totalDislikes\":3,\"pubDate\":\"2023-12-21 09:06:15\",\"endDate\":\"2023-12-17 14:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[1246],\"complexity\":[7.78],\"correct_answers\":[97],\"tournaments\":[{\"id\":10069,\"title\":\"Школьная лига Европы. III тур\",\"typeoft\":{\"id\":8,\"title\":\"Асинхрон\"}}]},{\"id\":384458,\"number\":34,\"text\":\"В начале одного произведения дети, попав в лабораторию, захотели пить, а вскоре с испугом увидели, как люстра с потолком умчались вверх. По одной из версий, автора этого произведения вдохновила повесть «Приключения ИКСА меньше ИГРЕКА». ИКС и ИГРЕК различаются только первой буквой. Назовите ИКСА и ИГРЕК.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"мальчик, пальчик.\",\"answerPic\":\"\",\"zachet\":\"в любом порядке.\",\"nezachet\":\"\",\"comment\":\"речь идёт о сказке «Необыкновенные приключения Ка\u0301рика и Ва\u0301ли», в которой дети уменьшились, выпив эликсир в профессорской лаборатории.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. Я. Ларри. Необыкновенные приключения Карика и Вали; https://tinyurl.com/mvmwzcmd\\\\r\\\\n2. К. Булычёв. Второе пришествие Золушки; https://tinyurl.com/yt96chb8\",\"authors\":[{\"id\":267,\"name\":\"Максим Мерзляков\",\"gender\":\"HE\"}],\"editors\":[{\"id\":267,\"name\":\"Максим Мерзляков\",\"gender\":\"HE\"}],\"tour\":{\"id\":23857,\"number\":3,\"title\":\"\"},\"packId\":5572,\"packTitle\":\"Школьная лига Европы. I тур\",\"controversials\":[{\"id\":205610,\"answer\":\"Мальчик с пальчик\",\"status\":\"A\",\"comment\":\"None\",\"appealJuryComment\":\"None\"},{\"id\":205754,\"answer\":\"3\",\"status\":\"D\",\"comment\":\"None\",\"appealJuryComment\":\"None\"}],\"appeals\":[],\"totalLikes\":4,\"totalDislikes\":0,\"pubDate\":\"2023-10-12 12:33:17\",\"endDate\":\"2023-10-08 14:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[1235],\"complexity\":[16.76],\"correct_answers\":[207],\"tournaments\":[{\"id\":9814,\"title\":\"Школьная лига Европы. I тур\",\"typeoft\":{\"id\":8,\"title\":\"Асинхрон\"}}]},{\"id\":383147,\"number\":11,\"text\":\"Персонаж научно-фантастического сериала возмущён использованием фотофиниша на\u00a0высокотехнологичных гонках из-за\u00a0проявления ИКСА. Назовите ИКС двумя нарицательными словами.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"эффект наблюдателя\",\"answerPic\":\"\",\"zachet\":\"принцип неопределённости\",\"nezachet\":\"\",\"comment\":\"для\u00a0фотофиниша в\u00a0скачках используют электронный микроскоп, но\u00a0наблюдение меняет результат, и\u00a0профессор Фарнсворт этим недоволен. Редактор и\u00a0сам путался в\u00a0эффекте наблюдателя и\u00a0принципе неопределённости, но\u00a0Википедия утверждает, что\u00a0даже Гейзенберг их путал, так что\u00a0не\u00a0стоит сильно возмущаться этим.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. Futurama S03E04; https://youtu.be/AuFUnKr8VVI\\\\n2. https://theinfosphere.org/The_Luck_of_the_Fryrish\\\\n3. https://en.wikipedia.org/wiki/Observer_effect_(physics)\",\"authors\":[{\"id\":711,\"name\":\"Игорь Лаптев\",\"gender\":\"HE\"}],\"editors\":[{\"id\":109,\"name\":\"Андрей Скиренко\",\"gender\":\"HE\"}],\"tour\":{\"id\":23742,\"number\":1,\"title\":\"\"},\"packId\":5543,\"packTitle\":\"XXII чемпионат России среди студентов\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2023-09-12 10:10:05\",\"endDate\":\"2023-05-21 14:00:00\",\"uploader\":49,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[50],\"complexity\":[60],\"correct_answers\":[30],\"tournaments\":[{\"id\":9282,\"title\":\"Студенческий чемпионат России\",\"typeoft\":{\"id\":2,\"title\":\"Обычный\"}}]},{\"id\":390427,\"number\":5,\"text\":\"[Ведущему: прочесть «артурИКС» слитно, чтобы было понятно, что это одно слово! Не обращать внимания команд на кавычки в тексте вопроса!]\\\\nВ этом вопросе ИКС является заменой. В книге А\u0301ртура Ко\u0301нан Дойля «Затерянный мир» профессор Че\u0301лленджер нашёл в Бразилии живых динозавров. В честь Конан Дойля был назван найденный в Бразилии артурИ\u0301КС с пятиметровым размахом крыльев. «Челленджер» — это, можно сказать,\\\\nпример ИКСА. Назовите ИКС.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"дактиль.\",\"answerPic\":\"\",\"zachet\":\"точный ответ.\",\"nezachet\":\"\",\"comment\":\"согласно роману, кроме динозавров, Челленджер нашёл и летающих ящеров — например, птеродактиля. Родственника птеродактиля, найденного в Бразилии в 1994 году, в честь Конан Дойля назвали артурдактилем. Также дактиль — это трёхсложный стихотворный размер с первым ударным слогом. Примером дактиля можно считать фамилию Челленджер, в которой ударение падает на первый слог.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1)\\\\t\\\\thttps://ru.wikipedia.org/wiki/Затерянный_мир_(роман,_1912)\\\\n2)\\\\t\\\\thttps://ru.wikipedia.org/wiki/Артурдактиль\\\\n3)\\\\t\\\\thttps://ru.wikipedia.org/wiki/Дактиль\",\"authors\":[{\"id\":267,\"name\":\"Максим Мерзляков\",\"gender\":\"HE\"}],\"editors\":[{\"id\":267,\"name\":\"Максим Мерзляков\",\"gender\":\"HE\"}],\"tour\":{\"id\":24409,\"number\":1,\"title\":\"\"},\"packId\":5716,\"packTitle\":\"Школьный чемпионат России\",\"controversials\":[],\"appeals\":[],\"totalLikes\":6,\"totalDislikes\":0,\"pubDate\":\"2023-12-31 22:03:08\",\"endDate\":\"2023-05-01 17:00:00\",\"uploader\":64,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[72],\"complexity\":[4.17],\"correct_answers\":[3],\"tournaments\":[{\"id\":9043,\"title\":\"Школьный чемпионат России\",\"typeoft\":{\"id\":2,\"title\":\"Обычный\"}}]},{\"id\":377541,\"number\":42,\"text\":\"Герой одного романа — ИКС, который по просьбе знакомого профессора согласился подвергнуться серии экспериментов. Один из них закончился неудачно, поскольку ИКС представил комнату, в которой находился, и не учёл, что она была плохо освещена. Кто такой ИКС?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"мнемони\u0301ст.\",\"answerPic\":\"\",\"zachet\":\"мнемотехник, мнемоник; синонимичные описательные ответы с упоминанием феноменальной памяти.\",\"nezachet\":\"\",\"comment\":\"герой, у которого была феноменальная память, согласился послужить для знакомого профессора объектом экспериментов. При запоминании герой использовал «метод ло\u0301кусов», помещая предназначенные для запоминания данные в разные места какого-то помещения или знакомой ему местности. Однажды он расположил ряды чисел в той комнате, в которой находился, и не учёл, что ему не слишком хорошо видны тёмные углы — на соответствующих им числах он и сбился. Когда его глаза привыкли к темноте, повторный эксперимент прошёл удачно.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"Е. Водолазкин. Чагин; https://tinyurl.com/3ezvcz6n\",\"authors\":[{\"id\":267,\"name\":\"Максим Мерзляков\",\"gender\":\"HE\"}],\"editors\":[{\"id\":267,\"name\":\"Максим Мерзляков\",\"gender\":\"HE\"}],\"tour\":{\"id\":23268,\"number\":4,\"title\":\"\"},\"packId\":5424,\"packTitle\":\"Весенний Умлаут 2023\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2023-06-08 13:46:33\",\"endDate\":\"2023-04-09 16:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[30],\"complexity\":[16.67],\"correct_answers\":[5],\"tournaments\":[{\"id\":8979,\"title\":\"Весенний Умлаут 2023\",\"typeoft\":{\"id\":2,\"title\":\"Обычный\"}}]},{\"id\":381265,\"number\":45,\"text\":\"В шуточном комиксе про Гарри Поттера профессор Дамблдор представляет нового учителя по Защите от темных искусств, после чего слизеренцы покидают зал. Назовите имя этого учителя.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Патрик\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"святой Патрик прославлен в том числе тем, что изгнал из Ирландии змей, а символ Слизерина как раз змея.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"https://i.redd.it/032gzvo6iln61.jpg\",\"authors\":[{\"id\":7091,\"name\":\"Вера Потопаева\",\"gender\":\"SE\"}],\"editors\":[{\"id\":6406,\"name\":\"Михаил Фрухт\",\"gender\":\"HE\"},{\"id\":7091,\"name\":\"Вера Потопаева\",\"gender\":\"SE\"},{\"id\":12165,\"name\":\"Дарья Широкова\",\"gender\":\"SE\"}],\"tour\":{\"id\":23597,\"number\":4,\"title\":\"\"},\"packId\":5504,\"packTitle\":\"V Открытый Кубок 57 школы\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":2,\"pubDate\":\"2023-08-16 17:48:07.954806\",\"endDate\":\"2023-03-05 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":374085,\"number\":9,\"text\":\"Нил Гейман перенес действие произведения из наших дней в Англию 17 века. Его герой посещает колледж мастера Каро\u0301луса, девиз которого — латинская фраза, означающая «все меняется, и мы меняемся». Назовите фамилию мастера Каролуса.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Ксавье\u0301.\",\"answerPic\":\"\",\"zachet\":\"Хавье\u0301р, Ксавериус, Xavier, Javier, Xaverius или любая другая узнаваемая версия этого имени.\",\"nezachet\":\"\",\"comment\":\"в комиксе Геймана «Марвел, 1602 год» супергерои действуют в декорациях времен Шекспира. Школу для мутантов — «людей Икс» — возглавляет тот же профессор Чарльз Ксавье, только в этой версии его фамилия пишется на испанский лад. Слово «мутант» тогда не использовалось, но намек на него — в латинском девизе, который начинается со слов omnia mutantur [о\u0301мния мута\u0301нтур].\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"Neil Gaiman, Marvel 1602 (Marvel, 2019), p.41\",\"authors\":[{\"id\":803,\"name\":\"Игорь Мокин\",\"gender\":\"HE\"}],\"editors\":[{\"id\":803,\"name\":\"Игорь Мокин\",\"gender\":\"HE\"}],\"tour\":{\"id\":22964,\"number\":1,\"title\":\"\"},\"packId\":5350,\"packTitle\":\"Фонтан: Оранжевый\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2023-03-28 14:37:22\",\"endDate\":\"2023-03-02 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[70,29],\"complexity\":[32.86,34.48],\"correct_answers\":[23,10],\"tournaments\":[{\"id\":8813,\"title\":\"Фонтан: Оранжевый\",\"typeoft\":{\"id\":3,\"title\":\"Синхрон\"}},{\"id\":8862,\"title\":\"Фонтан: Оранжевый (асинхрон)\",\"typeoft\":{\"id\":8,\"title\":\"Асинхрон\"}}]},{\"id\":414124,\"number\":22,\"text\":\"Какой известный профессор носит эту модель часов с особой защитой?\",\"razdatkaText\":\"Rolex Milgauss\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Профессор Икс.\",\"answerPic\":\"\",\"zachet\":\"Профессор X, Чарльз Ксавьер.\",\"nezachet\":\"\",\"comment\":\"Компания «Ролекс» разработала часы для учёных и инженеров, имеющих дело с\u00a0магнитными полями: название говорит, что они выдерживают воздействие магнитного поля до\u00a0тысячи гауссов, тогда как на точность обычных часов легко влияет поле в 50–100 гауссов. Гаусс — названная в честь учёного единица магнитной индукции (одна тесла — 10 тысяч гауссов). Главный визави этого профессора — Магнето, и это Профессор Икс, он же Чарльз Ксавьер из «Людей Икс».\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. https://www.imdb.com/title/tt6565702/trivia?item=tr4577760\\\\n2. https://www.rolex.com/watches/milgauss.html\",\"authors\":[{\"id\":119,\"name\":\"Константин Сахаров\",\"gender\":\"HE\"}],\"editors\":[{\"id\":119,\"name\":\"Константин Сахаров\",\"gender\":\"HE\"}],\"tour\":{\"id\":26492,\"number\":2,\"title\":\"\"},\"packId\":6258,\"packTitle\":\"Научпоп\",\"controversials\":[{\"id\":182701,\"answer\":\"Магнето\",\"status\":\"D\",\"comment\":\"None\",\"appealJuryComment\":\"None\"},{\"id\":184166,\"answer\":\"магнето\",\"status\":\"D\",\"comment\":\"None\",\"appealJuryComment\":\"None\"}],\"appeals\":[],\"totalLikes\":3,\"totalDislikes\":3,\"pubDate\":\"2025-03-28 19:21:04.439771\",\"endDate\":\"2022-12-21 22:55:00\",\"uploader\":28,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[54,51],\"complexity\":[59.26,56.86],\"correct_answers\":[32,29],\"tournaments\":[{\"id\":8177,\"title\":\"Научпоп\",\"typeoft\":{\"id\":3,\"title\":\"Синхрон\"}},{\"id\":8603,\"title\":\"Научпоп (асинхрон/онлайн)\",\"typeoft\":{\"id\":8,\"title\":\"Асинхрон\"}}]},{\"id\":370746,\"number\":32,\"text\":\"На судах нацистские преступники говорили, что всего лишь выполняли приказы. Кристин Осазува не только называет главного виновника, но и проводит параллель между приказами и ИКСОМ. Через минуту вы напишете целиком слово, в котором мы заменили шесть букв одной.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"империусом\",\"answerPic\":\"\",\"zachet\":\"империус\",\"nezachet\":\"\",\"comment\":\"понять, врут преступники или нет, было чрезвычайно сложно, и примерно пятая часть обвинительных приговоров была смягчена или вообще отменена. В четвёртом фильме о Гарри Поттере профессор по защите от тёмных искусств рассказывал, что на судах многие сторонники Волан-де-Морта заявляли, что действовали под влиянием подчиняющего заклинания «империус». Формой вопроса мы постарались наложить на вас заклятие, чтобы вы точно сдали правильный ответ. Но упоминать в вопросе «того, кого нельзя называть» всё-таки не стали.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. https://youtu.be/VoInDuvraJg\\u2028\\\\r\\\\n2. http://christineosazuwa.com/cv_portfolio/harry-potter/\",\"authors\":[{\"id\":66,\"name\":\"Алексей Полевой\",\"gender\":\"HE\"}],\"editors\":[{\"id\":66,\"name\":\"Алексей Полевой\",\"gender\":\"HE\"},{\"id\":67,\"name\":\"Денис Рыбачук\",\"gender\":\"HE\"},{\"id\":308,\"name\":\"Дмитрий Родионов\",\"gender\":\"HE\"},{\"id\":449,\"name\":\"Павел Столяров\",\"gender\":\"HE\"}],\"tour\":{\"id\":22679,\"number\":2,\"title\":\"Второй блок \"},\"packId\":5269,\"packTitle\":\"Кубок Бесконечности. Этап III: Камень Пространства\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":1,\"pubDate\":\"2023-01-11 00:00:00\",\"endDate\":\"2022-11-23 10:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[151,39],\"complexity\":[13.91,10.26],\"correct_answers\":[21,4],\"tournaments\":[{\"id\":8442,\"title\":\"Кубок Бесконечности: третий этап (синхрон)\",\"typeoft\":{\"id\":3,\"title\":\"Синхрон\"}},{\"id\":8443,\"title\":\"Кубок Бесконечности: третий этап. Онлайн и асинхрон\",\"typeoft\":{\"id\":8,\"title\":\"Асинхрон\"}}]},{\"id\":372432,\"number\":74,\"text\":\"В соревновании, однажды проведённом в Массачусетском технологическом институте, надо было написать на доске число большее, чем у соперника. Один из участников в свой ход написал в ряд несколько десятков единиц, а другой в ответ провёл по доске пальцем, чтобы осталось две единицы и множество ИКСОВ. Назовите ИКС.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"факториал.\",\"answerPic\":\"\",\"zachet\":\"восклицательный знак; !.\",\"nezachet\":\"\",\"comment\":\"единицы были записаны палочками без хвостика, благодаря чему Адам Эльга легко превратил их в восклицательные знаки. Учитывая, что факториал натурального числа обозначает произведение всех натуральных чисел от 1 до этого числа, планка была задрана довольно высоко. Впрочем, соперник Эльги и другой профессор MIT Агустин Райо всё же его обставил.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. https://www.youtube.com/watch?v=X3l0fPHZja8\\\\n2. https://googology.fandom.com/wiki/Big_Number_Duel\",\"authors\":[{\"id\":541,\"name\":\"Дмитрий Хмыров\",\"gender\":\"HE\"}],\"editors\":[{\"id\":541,\"name\":\"Дмитрий Хмыров\",\"gender\":\"HE\"}],\"tour\":{\"id\":22821,\"number\":5,\"title\":\"\"},\"packId\":5309,\"packTitle\":\"MGIMO Cybernational — 2022\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2023-02-23 00:00:00\",\"endDate\":\"2022-10-09 15:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[102],\"complexity\":[65.69],\"correct_answers\":[67],\"tournaments\":[{\"id\":8519,\"title\":\"MGIMO Cybernational\",\"typeoft\":{\"id\":2,\"title\":\"Обычный\"}}]},{\"id\":370880,\"number\":21,\"text\":\"По слухам, Уильям Додд был назначен послом США в Германии случайно — мол, Рузвельт собирался предложить этот пост Уолтеру Додду. Из-за этого Уильям Додд получил прозвище «посол из ИКСА». Назовите ИКС двумя словами, начинающимися на соседние буквы алфавита.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"телефонный справочник.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"ходили слухи, что Рузвельт просто ошибся и набрал номер не того У. Додда по телефонному справочнику, да и в целом профессор истории Уильям Додд выглядел очень неочевидной кандидатурой на роль посла. Впрочем, Эдвард Флинн, распространявший эти слухи, также претендовал на этот пост, так что, скорее всего, он просто злословил относительно более удачливого конкурента.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"Эрик Ларсон. В саду чудовищ: любовь и террор в гитлеровском Берлине.\",\"authors\":[{\"id\":43,\"name\":\"Руслан Хаиткулов\",\"gender\":\"HE\"}],\"editors\":[{\"id\":6,\"name\":\"Сергей Терентьев\",\"gender\":\"HE\"},{\"id\":43,\"name\":\"Руслан Хаиткулов\",\"gender\":\"HE\"}],\"tour\":{\"id\":22690,\"number\":2,\"title\":\"\"},\"packId\":5272,\"packTitle\":\"Енисейская знать - 2022\",\"controversials\":[],\"appeals\":[],\"totalLikes\":1,\"totalDislikes\":0,\"pubDate\":\"2023-01-19 00:00:00\",\"endDate\":\"2022-09-25 15:00:00\",\"uploader\":1,\"tags\":[{\"id\":2,\"title\":\"насоседние\"}],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[45],\"complexity\":[44.44],\"correct_answers\":[20],\"tournaments\":[{\"id\":8507,\"title\":\"Енисейская Знать - 2022\",\"typeoft\":{\"id\":2,\"title\":\"Обычный\"}}]},{\"id\":366745,\"number\":35,\"text\":\"Слова “ИКС” и “ТАК” — это замены. “Маленький профессор” — это обучающая игрушка для младших школьников, выполненная в виде ИКСА. Можно сказать, что “Маленький профессор” — это ИКС ТАК. Напишите ИКС ТАК.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"ротялукьлак\",\"answerPic\":\"\",\"zachet\":\"с незначительными отклонениями\",\"nezachet\":\"\",\"comment\":\"игрушка задает математические задачи, которые нужно решить в уме и ввести ответ. ИКС — калькулятор. ТАК — наоборот.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"https://en.wikipedia.org/wiki/Little_Professor\",\"authors\":[{\"id\":5401,\"name\":\"Константин Ильин\",\"gender\":\"HE\"},{\"id\":12130,\"name\":\"Артур Альтергот\",\"gender\":\"HE\"}],\"editors\":[{\"id\":5401,\"name\":\"Константин Ильин\",\"gender\":\"HE\"}],\"tour\":{\"id\":22333,\"number\":3,\"title\":\"\"},\"packId\":5187,\"packTitle\":\"Всё будет Украина 3!\",\"controversials\":[{\"id\":178308,\"answer\":\"ретюьпмок\",\"status\":\"D\",\"comment\":\"\",\"appealJuryComment\":\"None\"}],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2022-10-14 00:00:00\",\"endDate\":\"2022-09-19 23:55:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[19],\"complexity\":[10.53],\"correct_answers\":[2],\"tournaments\":[{\"id\":8137,\"title\":\"Всё будет Украина 3!\",\"typeoft\":{\"id\":8,\"title\":\"Асинхрон\"}}]},{\"id\":387242,\"number\":16,\"text\":\"Марина Цветаева писала, что Пушкинский музей — это многолетний бессре\u0301бреный труд её отца и три таких же бессребреных ИКСА Юрия Нечаева-Мальцова. Назовите ИКС словом из семи букв.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Миллион.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Профессор Московского университета Иван Цветаев и меценат Юрий Нечаев Мальцов оставили потомкам добрую память о себе. Правда, менее субъективные источники указывают, что сумма была меньше — миллиона два с половиной. Но именно благодаря этим средствам музейный долгострой был завершён. Бессре\u0301брениками, или бессере\u0301брениками, обычно называют тех, кто равнодушен к богатству, но меценат явно был не из таких.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"https://vedom.ru/news/2019/06/05/35332-stekolnyj-oligarh-zastavlyal-professora-est\",\"authors\":[{\"id\":367,\"name\":\"Игорь Демьянцев\",\"gender\":\"HE\"}],\"editors\":[{\"id\":367,\"name\":\"Игорь Демьянцев\",\"gender\":\"HE\"}],\"tour\":{\"id\":24130,\"number\":3,\"title\":\"Блок 3\"},\"packId\":5639,\"packTitle\":\"Куб-финал. Гиперкуб\",\"controversials\":[{\"id\":171970,\"answer\":\"капитал\",\"status\":\"D\",\"comment\":\"None\",\"appealJuryComment\":\"None\"},{\"id\":171971,\"answer\":\"гонорар\",\"status\":\"D\",\"comment\":\"None\",\"appealJuryComment\":\"None\"},{\"id\":171847,\"answer\":\"меценат\",\"status\":\"D\",\"comment\":\"None\",\"appealJuryComment\":\"None\"}],\"appeals\":[],\"totalLikes\":1,\"totalDislikes\":6,\"pubDate\":\"2023-12-03 21:03:15\",\"endDate\":\"2022-06-15 23:55:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[91,44],\"complexity\":[15.39,18.18],\"correct_answers\":[14,8],\"tournaments\":[{\"id\":7948,\"title\":\"Куб-финал. Гиперкуб\",\"typeoft\":{\"id\":3,\"title\":\"Синхрон\"}},{\"id\":8027,\"title\":\"Куб-финал. Гиперкуб (асинхрон/онлайн)\",\"typeoft\":{\"id\":8,\"title\":\"Асинхрон\"}}]},{\"id\":367092,\"number\":39,\"text\":\"Советуем вам включить мозг. Чтобы связаться со своей девушкой из другого штата герой-гик из одного сериала изобретает радиостанцию, многократно усиливающую функционал обычной станции. Название изобретённой станции отсылает к детищу Чарльза и Эрика. Напишите это название.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Cerebro [цере\u0301бро].\",\"answerPic\":\"\",\"zachet\":\"Церебро.\",\"nezachet\":\"\",\"comment\":\"в серии комиксов «Люди Икс» Чарльз Ксавьер, более известный как Профессор Икс, и Эрик Леншер, более известный как Магнето, создали установку, усиливающую поиск мутантов на большом расстоянии. В сериале «Очень странные дела» усиливающая радиоустановка Да\u0301стина для связи с его подружкой Сьюзи получила такое же название. Слова «включить мозг» — небольшая подсказка, ведь название «Цере\u0301бро» происходит от латинского слова cerebrum [цере\u0301брум] — мозг. \\\\nИсточники: \\\\n1. Сериал «Stranger Things», сезон 3, эпизод 1 «Chapter One: Suzie, Do You Copy?».\\\\n2. https://en.wikipedia.org/wiki/Cerebro\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"\",\"authors\":[{\"id\":438,\"name\":\"Александр Евтушков\",\"gender\":\"HE\"}],\"editors\":[{\"id\":438,\"name\":\"Александр Евтушков\",\"gender\":\"HE\"}],\"tour\":{\"id\":22358,\"number\":4,\"title\":\"\"},\"packId\":5192,\"packTitle\":\"Студенческий чемпионат Архангельской области 2022.\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2022-10-07 00:00:00\",\"endDate\":\"2022-03-13 13:30:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[16],\"complexity\":[43.75],\"correct_answers\":[7],\"tournaments\":[{\"id\":7901,\"title\":\"СЧАО —\u00a02022\",\"typeoft\":{\"id\":2,\"title\":\"Обычный\"}}]},{\"id\":362870,\"number\":6,\"text\":\"В одном издании романа «Гарри Поттер и философский камень» чтобы подчеркнуть, например, аккуратность профессора Макгонагалл и прямолинейность Хагрида, использовались разные ИКСЫ. Назовите ИКС словом немецкого происхождения.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"шрифт.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"в тексте книги встречаются письма и записки разных героев. Эти письма набраны разными шрифтами, имитирующими почерк, соответствующий характеру персонажа. Например, у Хагрида почерк грубый и размашистый, а у Макгонагалл – аккуратный.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"https://screenrant.com/harry-potter-philosopher-sorcerer-stone-differences/\",\"authors\":[{\"id\":12109,\"name\":\"Алеся Заботина\",\"gender\":\"HE\"}],\"editors\":[{\"id\":27,\"name\":\"Андрей Волков\",\"gender\":\"HE\"}],\"tour\":{\"id\":22022,\"number\":1,\"title\":\"Блок 1\"},\"packId\":5107,\"packTitle\":\"Молодёжный кубок мира. Сезон 2021-2022. 6 тур\",\"controversials\":[],\"appeals\":[],\"totalLikes\":1,\"totalDislikes\":0,\"pubDate\":\"2022-07-24 00:00:00\",\"endDate\":\"2022-02-13 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":397764,\"number\":36,\"text\":\"Профессор Хидэсабýро Уэно скоропостижно скончался в аудитории Токийского университета в возрасте 53-х лет от инсульта... Вне Японии Уэно стал известен благодаря ИКСу. Назовите ИКСа словом, содержащим числительное.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Хатико\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"однажды профессор не вернулся с работы домой… Уэно был владельцем пса Хатико, девять лет ожидавшего возвращения хозяина на станции Сибуя. Имя пса содержит числительное «восемь» (яп. Хати) – это была восьмая по счету собака профессора.\\\\nИгра закончена. Большое спасибо всем. Возвращайтесь к тем, кто вас ждет.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. https://ru.wikipedia.org/wiki/Уэно,_Хидэсабуро\\\\n2. https://ru.wikipedia.org/wiki/Хатико\",\"authors\":[{\"id\":793,\"name\":\"Евгений Кононенко\",\"gender\":\"HE\"}],\"editors\":[{\"id\":793,\"name\":\"Евгений Кононенко\",\"gender\":\"HE\"}],\"tour\":{\"id\":25028,\"number\":3,\"title\":\"\"},\"packId\":5882,\"packTitle\":\"Другой Старый Свет\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":5,\"pubDate\":\"2024-05-29 07:50:05\",\"endDate\":\"2021-12-18 14:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[54],\"complexity\":[50],\"correct_answers\":[27],\"tournaments\":[{\"id\":7501,\"title\":\"Другой Старый свет\",\"typeoft\":{\"id\":3,\"title\":\"Синхрон\"}}]},{\"id\":356915,\"number\":5,\"text\":\"В 1884 году профессор Уильям Пе\u0301нкост выбрал самого красивого студента, и тот стал одним из первых ИКСов в истории. ИКС Джоэл Маки\u0301рнан смог освободиться от регулярных платежей только через Верховный суд США. Какие два слова мы заменили словом «ИКС»?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"донор спермы.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Пенкост провёл процедуру по просьбе бесплодного торговца, который очень хотел детей от жены. Подобно тому, как и сегодня доноров спермы часто отбирают по внешности, Пенкост решил, что первым из них станет самый красивый из его студентов. Жена так и не узнала, что родила не от мужа, а имя студента не знаем даже мы. Джоэл Макирнан договорился со своей подругой, что выступит для неё донором спермы и откажется от родительских прав, но спустя несколько лет она потребовала от него алименты. Разбирательство дошло до Верховного Суда США, который все же освободил его от выплат.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. https://en.wikipedia.org/wiki/Sperm_donation\u00a0\\\\r\\\\n2. https://en.wikipedia.org/wiki/Ferguson_v._McKiernan\",\"authors\":[{\"id\":269,\"name\":\"Руслан Алиев\",\"gender\":\"HE\"}],\"editors\":[{\"id\":269,\"name\":\"Руслан Алиев\",\"gender\":\"HE\"}],\"tour\":{\"id\":21586,\"number\":1,\"title\":\"\"},\"packId\":4988,\"packTitle\":\"Кубок Гармонии. Элемент Первый: Щедрость\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2021-12-15 00:00:00\",\"endDate\":\"2021-12-15 23:55:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[35,57],\"complexity\":[80,84.21],\"correct_answers\":[28,48],\"tournaments\":[{\"id\":7549,\"title\":\"Кубок Гармонии. Элемент Первый: Щедрость (синхрон)\",\"typeoft\":{\"id\":3,\"title\":\"Синхрон\"}},{\"id\":7550,\"title\":\"Кубок Гармонии. Элемент Первый: Щедрость (асинхрон)\",\"typeoft\":{\"id\":8,\"title\":\"Асинхрон\"}}]},{\"id\":395028,\"number\":38,\"text\":\"Модернизировать гемино\u0301ида дорого, поэтому 52-летний Хироши Ишигуро прибегает к ИКСУ.  Согласно некоторым исследованиям, люди, использовавшие ИКС, утрачивают способность сопереживать окружающим. Назовите ИКС.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"/pics/5816/395028_razdatka.png\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Ботокс\",\"answerPic\":\"\",\"zachet\":\"укол ботокса и т.п. по смыслу с упоминанием слова «ботокс»\",\"nezachet\":\"\",\"comment\":\"Японскому профессору дешевле пройти косметическую процедуру, чем создавать нового робота-близнеца, добавляя морщины. Согласно теории, которую поддерживают результаты исследований, из-за нарушенной иннервации мимической мускулатуры теряется способность к эмпатии.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. Человек мира с Андреем Понкратовым. Японский альбом. Часть 3. [Электронный ресурс]. — Режим доступа: URL: http://spp.sagepub.com/content/early/2011/04/21/1948550611406138.abstract\\\\n2. Social Psychological and Personality Science, журнал\",\"authors\":[{\"id\":13117,\"name\":\"Дмитрий Турпаков\",\"gender\":\"HE\"}],\"editors\":[{\"id\":762,\"name\":\"Алексей Хмельков\",\"gender\":\"HE\"}],\"tour\":{\"id\":24792,\"number\":4,\"title\":\"\"},\"packId\":5816,\"packTitle\":\"Octobearfest — 2021\",\"controversials\":[],\"appeals\":[],\"totalLikes\":2,\"totalDislikes\":1,\"pubDate\":\"2024-03-11 19:41:01\",\"endDate\":\"2021-10-03 15:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[29],\"complexity\":[48.28],\"correct_answers\":[14],\"tournaments\":[{\"id\":7366,\"title\":\"Octobearfest\",\"typeoft\":{\"id\":2,\"title\":\"Обычный\"}}]},{\"id\":395029,\"number\":39,\"text\":\"Профессор Рейтер считал, что Бетховен, вероятно, был отравлен собственным врачом, лечившим композитора при помощи солей. Эту догадку Йорг Ци\u0301глау описывает в главе, название которой начинается со слов «От симфонии до ИКСА». Назовите ИКС двумя словами по-русски или по-английски.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"тяжёлый металл\",\"answerPic\":\"\",\"zachet\":\"хеви метал, Heavy Metal\",\"nezachet\":\"\",\"comment\":\"в волосах Бетховена было обнаружено чрезвычайно высокое содержание тяжёлого металла свинца, соли которого, как считалось, растворяют слизь. А тяжёлый металл, как известно, не только химический термин, но и музыкальный жанр.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"Йорг Циттлау «Могло быть и хуже».\",\"authors\":[{\"id\":13117,\"name\":\"Дмитрий Турпаков\",\"gender\":\"HE\"}],\"editors\":[{\"id\":762,\"name\":\"Алексей Хмельков\",\"gender\":\"HE\"}],\"tour\":{\"id\":24792,\"number\":4,\"title\":\"\"},\"packId\":5816,\"packTitle\":\"Octobearfest — 2021\",\"controversials\":[],\"appeals\":[],\"totalLikes\":2,\"totalDislikes\":1,\"pubDate\":\"2024-03-11 19:41:01\",\"endDate\":\"2021-10-03 15:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[29],\"complexity\":[0],\"correct_answers\":[0],\"tournaments\":[{\"id\":7366,\"title\":\"Octobearfest\",\"typeoft\":{\"id\":2,\"title\":\"Обычный\"}}]},{\"id\":354436,\"number\":28,\"text\":\"Уже в 1893 году Карл Стёрмер подходил к людям поздороваться, после чего дёргал за цепочку в кармане жилетки. Карла Стёрмера считают одним из первых ИКСов. Назовите ИКСа словом с удвоенной согласной.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"папара\u0301цци\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"в кармане Стёрмера была скрытая камера, которая и приводилась в действие цепочкой. Он подходил к знаменитым жителям Осло и фотографировал их. Многие не догадывались о его цели, но один профессор всё же понял его замысел и дал резкий отпор, хотя Стёрмер успел его сфотографировать, и фото даже сохранилось. Сам термин «папарацци» появился уже спустя 67 лет, когда в фильме Фелли\u0301ни «Сладкая жизнь» был показан фотограф с такой фамилией.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"https://birdinflight.com/ru/vdohnovenie/resursy/20180105-carl-stormer.html\",\"authors\":[{\"id\":269,\"name\":\"Руслан Алиев\",\"gender\":\"HE\"}],\"editors\":[{\"id\":269,\"name\":\"Руслан Алиев\",\"gender\":\"HE\"}],\"tour\":{\"id\":21373,\"number\":4,\"title\":\"Четвертый блок\"},\"packId\":4927,\"packTitle\":\"Memel Spiegel. Teil 2\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2021-09-26 00:00:00\",\"endDate\":\"2021-09-25 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[58],\"complexity\":[72.41],\"correct_answers\":[42],\"tournaments\":[{\"id\":7331,\"title\":\"Memel Spiegel. Teil 2\",\"typeoft\":{\"id\":8,\"title\":\"Асинхрон\"}}]},{\"id\":368173,\"number\":86,\"text\":\"Дуплет. Два вопроса по 30 секунд обсуждения на каждыи\u0306.\\\\n[Раздаточныи\u0306 материал:\\\\n1. «Великолепная семе\u0308рка» — фильм шестидесятых годов с Юлом Бри\u0301ннером в главнои\u0306 роли. Известныи\u0306 автор признавался, что благодаря этому фильму появился преподаватель университета Колумбия. Назовите этого преподавателя.\\\\n2. «Грязная дюжина» — фильм шестидесятых годов. Один из постеров к НЕМУ стилизован под афишу «Грязнои\u0306 дюжины». Назовите ЕГО двумя словами.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"/pics/5214/368173_razdatka.png\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"1. [Чарльз] Ксавьер;\\\\r\\\\n2. «Отряд самоубии\u0306ц».\",\"answerPic\":\"\",\"zachet\":\"1. Профессор Х [икс];\\\\r\\\\n2. «Suicide squad» [суиса\u0301и\u0306д скуа\u0301д].\",\"nezachet\":\"\",\"comment\":\"Стэн Ли признавался, что лысыи\u0306 из «Марвел» появился под впечатлением от лысого из «Великолепнои\u0306 семе\u0308рки»: и тот, и другои\u0306 набирают команду для борьбы с преступниками. Режиссе\u0308р грядущего «Отряда самоубии\u0306ц» отдал дань уважения классическому боевику с похожеи\u0306 фабулои\u0306: и там, и там опасную миссию поручают команде бывших арестантов. Немного тривии: Чарльз Бронсон был единственным общим участником «Семе\u0308рки» и «Дюжины».\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"https://books.google.ru/books?id=zLmB3GprtboC\\u0026pg=PT170 https://www.slashfilm.com/the-suicide-squad-poster-dirty-dozen/\",\"authors\":[{\"id\":181,\"name\":\"Николай Коврижных\",\"gender\":\"HE\"}],\"editors\":[{\"id\":105,\"name\":\"Антон Саксонов\",\"gender\":\"HE\"},{\"id\":109,\"name\":\"Андрей Скиренко\",\"gender\":\"HE\"},{\"id\":134,\"name\":\"Михаил Папков\",\"gender\":\"HE\"},{\"id\":312,\"name\":\"Эдуард Шагал\",\"gender\":\"HE\"},{\"id\":354,\"name\":\"Наталья Комар\",\"gender\":\"SE\"},{\"id\":355,\"name\":\"Ольга Сарницкая\",\"gender\":\"SE\"}],\"tour\":{\"id\":22445,\"number\":7,\"title\":\"Шестои\u0306 тур.\"},\"packId\":5214,\"packTitle\":\"Студенческий чемпионат Беларуси\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2022-11-07 00:00:00\",\"endDate\":\"2021-05-23 15:00:00\",\"uploader\":1,\"tags\":[{\"id\":5,\"title\":\"дуплет\"}],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[33],\"complexity\":[0],\"correct_answers\":[0],\"tournaments\":[{\"id\":6862,\"title\":\"Студенческий чемпионат Беларуси\",\"typeoft\":{\"id\":2,\"title\":\"Обычный\"}}]},{\"id\":368152,\"number\":65,\"text\":\"В этом вопросе ИКС заменяет другое слово. Многие фанаты возмутились, узнав новыи\u0306 факт биографии одного из главных героев серии книг. В связи с этим Стивен Кольбе\u0301р отмечает, что, хотя и раньше литературные персонажи оказывались в ИКСе, обычно они были на пути... куда?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"[в] Нарнию.\",\"answerPic\":\"\",\"zachet\":\"в любом падеже.\",\"nezachet\":\"\",\"comment\":\"новость о том, что профессор Дамблдор из саги о Гарри Поттере является геем, удивила многих. Стивен Кольбер обыгрывает выражение «выход из шкафа» как синоним совершения каминг-аута. Во вселеннои\u0306 Клаи\u0306ва Лью\u0301иса, выходя из шкафа, попадали в Нарнию.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. мнение большинства известных автору фанатов саги.\\\\n2. https://www.youtube.com/watch?v=bsWzUn4dKsI\",\"authors\":[{\"id\":213,\"name\":\"Владимир Осипчук\",\"gender\":\"HE\"}],\"editors\":[{\"id\":213,\"name\":\"Владимир Осипчук\",\"gender\":\"HE\"}],\"tour\":{\"id\":22444,\"number\":6,\"title\":\"Пятыи\u0306 тур.\"},\"packId\":5214,\"packTitle\":\"Студенческий чемпионат Беларуси\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2022-11-07 00:00:00\",\"endDate\":\"2021-05-23 15:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[33],\"complexity\":[63.64],\"correct_answers\":[21],\"tournaments\":[{\"id\":6862,\"title\":\"Студенческий чемпионат Беларуси\",\"typeoft\":{\"id\":2,\"title\":\"Обычный\"}}]},{\"id\":1140,\"number\":0,\"text\":\"Существует сюжетная линия, где известному персонажу противостоит злодей по прозвищу «Профессор Сатл», чья фамилия означает «неявный». Назовите этого персонажа двумя словами.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Капитан Очевидность.\",\"answerPic\":\"\",\"zachet\":\"Captain Obvious.\",\"nezachet\":\"\",\"comment\":\"фанаты Капитана Очевидность написали ему комикс-биографию. Согласно этой биографии, супергерой «Капитан Очевидность» противостоит злому профессору, чью фамилию можно перевести как «неочевидный».\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"https://uncyclopedia.ca/wiki/Captain_Obvious\",\"authors\":[{\"id\":105,\"name\":\"Антон Саксонов\",\"gender\":\"HE\"}],\"editors\":[{\"id\":105,\"name\":\"Антон Саксонов\",\"gender\":\"HE\"}],\"tour\":{\"id\":95,\"number\":1,\"title\":\"\"},\"packId\":25,\"packTitle\":\"Бесконечные Земли: том IX\",\"controversials\":[],\"appeals\":[],\"totalLikes\":1,\"totalDislikes\":0,\"pubDate\":\"2021-03-26 00:00:00\",\"endDate\":\"2021-02-09 23:55:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[210],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[{\"id\":6878,\"title\":\"Онлайн: Бесконечные Земли. Том IX\",\"typeoft\":{\"id\":8,\"title\":\"Асинхрон\"}}]},{\"id\":2313,\"number\":3,\"text\":\"Профессор оксфордского университета Брайан Сайкс полагает, что ИМ может быть гибрид полярного и бурого медведей, оказавшийся значительно южнее обычного ареала обитания. Назовите ЕГО несклоняемым словом.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Йети\",\"answerPic\":\"\",\"zachet\":\"Точный ответ\",\"nezachet\":\"\",\"comment\":\"Профессор исследовал ДНК шерсти, обнаруженной в Гималаях, и пришел к выводу, что эта шерсть принадлежит не снежному человеку, а упомянутому гибриду белого и бурого медведей, который мог жить в том регионе некоторое время назад, что и стало поводом для появления легенды о йети. Исследование вполне характерно для британского учёного.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"https://www.bbc.com/russian/science/2013/10/131017_uk_yeti_research\",\"authors\":[{\"id\":85,\"name\":\"Максим Мозуль\",\"gender\":\"HE\"}],\"editors\":[{\"id\":85,\"name\":\"Максим Мозуль\",\"gender\":\"HE\"}],\"tour\":{\"id\":184,\"number\":1,\"title\":\"\"},\"packId\":48,\"packTitle\":\"Кубок Оливье\",\"controversials\":[],\"appeals\":[],\"totalLikes\":1,\"totalDislikes\":0,\"pubDate\":\"2021-01-27 00:00:00\",\"endDate\":\"2021-01-29 14:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[351],\"complexity\":[85.47],\"correct_answers\":[300],\"tournaments\":[{\"id\":6887,\"title\":\"Кубок Оливье\",\"typeoft\":{\"id\":8,\"title\":\"Асинхрон\"}}]},{\"id\":3998,\"number\":15,\"text\":\"Будущий нобелевский лауреат мечтал заниматься творчеством, но пошёл по стопам отца-профессора и во второй половине XIX века подготовил к изданию ИКС. Назовите ИКС двумя словами, начинающимися на одну и ту же букву.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"анатомический атлас.\",\"answerPic\":\"\",\"zachet\":\"точный ответ.\",\"nezachet\":\"\",\"comment\":\"при создании анатомического атласа Сантьяго Рамон-и-Кахалю (лауреат Нобелевской премии по физиологии и медицине за 1906 год) очень пригодились навыки художника.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"https://ru.wikipedia.org/wiki/Рамон-и-Кахаль,_Сантьяго\",\"authors\":[{\"id\":67,\"name\":\"Денис Рыбачук\",\"gender\":\"HE\"}],\"editors\":[{\"id\":66,\"name\":\"Алексей Полевой\",\"gender\":\"HE\"},{\"id\":67,\"name\":\"Денис Рыбачук\",\"gender\":\"HE\"}],\"tour\":{\"id\":322,\"number\":2,\"title\":\"\"},\"packId\":84,\"packTitle\":\"Онлайн: Бесконечные Земли. Том V\",\"controversials\":[{\"id\":133385,\"answer\":\"учебник урологии\",\"status\":\"D\",\"comment\":\"\",\"appealJuryComment\":\"None\"}],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":1,\"pubDate\":\"2020-12-22 00:00:00\",\"endDate\":\"2020-10-20 23:55:00\",\"uploader\":1,\"tags\":[{\"id\":1,\"title\":\"наоднубукву\"}],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[188],\"complexity\":[70.75],\"correct_answers\":[133],\"tournaments\":[{\"id\":6706,\"title\":\"Онлайн: Бесконечные Земли. Том V\",\"typeoft\":{\"id\":8,\"title\":\"Асинхрон\"}}]},{\"id\":389292,\"number\":28,\"text\":\"Поначалу коллеги называли ЕГО жи\u0301голо и принцем-консо\u0301ртом. В комиксе «Химери\u0301ческая бригада» ЕГО тёща руководит институтом, в котором обучаются мутанты. Назовите ЕГО.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Фредери\u0301к Жолио\u0301-Кюри\u0301.\",\"answerPic\":\"\",\"zachet\":\"по фамилии; Жолио.\",\"nezachet\":\"\",\"comment\":\"выдающегося французского учёного, будущего лауреата Нобелевской премии, обвиняли в том, что его женитьба на дочери Марии Склодо\u0301вской-Кюри\u0301 обусловлена карьерными соображениями, и ни о любви, ни о научном таланте говорить в данном случае не стоит. В комиксе Се\u0301ржа Лема\u0301на и Фабри\u0301са Коле\u0301на, созданном в жанре ра\u0301диум-па\u0301нк, «королева радия» Мария Кюри, подобно профессору Ксавье\u0301, собирает под крышей своего института мутантов с паранормальными способностями.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. https://www.aip.org/history-programs/niels-bohr-library/oral-histories/4717-2\\\\n2. https://ru.wikipedia.org/wiki/Жолио-Кюри,_Фредерик\\\\n3. https://fr.wikipedia.org/wiki/La_Brigade_chimérique\\\\n4. https://ru.wikipedia.org/wiki/Профессор_Икс\",\"authors\":[{\"id\":47,\"name\":\"Александр Кудрявцев\",\"gender\":\"HE\"},{\"id\":184,\"name\":\"Игорь Коршовский\",\"gender\":\"HE\"}],\"editors\":[{\"id\":47,\"name\":\"Александр Кудрявцев\",\"gender\":\"HE\"}],\"tour\":{\"id\":24312,\"number\":3,\"title\":\"\"},\"packId\":5691,\"packTitle\":\"Синхрон с человеческим лицом VII\",\"controversials\":[],\"appeals\":[],\"totalLikes\":2,\"totalDislikes\":0,\"pubDate\":\"2023-12-15 01:10:54.126555\",\"endDate\":\"2020-09-27 23:00:00\",\"uploader\":470,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[119],\"complexity\":[15.13],\"correct_answers\":[18],\"tournaments\":[{\"id\":5969,\"title\":\"Онлайн: Синхрон с человеческим лицом VII\",\"typeoft\":{\"id\":8,\"title\":\"Асинхрон\"}}]},{\"id\":7766,\"number\":31,\"text\":\"Блиц. 3 вопроса по 20 секунд обсуждения.\\\\n1. После успеха дебютного фильма Джон и Джордж поругались, и Джон сохранил за собой права на словосочетание «ПЕРВЫЕ ВТОРЫЕ». Джон пока ещё ПЕРВЫЙ. Назовите ПЕРВЫХ.\\\\n2. Профессор Шарль Рише считал ИКСОВ психопатами, которые страдают от расщепления сознания. Назовите ИКСА словом латинского происхождения.\\\\n3. После успеха дебютного фильма Джон и Джордж поругались, и из названий сиквелов Джорджа пропало слово «ПЕРВЫЕ». Джордж стал ВТОРЫМ в 2017 году. Назовите ВТОРЫХ.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"1) живые. 2) медиум. 3) мертвецы.\",\"answerPic\":\"\",\"zachet\":\"1) living. 2) спирит; спиритуалист. 3) мёртвые; dead.\",\"nezachet\":\"\",\"comment\":\"после «Ночи живых мертвецов» пути Джона Руссо и Джорджа Ромеро разошлись, и Руссо оставил за собой право на «живых мертвецов», а Ромеро стал снимать фильмы, в названии которых остались только мертвецы. Ромеро стал мертвецом в 2017 году, а Руссо пока ещё жив. В ответах живых и мёртвых связывает медиум, чьи способности контактировать с духами объяснялись расщеплением сознания на несколько личностей.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. https://ru.wikipedia.org/wiki/Живые_мертвецы\\\\n2. https://ru.wikipedia.org/wiki/Руссо,_Джон_(кинематографист)\\\\n3. https://ru.wikipedia.org/wiki/Медиум\\\\n4. https://ru.wikipedia.org/wiki/Ромеро,_Джордж\",\"authors\":[{\"id\":267,\"name\":\"Максим Мерзляков\",\"gender\":\"HE\"}],\"editors\":[{\"id\":267,\"name\":\"Максим Мерзляков\",\"gender\":\"HE\"}],\"tour\":{\"id\":634,\"number\":3,\"title\":\"\"},\"packId\":175,\"packTitle\":\"Бесконечные земли: том I\",\"controversials\":[{\"id\":129583,\"answer\":\"живые мертвецы экзорцисты мертвецы\",\"status\":\"D\",\"comment\":\"\",\"appealJuryComment\":\"None\"},{\"id\":129584,\"answer\":\"живые ходоки мертвые\",\"status\":\"D\",\"comment\":\"\",\"appealJuryComment\":\"None\"},{\"id\":129541,\"answer\":\"живые лунатики мертвые\",\"status\":\"D\",\"comment\":\"None\",\"appealJuryComment\":\"None\"},{\"id\":129575,\"answer\":\"живые коматозники мертвецы\",\"status\":\"D\",\"comment\":\"\",\"appealJuryComment\":\"None\"},{\"id\":129535,\"answer\":\"Живой, призрак, мертвые\",\"status\":\"D\",\"comment\":\"None\",\"appealJuryComment\":\"None\"},{\"id\":129536,\"answer\":\"живые зомби мертвецы\",\"status\":\"D\",\"comment\":\"None\",\"appealJuryComment\":\"None\"},{\"id\":129582,\"answer\":\"живой зомби мертвый\",\"status\":\"D\",\"comment\":\"\",\"appealJuryComment\":\"None\"},{\"id\":129546,\"answer\":\"живые ходячие мертвецы\",\"status\":\"D\",\"comment\":\"\",\"appealJuryComment\":\"None\"},{\"id\":129585,\"answer\":\"живые лунатики мертвецы\",\"status\":\"D\",\"comment\":\"\",\"appealJuryComment\":\"None\"}],\"appeals\":[],\"totalLikes\":1,\"totalDislikes\":0,\"pubDate\":\"2020-08-05 00:00:00\",\"endDate\":\"2020-07-05 23:55:00\",\"uploader\":1,\"tags\":[{\"id\":4,\"title\":\"блиц\"}],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[246],\"complexity\":[17.89],\"correct_answers\":[44],\"tournaments\":[{\"id\":6529,\"title\":\"Онлайн: Бесконечные земли. Том I\",\"typeoft\":{\"id\":8,\"title\":\"Асинхрон\"}}]},{\"id\":369955,\"number\":46,\"text\":\"[Ведущему: кавычки в тексте вопроса игнорировать]Дуплет. 2 вопроса по 30 секунд обсуждения каждый, ответы сдаются на одном бланке.1. В романе Кевина Андерсона женщина остаётся в осажденном Париже времен франко-прусской войны. Женщине удаётся воссоединиться со своим возлюбленным благодаря зашедшему в Сену «ИКСу». Можно сказать, что другой «ИКС» воссоединялся, например, в 2014 году. Назовите ИКС одним словом.2. В романе Кевина Андерсона ИКС сбегает с необитаемого острова через подземный мир, после чего отправляется в путешествие на воздушном шаре. Какого персонажа мы заменили ИКСом?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"1. НаутИлус.\\\\n2. [капитан] Немо.\",\"answerPic\":\"\",\"zachet\":\"2) [принц] Даккар.\",\"nezachet\":\"\",\"comment\":\"в романе Андерсона капитан Немо участвует во всех других известных произведениях Жюля Верна: с таинственного острова сбегает через центр Земли, встречается на Крымской войне с РобУром-завоевателем, пролетает над Африкой на воздушном шаре. Сам Верн также является персонажем романа, якобы записавшим все приключения со слов Немо. Профессор Арронакс в романе выведен как женщина, в которую влюблены и Верн, и Немо. Из Парижа её спасает зашедший в Сену «Наутилус». Последнее воссоединение группы «Наутилус Помпилиус», которую часто называют просто «Наутилус», произошло в 2014 году.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"https://en.wikipedia.org/wiki/Captain_Nemo:_The_Fantastic_History_of_a_Dark_Genius\",\"authors\":[{\"id\":269,\"name\":\"Руслан Алиев\",\"gender\":\"HE\"}],\"editors\":[{\"id\":269,\"name\":\"Руслан Алиев\",\"gender\":\"HE\"}],\"tour\":{\"id\":22617,\"number\":4,\"title\":\"\"},\"packId\":5254,\"packTitle\":\"Кубок Сигулды `20\",\"controversials\":[],\"appeals\":[],\"totalLikes\":1,\"totalDislikes\":0,\"pubDate\":\"2022-12-26 00:00:00\",\"endDate\":\"2020-02-02 13:00:00\",\"uploader\":1,\"tags\":[{\"id\":5,\"title\":\"дуплет\"}],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[33],\"complexity\":[54.55],\"correct_answers\":[18],\"tournaments\":[{\"id\":6185,\"title\":\"Кубок Сигулды\",\"typeoft\":{\"id\":2,\"title\":\"Обычный\"}}]},{\"id\":390864,\"number\":46,\"text\":\"Маньяк из комиксов DC (ди-си) носит маску свиньи и стремится совершенствовать тела своих жертв. Его псевдоним – сокращение от имени. Какого?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Пигмалион.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Убийца носит прозвище \\\"Профессор Пиг\\\", но его имя пишется через \\\"y\\\" (уай), что отсылает мифу о Пигмалионе и пьесе Бернарда Шоу.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"http://batman.wikia.com/wiki/Professor_Pyg\",\"authors\":[{\"id\":584,\"name\":\"Дмитрий Богданов\",\"gender\":\"HE\"}],\"editors\":[],\"tour\":{\"id\":24441,\"number\":4,\"title\":\"\"},\"packId\":5722,\"packTitle\":\"II открытый чемпионат Белгородской области среди студенческих команд 2019\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2024-01-07 12:14:37.949537\",\"endDate\":\"2019-12-14 18:00:00\",\"uploader\":484,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[16],\"complexity\":[0],\"correct_answers\":[0],\"tournaments\":[{\"id\":6170,\"title\":\"Открытый чемпионат Белгородской области\",\"typeoft\":{\"id\":2,\"title\":\"Обычный\"}}]},{\"id\":413420,\"number\":164,\"text\":\"В начале одной из лекций по менеджменту профессор Армин Трост отмечает, что предпочитает менее распространенный термин «ТАКОЙ ИКС», а не «ТАКИЕ ИГРЕКИ». По мнению лектора, «ТАКОЙ ИКС» подчеркивает возможность преумножения, а не истощения. Что мы заменили на ТАКОЙ ИКС?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"человеческий капитал.\",\"answerPic\":\"\",\"zachet\":\"human capital.\",\"nezachet\":\"\",\"comment\":\"в самом начале лектор обращается к основной терминологии и говорит, что у человеческих ресурсов (human resources) есть недостаток: когда ресурсы используют, они истощаются, в то время как правильное использование капитала позволяет увеличивать его. Но термин «человеческий капитал» использует не так много компаний, поэтому курс всё равно назван «Human Resource Management».\\\\nЧисло взятий (ВЛ/ПЛ):7/16\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. https://youtu.be/c8_avX9miag?t=54.\",\"authors\":[{\"id\":13150,\"name\":\"Алия Агаева\",\"gender\":\"HE\"}],\"editors\":[{\"id\":957,\"name\":\"Сергей Фокин\",\"gender\":\"HE\"},{\"id\":3517,\"name\":\"Юрий Старовойт\",\"gender\":\"HE\"},{\"id\":13149,\"name\":\"Дмитрий Силин\",\"gender\":\"HE\"},{\"id\":13150,\"name\":\"Алия Агаева\",\"gender\":\"HE\"},{\"id\":13151,\"name\":\"Андрей Репин\",\"gender\":\"HE\"},{\"id\":13152,\"name\":\"Никита Пономарёв\",\"gender\":\"HE\"},{\"id\":13153,\"name\":\"Александр Петраков\",\"gender\":\"HE\"}],\"tour\":{\"id\":26416,\"number\":11,\"title\":\"Тур команды «Разбойники из Кардамона»\"},\"packId\":6239,\"packTitle\":\"XXI Чемпионат Санкт-Петербурга\",\"controversials\":[],\"appeals\":[],\"totalLikes\":3,\"totalDislikes\":0,\"pubDate\":\"2025-03-10 10:09:31\",\"endDate\":\"2019-12-01 15:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[12],\"complexity\":[58.33],\"correct_answers\":[7],\"tournaments\":[{\"id\":6150,\"title\":\"Чемпионат Санкт-Петербурга. Высшая лига\",\"typeoft\":{\"id\":2,\"title\":\"Обычный\"}}]},{\"id\":380869,\"number\":23,\"text\":\"Происхождение фамилии Саи\u0306кс задокументировано, и ее\u0308 историю можно проследить на протяжении как минимум семи веков. Браи\u0306ан Саи\u0306кс исследовал хромосомы своих однофамильцев и вывел коэффициент ЕГО. Назовите ЕГО словом французского происхождения.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"адюльте\u0301р.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"зная, что и фамилия, и Y-хромосома передаются по мужскои\u0306 линии, уче\u0308ныи\u0306 предположил, что у всех мужчин однофамильцев также должна быть одна и та же Y- хромосома. Разумеется, такая связь между Y-хромосомои\u0306 и фамилиеи\u0306 может разорваться. Например, если мать таи\u0306но забеременела от сантехника. Профессор Саи\u0306кс смог добыть 48 образцов для анализа. Оказалось, что 50 % их Y-хромосом деи\u0306ствительно идентичны его «саи\u0306ксовскои\u0306» хромосоме, в остальных нашлись признаки адюльтера со стороны однои\u0306 или более миссис Саи\u0306кс. В среднем получился 1% на поколение — это означает, что 99% саи\u0306ксовских же\u0308н в каждом поколении не изменяли мужу (или делали это осторожно).\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"Джеи\u0306мс Д. Уотсон, Кевин Дэвис, Эндрю Берри. ДНК. История генетическои\u0306 революции.\",\"authors\":[{\"id\":6,\"name\":\"Сергей Терентьев\",\"gender\":\"HE\"}],\"editors\":[{\"id\":6,\"name\":\"Сергей Терентьев\",\"gender\":\"HE\"}],\"tour\":{\"id\":23562,\"number\":2,\"title\":\"\"},\"packId\":5497,\"packTitle\":\"XV кубок Европы среди студентов по интеллектуальным играм (Минск). ЧГК\",\"controversials\":[],\"appeals\":[],\"totalLikes\":1,\"totalDislikes\":0,\"pubDate\":\"2023-08-08 12:58:36\",\"endDate\":\"2019-10-13 16:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[36],\"complexity\":[41.67],\"correct_answers\":[15],\"tournaments\":[{\"id\":5773,\"title\":\"Кубок Европы среди студентов\",\"typeoft\":{\"id\":2,\"title\":\"Обычный\"}}]},{\"id\":4247,\"number\":44,\"text\":\"В годы Второй мировой войны ФБР пыталось запретить публикацию некоего произведения, персонажу которого удалось сжечь асбест. Какие два слова мы заменили словами «сжечь асбест»?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"разделить атом.\",\"answerPic\":\"\",\"zachet\":\"разрезать атом, расщепить атом.\",\"nezachet\":\"\",\"comment\":\"Профессор из комикса «Наука Супермена» изобрел прибор, способный разделять атомы. ФБР заподозрило утечку информации из Манхэттенского проекта, но оказалось, что это лишь потрепавшее нервы совпадение. С греческого асбест переводится как «несгораемый», а атом как «неделимый».\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"M. Jacob. St. Benzofker. 10 Things You Might Not Know About Nearly Everything.\",\"authors\":[{\"id\":105,\"name\":\"Антон Саксонов\",\"gender\":\"HE\"}],\"editors\":[{\"id\":105,\"name\":\"Антон Саксонов\",\"gender\":\"HE\"}],\"tour\":{\"id\":348,\"number\":4,\"title\":\"\"},\"packId\":90,\"packTitle\":\"Чемпионат Азербайджана\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2020-12-19 00:00:00\",\"endDate\":\"2019-04-14 19:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[23],\"complexity\":[21.74],\"correct_answers\":[5],\"tournaments\":[{\"id\":5573,\"title\":\"Чемпионат Азербайджана\",\"typeoft\":{\"id\":2,\"title\":\"Обычный\"}}]},{\"id\":16639,\"number\":61,\"text\":\"В книге Кира Булычёва инопланетянин Громозека, желая сделать комплимент женщине, употребил некое слово, после чего услышал комментарий о примитивном жилище. Уже тогда Булычёв высмеивал проблемы с употреблением ИХ. Назовите ИХ.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"феминитивы\",\"answerPic\":\"\",\"zachet\":\"феминативы\",\"nezachet\":\"\",\"comment\":\"инопланетянин Громозека, встретив в ресторане старушку с планеты Земля, оставил ей автограф со строками «прекрасной юной землянке», на что профессор Селезнёв резонно возразил, что землянками называют не женщин, а «первобытное жильё, выкопанное в Земле». Уже тогда Булычёв предвосхитил языковые проблемы, которые вызывает неумеренное использование суффикса «–ка» вместо более подходящих «-ша» или «-ха». Отсюда, например, типичные ошибки вроде «спецкорки» или «гримёрки», которые допускают современные феминистки.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"http://www.rusf.ru/kb/stories/puteshestvie_alisy/text-01.htm\",\"authors\":[{\"id\":335,\"name\":\"Артём Рожков\",\"gender\":\"HE\"}],\"editors\":[{\"id\":762,\"name\":\"Алексей Хмельков\",\"gender\":\"HE\"}],\"tour\":{\"id\":1393,\"number\":5,\"title\":\"\"},\"packId\":370,\"packTitle\":\"XIII международный кубок Физтеха\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2019-11-07 00:00:00\",\"endDate\":\"2019-03-10 16:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[53],\"complexity\":[88.68],\"correct_answers\":[47],\"tournaments\":[{\"id\":5343,\"title\":\"Кубок Физтеха\",\"typeoft\":{\"id\":2,\"title\":\"Обычный\"}}]},{\"id\":376259,\"number\":13,\"text\":\"Маньяк-учёный из комиксов носит маску свиньи и стремится совершенствовать своих жертв. Одно из слов в его псевдониме является сокращение от имени. Какого?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Пигмалион.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"учёный взял себе прозвище «Профессор Пиг», а маска свиньи может ввести в заблуждение, что «Пиг» в псевдониме пишется через английскую «i» [ай]. Тем не менее, «Пиг» пишется через «y» [уай] и является отсылкой к пьесе «Пигмалион», что и отражается в намерениях злодея.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"http://batman.wikia.com/wiki/Professor_Pyg\",\"authors\":[{\"id\":65,\"name\":\"Станислав Утикеев\",\"gender\":\"HE\"}],\"editors\":[{\"id\":6,\"name\":\"Сергей Терентьев\",\"gender\":\"HE\"}],\"tour\":{\"id\":23154,\"number\":1,\"title\":\"\"},\"packId\":5398,\"packTitle\":\"Гран-при Славянки. 2 этап\",\"controversials\":[],\"appeals\":[],\"totalLikes\":2,\"totalDislikes\":0,\"pubDate\":\"2023-05-05 12:24:57\",\"endDate\":\"2019-02-26 17:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[124],\"complexity\":[55.65],\"correct_answers\":[69],\"tournaments\":[{\"id\":5334,\"title\":\"Гран-при Славянки. 2 этап\",\"typeoft\":{\"id\":3,\"title\":\"Синхрон\"}}]},{\"id\":27533,\"number\":54,\"text\":\"Дуплет.\\\\n1. В 1857 году американский дипломат Эндрю Диксон Уайт прочитал в Йельском университете публичную лекцию, в которой критиковал ЭТО с позиций экономики и морали. Назовите ЭТО двумя словами.\\\\n2. В 1857 году профессор Дмитрий Каченовский читал в Харьковском университете публичные лекции, в которых критиковал ЭТО с позиций экономики и морали. Назовите ЭТО одним словом.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"1. Крепостное право.\\\\n2. Рабство.\",\"answerPic\":\"\",\"zachet\":\"1. Крепостная система.\\\\n2. Рабовладение.\",\"nezachet\":\"\",\"comment\":\"Каждый из них не мог по разным причинам говорить о проблемах собственной страны (в России из-за жесткой цензуры, в Америке из-за боязни отпугнуть аудиторию) и поэтому говорил о заокеанских проблемах. Впрочем, в обоих случаях думающие слушатели прекрасно понимали, на что намекает автор.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"https://www.nlobooks.ru/magazines/novoe_literaturnoe_obozrenie/142_nlo_6_2016_spetsialnyy_vypusk_t_2_rabstvo/article/12342/\",\"authors\":[{\"id\":234,\"name\":\"Дмитрий Борок\",\"gender\":\"HE\"}],\"editors\":[{\"id\":234,\"name\":\"Дмитрий Борок\",\"gender\":\"HE\"}],\"tour\":{\"id\":2167,\"number\":4,\"title\":\"\"},\"packId\":575,\"packTitle\":\"Самариум\",\"controversials\":[],\"appeals\":[],\"totalLikes\":1,\"totalDislikes\":0,\"pubDate\":\"2019-02-22 00:00:00\",\"endDate\":\"2018-12-09 17:00:00\",\"uploader\":1,\"tags\":[{\"id\":5,\"title\":\"дуплет\"}],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[49],\"complexity\":[77.55],\"correct_answers\":[38],\"tournaments\":[{\"id\":5214,\"title\":\"Самариум\",\"typeoft\":{\"id\":2,\"title\":\"Обычный\"}}]},{\"id\":364174,\"number\":11,\"text\":\"ИКС — это замена.\\\\nВ песне Максима Леонидова есть слова: «Нашу родную ширь туман превратил в ИКС». Одним из увлечений уроженца ИКСА было фотографирование, благодаря чему поклонники смогли узнать, как выглядел в XIX веке его отчий дом, уничтоженный позже пожаром. Назовите фамилию этого фотографа-любителя.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Доджсон.\",\"answerPic\":\"\",\"zachet\":\"Кэрролл.\",\"nezachet\":\"\",\"comment\":\"ИКС — это Че\u0301шир, хотя для песни было использовано неправильное ударение. Графство Чешир, помимо прочего, является малой родиной Чарльза Доджсона (Льюиса Кэрролла), описавшего знаменитого Чеширского кота в книге «Алиса в Стране чудес». Одним из увлечений профессора Доджсона было фотографирование. Освоившись с этим сложным процессом, он отправился в деревню Дарсбери, где прошло его детство, и сделал ряд снимков. И успел вовремя — спустя несколько лет пожар уничтожил многое в этой деревне, в том числе и отчий дом писателя.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. М. Леонидов, «Питерские коты» (http://slovapesen.com/maksim-leonidov-piterskie-koty-valeriy-syutkin_s159799/)\\\\n2. Н. Демурова. «Льюис Кэрролл» (http://www.lewis-carroll.ru/library/demurova-luis-kerroll9.html)\\\\n3. https://ru.wikipedia.org/wiki/Чешир\\\\n4. https://ru.wikipedia.org/wiki/Льюис_Кэрролл\",\"authors\":[{\"id\":428,\"name\":\"Денис Володин\",\"gender\":\"HE\"},{\"id\":790,\"name\":\"Виктор Мялов\",\"gender\":\"HE\"}],\"editors\":[{\"id\":525,\"name\":\"Дмитрий Свинтицкий\",\"gender\":\"HE\"},{\"id\":790,\"name\":\"Виктор Мялов\",\"gender\":\"HE\"},{\"id\":1331,\"name\":\"Дмитрий Смирнов\",\"gender\":\"HE\"}],\"tour\":{\"id\":22138,\"number\":3,\"title\":\"\"},\"packId\":5141,\"packTitle\":\"Гран-при Бауманки - 2018/19. 6 этап. \\\"Августовский пунш - 2019\\\"\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2022-08-30 00:00:00\",\"endDate\":\"2018-12-08 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":15648,\"number\":6,\"text\":\"На фотографии 1924 года профессор пока жив и здоров, а ИКС – у него на привязи. Назовите имя ИКСА.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Ха\u0301тико.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"в кадре профессор Уэ\u0301но играет с привязанным псом. После смерти профессора Хатико стал символом привязанности в переносном смысле. В каком-то смысле Хатико повторил судьбу Йозефа Майстера.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. http://tunnel.ru/post-istoriya-v-fotografii\\\\n2. https://ru.wikipedia.org/wiki/Хатико\",\"authors\":[{\"id\":115,\"name\":\"Павел Ершов\",\"gender\":\"HE\"}],\"editors\":[{\"id\":115,\"name\":\"Павел Ершов\",\"gender\":\"HE\"}],\"tour\":{\"id\":1308,\"number\":1,\"title\":\"\"},\"packId\":349,\"packTitle\":\"Играй для жизни\",\"controversials\":[],\"appeals\":[],\"totalLikes\":1,\"totalDislikes\":0,\"pubDate\":\"2019-11-30 00:00:00\",\"endDate\":\"2018-10-02 19:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[352],\"complexity\":[14.49],\"correct_answers\":[51],\"tournaments\":[{\"id\":4816,\"title\":\"Играй для Жизни\",\"typeoft\":{\"id\":3,\"title\":\"Синхрон\"}}]},{\"id\":34177,\"number\":42,\"text\":\"Задача о сортировке шаров трех разных цветов, сформулированная профессором Эйндховенского университета Эдсгером Дейкстрой, носит название \\\"Проблема ИКСА\\\". Назовите ИКС двумя словами.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Нидерландский флаг.\",\"answerPic\":\"\",\"zachet\":\"Флаг Нидерландов; голландский флаг; флаг Голландии.\",\"nezachet\":\"\",\"comment\":\"Эдсгер Дейкстра — нидерландский ученый. Для примера он использовал цвета национального флага: красный, белый и синий.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. https://neerc.ifmo.ru/wiki/index.php?title=Dutch_national_flag_problem\\\\n2. https://en.wikipedia.org/wiki/Edsger_W._Dijkstra\",\"authors\":[{\"id\":298,\"name\":\"Владислав Говердовский\",\"gender\":\"HE\"}],\"editors\":[{\"id\":298,\"name\":\"Владислав Говердовский\",\"gender\":\"HE\"}],\"tour\":{\"id\":2596,\"number\":4,\"title\":\"\"},\"packId\":692,\"packTitle\":\"Хрустальный Голем\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2018-11-05 00:00:00\",\"endDate\":\"2018-05-12 14:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[31],\"complexity\":[61.29],\"correct_answers\":[19],\"tournaments\":[{\"id\":4815,\"title\":\"Хрустальный Голем\",\"typeoft\":{\"id\":2,\"title\":\"Обычный\"}}]},{\"id\":42016,\"number\":3,\"text\":\"Профессор геологического факультета МГУ Николай Короновский, рассказывая о мощности отложений соли в Прикаспийской низменности, упоминает двадцать четвертый ИКС. Какие слова мы заменили ИКСОМ?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Этаж главного здания МГУ.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Мощность этих отложений сопоставима с высотой, на которой находится двадцать четвертый этаж главного здания МГУ. На этом этаже, кстати, расположен музей землеведения.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"Н.В. Короновский. Общая геология. — М.: КДУ, 2006. — С. 345.\",\"authors\":[{\"id\":295,\"name\":\"Максим Руссо\",\"gender\":\"HE\"}],\"editors\":[{\"id\":295,\"name\":\"Максим Руссо\",\"gender\":\"HE\"},{\"id\":474,\"name\":\"Иван Семушин\",\"gender\":\"HE\"},{\"id\":769,\"name\":\"Александра Брутер\",\"gender\":\"HE\"}],\"tour\":{\"id\":3095,\"number\":1,\"title\":\"1 тур. \\\"Борский корабел\\\"\"},\"packId\":803,\"packTitle\":\"Кубок Москвы по ЧГК. Гран-При сезона 2017/18 гг.\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2018-07-21 00:00:00\",\"endDate\":\"2018-04-14 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":58649,\"number\":18,\"text\":\"Герой Акунина считает, что на Сталина плохо влияет некий профессор, после чего заявляет, что готов стать красным Феликсом Дзержинским. Какое слово мы заменили в предыдущем предложении?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Юсуповым.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Этого профессора герой сравнивает с Распутиным, после чего говорит, что готов попытаться спасти Отечество и убить профессора, подобно тому как князь Феликс Юсупов убил \\\"святого старца\\\".\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. Б. Акунин. Квест.\\\\nhttps://books.google.ru/books?id=yNoWM2xspGQC\\u0026pg=PT271#v=onepage\\u0026q\\u0026f=false\\\\n2. http://ru.wikipedia.org/wiki/Юсупов,_Феликс_Феликсович\",\"authors\":[{\"id\":267,\"name\":\"Максим Мерзляков\",\"gender\":\"HE\"}],\"editors\":[{\"id\":267,\"name\":\"Максим Мерзляков\",\"gender\":\"HE\"}],\"tour\":{\"id\":4115,\"number\":2,\"title\":\"\"},\"packId\":1084,\"packTitle\":\"Играй для Жизни — 2017\",\"controversials\":[{\"id\":62793,\"answer\":\"врач\",\"status\":\"D\",\"comment\":\"\",\"appealJuryComment\":\"None\"},{\"id\":62914,\"answer\":\"eefant,came\",\"status\":\"D\",\"comment\":\"\",\"appealJuryComment\":\"None\"}],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2017-10-09 00:00:00\",\"endDate\":\"2017-10-03 19:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[500],\"complexity\":[24.6],\"correct_answers\":[123],\"tournaments\":[{\"id\":4150,\"title\":\"Играй для Жизни\",\"typeoft\":{\"id\":3,\"title\":\"Синхрон\"}}]},{\"id\":52280,\"number\":13,\"text\":\"В 1899 году палеонтолог Владимир АмалИцкий раскопал в песчаниках останки доисторических животных. Для того чтобы привести их в \\\"музейный\\\" вид, ему пришлось обратиться к ИКСАМ. Назовите немецкоязычный роман, заголовок которого — продукт деятельности ИКСОВ.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"\\\"Черный обелиск\\\".\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Чтобы высвободить окаменелости из песчаника, профессору пришлось обратиться к кладбищенским каменотесам, вырезающим надгробные плиты. Мастера буквально выдолбили кость за костью уникальные скелеты. Не всегда точно, с некоторыми потерями, но результат был достигнут. В романе \\\"Черный обелиск\\\" Эриха Марии Ремарка главный герой работает в фирме по продаже надгробий.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. http://elementy.ru/nauchno-populyarnaya_biblioteka/430815\\\\n2. http://ru.wikipedia.org/wiki/Чёрный_обелиск_(роман)\",\"authors\":[{\"id\":14,\"name\":\"Михаил Рыжок\",\"gender\":\"HE\"}],\"editors\":[],\"tour\":{\"id\":3640,\"number\":6,\"title\":\"6 тур. \\\"Дикие бозоны Хиггса\\\"\"},\"packId\":967,\"packTitle\":\"Весенний чемпионат \\\"Коломны\\\" - 2017\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2018-02-17 00:00:00\",\"endDate\":\"2017-06-03 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":69241,\"number\":22,\"text\":\"ИКС — это замена.\\\\nМосковский профессор Александр Петров является выпускником авиационного института. Но ИКСОМ его называют вовсе не по этой причине, а потому что он родом из... Какого украинского города?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Измаил.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Петрова называют измаильцем не потому что он из МАИ (Московского авиационного института), а потому что он родился и провел детство в Измаиле Одесской области.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. http://www.izmail.es/print_version/article/7251/\\\\n2. http://ru.wikipedia.org/wiki/Измаил\",\"authors\":[{\"id\":790,\"name\":\"Виктор Мялов\",\"gender\":\"HE\"}],\"editors\":[{\"id\":790,\"name\":\"Виктор Мялов\",\"gender\":\"HE\"}],\"tour\":{\"id\":4853,\"number\":2,\"title\":\"\"},\"packId\":1258,\"packTitle\":\"Эврика! - 4\",\"controversials\":[{\"id\":50455,\"answer\":\"Одесса\",\"status\":\"D\",\"comment\":\"None\",\"appealJuryComment\":\"None\"},{\"id\":50444,\"answer\":\"Мариуполь\",\"status\":\"D\",\"comment\":\"None\",\"appealJuryComment\":\"None\"},{\"id\":50686,\"answer\":\"измаилец\",\"status\":\"D\",\"comment\":\"Увы, требовалось назвать город.\",\"appealJuryComment\":\"None\"},{\"id\":50705,\"answer\":\"Львов\",\"status\":\"D\",\"comment\":\"None\",\"appealJuryComment\":\"None\"},{\"id\":50440,\"answer\":\"Харьков\",\"status\":\"D\",\"comment\":\"None\",\"appealJuryComment\":\"None\"}],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2017-02-23 00:00:00\",\"endDate\":\"2017-02-08 09:29:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[159],\"complexity\":[10.69],\"correct_answers\":[17],\"tournaments\":[{\"id\":4189,\"title\":\"Эврика! - 4\",\"typeoft\":{\"id\":3,\"title\":\"Синхрон\"}}]},{\"id\":54606,\"number\":6,\"text\":\"Профессор ГЕзер отмечает, что в свое время кавалеры отращивали пышную растительность на лице, чтоб показать, что у них нет ИКСА. Назовите ИКС.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Сифилис.\",\"answerPic\":\"\",\"zachet\":\"Люэс.\",\"nezachet\":\"\",\"comment\":\"При сифилисе наблюдается выпадение волос — как вследствие самого заболевания, так и из-за лечения его ядовитой ртутью, практиковавшегося до середины XX века. Таким образом, при помощи пышной растительности кавалеры хотели продемонстрировать дамам, что они свободны от этой весьма опасной и довольно распространенной в прошлые века венерической болезни.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. http://www.medicall.ru/pages/bolistrr/siflisss.html\\\\n2. http://ru.wikipedia.org/wiki/Сифилис\",\"authors\":[{\"id\":85,\"name\":\"Максим Мозуль\",\"gender\":\"HE\"}],\"editors\":[{\"id\":85,\"name\":\"Максим Мозуль\",\"gender\":\"HE\"}],\"tour\":{\"id\":3815,\"number\":1,\"title\":\"\"},\"packId\":1013,\"packTitle\":\"Кубок Сигулды\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2018-01-01 00:00:00\",\"endDate\":\"2017-01-22 13:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[29],\"complexity\":[44.83],\"correct_answers\":[13],\"tournaments\":[{\"id\":4139,\"title\":\"Кубок Сигулды\",\"typeoft\":{\"id\":2,\"title\":\"Обычный\"}}]},{\"id\":52451,\"number\":4,\"text\":\"Британский ученый описывает ситуацию в маленьком городке: среди жителей всего один ИКС, и остальные считают, что ИКС должен оставаться таковым ради всеобщего блага. Ведь иначе властям придется сделать ИКСАМИ нескольких других жителей. А что, как правило, ищут ИКСЫ?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Работу.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Если единственный безработный найдет работу, то станет не нужна городская служба занятости. Описывает этот курьезный случай экономист Ха Джун Чан — действительно кембриджский профессор корейского происхождения.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"Ха Джун Чан. Как устроена экономика.\\\\nhttps://postnauka.ru/longreads/50791\",\"authors\":[{\"id\":3170,\"name\":\"Марина Крылова\",\"gender\":\"HE\"}],\"editors\":[],\"tour\":{\"id\":3652,\"number\":8,\"title\":\"8 тур. \\\"В-Ч-Ж\\\"\"},\"packId\":968,\"packTitle\":\"Осенний чемпионат \\\"Коломны\\\" - 2016\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2018-02-12 00:00:00\",\"endDate\":\"2017-01-21 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":64934,\"number\":9,\"text\":\"ТАКОЙ ИКС — это цветок с длинными заостренными листьями серого цвета. В некоторых фанфиках ТАКОЙ ИКС есть у известного голландского профессора. Что мы заменили словами \\\"ТАКОЙ ИКС\\\"?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Серебряный меч.\",\"answerPic\":\"\",\"zachet\":\"Серебристый меч.\",\"nezachet\":\"\",\"comment\":\"Голландский профессор — это Абрахам ван Хельсинг — охотник на вампиров. Серебряный меч — это очень редкое растение, эндемик Гавайских островов. Название связано с тем, что у листьев мечевидная форма и серебристый оттенок.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. Э. Меннинджер. Причудливые деревья.\\\\nhttp://flibusta.is/b/470001/read\\\\n2. Многочисленные фанфики, посвященные охоте на вампиров.\",\"authors\":[{\"id\":327,\"name\":\"Эдуард Голуб\",\"gender\":\"HE\"}],\"editors\":[{\"id\":327,\"name\":\"Эдуард Голуб\",\"gender\":\"HE\"}],\"tour\":{\"id\":4562,\"number\":4,\"title\":\"\"},\"packId\":1183,\"packTitle\":\"Фестиваль памяти Сергея Некрасова\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2017-05-25 00:00:00\",\"endDate\":\"2017-01-07 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":67362,\"number\":38,\"text\":\"Внимание, слова \\\"ИГРЕК\\\" и \\\"ЗЕТ\\\" в вопросе являются заменами.\\\\nГероиня романа Элис Рэндалл — профессор филологии афроамериканского происхождения. Своему сыну она дала имя ИГРЕК ЗЕТ. Описывая барышню с туго перетянутой талией, ИГРЕК использует сравнение с ЗЕТОМ. Напишите слова, которые мы заменили ИГРЕКОМ и ЗЕТОМ.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Пушкин, Икс.\",\"answerPic\":\"\",\"zachet\":\"Пушкин, Экс; Пушкин, X.\",\"nezachet\":\"\",\"comment\":\"Сына зовут Пушкин Икс. Имя Икс популярно среди американских негров еще со времен Малькольма Икса. А так как она филолог, то дала сыну еще одно имя — в честь писателя частично африканского происхождения.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. http://www.alicerandall.com/pushkin\\\\n2. А.С. Пушкин. Барышня-крестьянка.\\\\nhttp://www.rvb.ru/pushkin/01text/06prose/01prose/0862.htm\",\"authors\":[{\"id\":220,\"name\":\"Александр Либер\",\"gender\":\"HE\"}],\"editors\":[{\"id\":220,\"name\":\"Александр Либер\",\"gender\":\"HE\"}],\"tour\":{\"id\":4722,\"number\":3,\"title\":\"\"},\"packId\":1225,\"packTitle\":\"Кубок 10-летия ProjeKCt\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2017-04-07 00:00:00\",\"endDate\":\"2016-12-18 16:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[29],\"complexity\":[3.45],\"correct_answers\":[1],\"tournaments\":[{\"id\":3904,\"title\":\"Кубок 10-летия ProjeKCt\",\"typeoft\":{\"id\":2,\"title\":\"Обычный\"}}]},{\"id\":71707,\"number\":10,\"text\":\"Федор СтепУн, впоследствии занимавший место профессора социологии в университете Дрездена, воспользовался поездом. Несмотря на это, Татьяна ВОльтская в своей статье \\\"\\\"ИКС\\\" как зло и спасение\\\" ошибочно упоминает Степуна. Назовите \\\"ИКС\\\".\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"\\\"Философский пароход\\\".\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Вольтская упоминает Степуна в числе пассажиров одного из двух немецких пароходов — \\\"Пруссия\\\" и \\\"Обербургомистр Хакен\\\", которые известны под общим названием \\\"Философский пароход\\\".\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. http://www.ihst.ru/projects/sohist/document/deport/stepun.htm\\\\n2. http://www.svoboda.org/a/24768799.html\",\"authors\":[{\"id\":336,\"name\":\"Серафим Шибанов\",\"gender\":\"HE\"}],\"editors\":[{\"id\":336,\"name\":\"Серафим Шибанов\",\"gender\":\"HE\"}],\"tour\":{\"id\":5048,\"number\":1,\"title\":\"\"},\"packId\":1301,\"packTitle\":\"13-й воин\",\"controversials\":[{\"id\":47847,\"answer\":\"пароход\",\"status\":\"D\",\"comment\":\"Недостаточно точный ответ. Вольтская пишет именно про \\\"Философский пароход\\\".\",\"appealJuryComment\":\"None\"},{\"id\":48065,\"answer\":\"пароход философов\",\"status\":\"A\",\"comment\":\"None\",\"appealJuryComment\":\"None\"}],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2016-12-30 00:00:00\",\"endDate\":\"2016-12-13 18:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[87],\"complexity\":[47.13],\"correct_answers\":[41],\"tournaments\":[{\"id\":3972,\"title\":\"13-й воин\",\"typeoft\":{\"id\":3,\"title\":\"Синхрон\"}}]},{\"id\":73249,\"number\":20,\"text\":\"Внимание, в вопросе есть замены.\\\\nПрофессор Оксфордского университета утверждал, что ИКСЫ не умеют делать красивых вещей. Возможно, это и так, но один ИКС с помощью \\\"Божьей искры\\\" так переиначил результат трудов профессора, что заставил смеяться миллионы. Назовите ИКСА.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Гоблин.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Гоблин (Дмитрий Пучков) — создатель студии \\\"Божья искра\\\", переводчик, создавший \\\"Братву и кольцо\\\" (\\\"гоблинский\\\" перевод фильма \\\"Властелин колец\\\").\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. http://ru.wikipedia.org/wiki/Гоблины\\\\n2. http://ru.wikipedia.org/wiki/Божья_искра_(студия)\",\"authors\":[{\"id\":2211,\"name\":\"Сергей Киктев\",\"gender\":\"HE\"}],\"editors\":[{\"id\":2210,\"name\":\"Андрей Тугин\",\"gender\":\"HE\"},{\"id\":2211,\"name\":\"Сергей Киктев\",\"gender\":\"HE\"},{\"id\":3236,\"name\":\"Мария Киут\",\"gender\":\"HE\"},{\"id\":3799,\"name\":\"Лев Баранчук-Червонный\",\"gender\":\"HE\"},{\"id\":3804,\"name\":\"Александр Шукан\",\"gender\":\"HE\"}],\"tour\":{\"id\":5159,\"number\":2,\"title\":\"\"},\"packId\":1334,\"packTitle\":\"Скважина знаний\",\"controversials\":[{\"id\":40860,\"answer\":\"Гоблин Дм. Пучков\",\"status\":\"A\",\"comment\":\"None\",\"appealJuryComment\":\"спорный был принят АЖ\"}],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2016-11-23 00:00:00\",\"endDate\":\"2016-07-12 19:30:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[132],\"complexity\":[45.46],\"correct_answers\":[60],\"tournaments\":[{\"id\":3882,\"title\":\"Скважина знаний\",\"typeoft\":{\"id\":3,\"title\":\"Синхрон\"}}]},{\"id\":79272,\"number\":21,\"text\":\"Татьяна Толстая признаётся, что любит ИКСЫ, и рассказывает, как угощала свою подругу, профессора университета, огурчиками. Подруга заметила, что в ее семье никогда не употребляли ИКСЫ, т.к. это считалось мещанством. \\\"И ведь действительно, — рассуждает Толстая, — дворянин не будет себе огурчики солить и банки закатывать с помидорчиками. И картошечку он не будет себе жарить. \\u003c...\\u003e А мещанин и закатает, и поджарит, и угостит, и почирикает, и попоет над этой едой\\\". Назовите ИКСЫ двумя словами.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Уменьшительные суффиксы.\",\"answerPic\":\"\",\"zachet\":\"Уменьшительно-ласкательные суффиксы; Уменьшительные формы;\\\\nУменьшительно-ласкательные формы; Уменьшительно-ласкательные слова.\",\"nezachet\":\"\",\"comment\":\"\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. http://vozduh.afisha.ru/books/tatyana-tolstaya-mne-interesno-kakie-v-narode-kvarki/\\\\n2. http://www.ruspeach.com/learning/course334/lesson4637/\",\"authors\":[{\"id\":33,\"name\":\"Ольга Неумывакина\",\"gender\":\"HE\"}],\"editors\":[{\"id\":24,\"name\":\"Дмитрий Башук\",\"gender\":\"HE\"}],\"tour\":{\"id\":5513,\"number\":2,\"title\":\"\"},\"packId\":1404,\"packTitle\":\"Девятый круг\",\"controversials\":[{\"id\":40879,\"answer\":\"уменьшительные формы\",\"status\":\"A\",\"comment\":\"None\",\"appealJuryComment\":\"None\"},{\"id\":40889,\"answer\":\"Суффиксы  (капитан не успела написать определение)\",\"status\":\"D\",\"comment\":\"None\",\"appealJuryComment\":\"None\"}],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2016-08-18 00:00:00\",\"endDate\":\"2016-07-11 23:55:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[63],\"complexity\":[60.32],\"correct_answers\":[38],\"tournaments\":[{\"id\":3837,\"title\":\"Девятый круг\",\"typeoft\":{\"id\":3,\"title\":\"Синхрон\"}}]},{\"id\":79677,\"number\":27,\"text\":\"На одном шарже Кукрыниксов изображен Николай, который смотрит в зеркало и видит там Александра, Ивана и Дмитрия Илларионовича. Мы не просим вас назвать ни прозвища, ни фамилии троих последних. Напишите фамилию Николая.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Черкасов.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Великий русский актер Николай Константинович Черкасов видит в зеркале своих героев — Александра Невского, Ивана Грозного (из одноименных фильмов) и профессора Полежаева (героя фильма \\\"Депутат Балтики\\\").\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. http://terijoki.spb.ru/trk_terrasa.php\\\\n2. Д/ф \\\"Николай Черкасов\\\"\\\\n(http://tvkultura.ru/brand/show/brand_id/28702/) (4:38 — 4:50).\\\\n3. http://ru.wikipedia.org/wiki/Черкасов,_Николай_Константинович\",\"authors\":[{\"id\":552,\"name\":\"Алексей Каплиёв\",\"gender\":\"HE\"}],\"editors\":[{\"id\":525,\"name\":\"Дмитрий Свинтицкий\",\"gender\":\"HE\"},{\"id\":526,\"name\":\"Валерий Леонченко\",\"gender\":\"HE\"},{\"id\":1331,\"name\":\"Дмитрий Смирнов\",\"gender\":\"HE\"}],\"tour\":{\"id\":5551,\"number\":3,\"title\":\"\"},\"packId\":1413,\"packTitle\":\"Апрельские тезисы\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2016-08-16 00:00:00\",\"endDate\":\"2016-04-23 15:40:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[25],\"complexity\":[4],\"correct_answers\":[1],\"tournaments\":[{\"id\":3437,\"title\":\"Апрельские тезисы\",\"typeoft\":{\"id\":6,\"title\":\"Строго синхронный\"}}]},{\"id\":7086,\"number\":1,\"text\":\"Около трех веков на территории Оксфордского университета можно было видеть ИКС, появившийся здесь благодаря профессору, который раньше работал на Ближнем Востоке. Другому ИКСу принадлежат слова: \\\"Плавает всё! Красота\\\". Какое слово мы заменили ИКСом?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Кедр.\",\"answerPic\":\"\",\"zachet\":\"Точный ответ.\",\"nezachet\":\"\",\"comment\":\"В саду колледжа Крайст-Черч долгое время рос кедр, выращенный профессором Эдвардом Пококом из семян, привезенных с Ближнего Востока. “Кедр” — это позывной Юрия Гагарина. Упомянутая в вопросе реплика — реакция Гагарина на состояние невесомости.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"Барбара Такман. Библия и меч. Англия и Палестина от бронзового века до Бальфура\\\\nhttp://www.cosmoworld.ru/spaceencyclopedia/gagarin/index.shtml?doc10.html\",\"authors\":[{\"id\":416,\"name\":\"Михаил Карпук\",\"gender\":\"HE\"}],\"editors\":[{\"id\":416,\"name\":\"Михаил Карпук\",\"gender\":\"HE\"}],\"tour\":{\"id\":582,\"number\":1,\"title\":\"1\"},\"packId\":157,\"packTitle\":\"Чемпионат Израиля – США – Молдовы\",\"controversials\":[],\"appeals\":[],\"totalLikes\":1,\"totalDislikes\":0,\"pubDate\":\"2020-09-03 00:00:00\",\"endDate\":\"2016-04-20 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":89352,\"number\":1,\"text\":\"Около трех веков на территории Оксфордского университета можно было видеть ИКС, появившийся здесь благодаря профессору, который раньше работал на Ближнем Востоке. Другому ИКСУ принадлежат слова: \\\"Плавает всё! Красота\\\". Какое слово мы заменили ИКСОМ?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Кедр.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"В саду колледжа Крайст-Чёрч долгое время рос кедр, выращенный профессором Эдвардом Пококом из семян, привезенных с Ближнего Востока. \\\"Кедр\\\" — это позывной Юрия Гагарина. Упомянутая в вопросе реплика — реакция Гагарина на состояние невесомости.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. Б. Такман. Библия и меч. Англия и Палестина от бронзового века до\\\\nБальфура. http://www.flibusta.is/b/398719/read\\\\n2. http://www.cosmoworld.ru/spaceencyclopedia/gagarin/index.shtml?doc10.html\",\"authors\":[{\"id\":416,\"name\":\"Михаил Карпук\",\"gender\":\"HE\"}],\"editors\":[{\"id\":416,\"name\":\"Михаил Карпук\",\"gender\":\"HE\"}],\"tour\":{\"id\":6115,\"number\":1,\"title\":\"\"},\"packId\":1535,\"packTitle\":\"Чемпионат Израиля\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2016-05-10 00:00:00\",\"endDate\":\"2016-04-09 18:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[23],\"complexity\":[4.35],\"correct_answers\":[1],\"tournaments\":[{\"id\":3767,\"title\":\"Чемпионат Израиля\",\"typeoft\":{\"id\":2,\"title\":\"Обычный\"}}]},{\"id\":96651,\"number\":10,\"text\":\"Оксфордский профессор Ричард Докинз считает ИКС одним из наиболее неудачных изобретений человечества и предлагает хотя бы располовинить и запараллелить. Сквернослов РОулэнд Дженкс был вероятным источником эпидемии сыпного тифа, убившей в 1577 году более трехсот человек. Ее название обычно переводится на русский язык как \\\"Черный оксфордский ИКС\\\". Назовите ИКС двумя словами.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Суд присяжных. Незачет: Судебный процесс.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Книготорговец Роулэнд Дженкс грубо высказался о королеве, был посажен в тюрьму, а потом был привезен в Оксфорд на показательный суд, привезя с собой вшей, зараженных сыпным тифом. В ходе суда умерли два судьи и бОльшая часть присяжных, а потом эпидемия распространилась и на университет, и на город. Докинз предлагает разделить коллегию присяжных на две или три и запараллелить их работу.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. https://esquire.ru/richard-dawkins\\\\n2. http://www.litmir.co/br/?b=208269\\u0026p=8\\\\n3. http://www.encyclopatia.ru/wiki/Вши\\\\n4. http://en.wikipedia.org/wiki/Black_Assize_of_Oxford_1577\",\"authors\":[{\"id\":2652,\"name\":\"Алексей Тугарев\",\"gender\":\"HE\"}],\"editors\":[{\"id\":103,\"name\":\"Павел Казначеев\",\"gender\":\"HE\"}],\"tour\":{\"id\":6587,\"number\":1,\"title\":\"\"},\"packId\":1633,\"packTitle\":\"6 из 36\",\"controversials\":[{\"id\":33602,\"answer\":\"валенки\",\"status\":\"D\",\"comment\":\"Кажется, это спорный не на 10, а на 11 вопрос. Но и в этом случае неверно - какова может быть цель сбора детских валенок?\",\"appealJuryComment\":\"None\"}],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2016-01-23 00:00:00\",\"endDate\":\"2015-12-22 18:29:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[116],\"complexity\":[0.86],\"correct_answers\":[1],\"tournaments\":[{\"id\":3587,\"title\":\"6 из 36\",\"typeoft\":{\"id\":3,\"title\":\"Синхрон\"}}]},{\"id\":96740,\"number\":17,\"text\":\"Профессор ПиншОт предложил использовать для разведения китов ИКСы. Лев КассИль сравнил с ИКСом волосы пожилого персонажа. Назовите ИКС.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Атолл.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"ИКС представляет собой неплохую заготовку загона для кита. Цитата из Кассиля: \\\"Вокруг лысины росли торчком бурые волосы, лысина его была подобна лагуне в коралловом атолле\\\".\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. Томилин А.Г. В мире китов и дельфинов. — М.: Знание, 1980. — С.\\\\n210.\\\\n2. http://lib.ru/PROZA/KASSIL/kassil1.txt\",\"authors\":[{\"id\":71,\"name\":\"Борис Моносов\",\"gender\":\"HE\"}],\"editors\":[{\"id\":71,\"name\":\"Борис Моносов\",\"gender\":\"HE\"}],\"tour\":{\"id\":6593,\"number\":2,\"title\":\"\"},\"packId\":1635,\"packTitle\":\"Синхрон Моносова\",\"controversials\":[{\"id\":31802,\"answer\":\"Кораллы\",\"status\":\"D\",\"comment\":\"Отклонить (3:0). Ответ недостаточно точный. Кассиль не сравнивал волосы пожилого персонажа с кораллом.\",\"appealJuryComment\":\"None\"},{\"id\":31868,\"answer\":\"коралловые рифы\",\"status\":\"D\",\"comment\":\"None\",\"appealJuryComment\":\"None\"},{\"id\":31939,\"answer\":\"коралловый остров\",\"status\":\"A\",\"comment\":\"None\",\"appealJuryComment\":\"None\"},{\"id\":31679,\"answer\":\"лагуна\",\"status\":\"D\",\"comment\":\"None\",\"appealJuryComment\":\"None\"}],\"appeals\":[{\"id\":3451,\"questionNumber\":17,\"type\":\"A\",\"status\":\"D\",\"appeal\":\"Просим зачесть ответ \\\"Кораллы\\\",так как он полностью идентичен авторскому ответу.\\\\nАтолл – это КОРАЛЛ,мертвая оболочка полипов.С точки зрения химии – углекислый кальций или известняк.Возвышение на дне океана,которое увенчано КОРАЛЛОВОЙ надстройкой.\\\\nКОРАЛЛ атолла часто сидит на оправе потухшей подводной горы или вулкана, который разрушил или спал частично ниже воды.\\\\nСчитаем наш ответ абсолютно правильным.\",\"comment\":\"Отклонить (3:0). Ответ недостаточно точный. Кассиль не сравнивал волосы пожилого персонажа с кораллом.\",\"answer\":\"Кораллы\",\"azh\":[{\"id\":25580,\"firstName\":\"Евгений\",\"lastName\":\"Поникаров\",\"pID\":537},{\"id\":25120,\"firstName\":\"Виктор\",\"lastName\":\"Плотников\",\"pID\":2490},{\"id\":18332,\"firstName\":\"Александр\",\"lastName\":\"Либер\",\"pID\":220}],\"tournament\":{\"id\":3383,\"title\":\"Синхрон Моносова\",\"start\":\"2015-11-13T18:00:00\",\"end\":\"2015-11-17T18:00:00\"},\"qID\":96740,\"tID\":1635}],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2016-01-22 00:00:00\",\"endDate\":\"2015-11-17 18:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[439],\"complexity\":[17.31],\"correct_answers\":[76],\"tournaments\":[{\"id\":3383,\"title\":\"Синхрон Моносова\",\"typeoft\":{\"id\":3,\"title\":\"Синхрон\"}}]},{\"id\":112788,\"number\":21,\"text\":\"В 1991 году состоялось заседание британской палаты лордов, посвященное новым возможностям химии и промышленности. Предмет обсуждения, по словам профессора КрОто из Сассекского университета, был во столько же раз меньше ИКСА, во сколько раз ИКС меньше земного шара. Догадавшись, что именно обсуждалось, назовите ИКС двумя словами.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Футбольный мяч.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Обсуждалось применение недавно открытой молекулы фуллерЕна — модификации углерода, состоящей из шестидесяти атомов и похожей по строению на футбольный мяч.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"http://www.nkj.ru/archive/articles/4204/\",\"authors\":[{\"id\":436,\"name\":\"Валерий Юдачёв\",\"gender\":\"HE\"}],\"editors\":[{\"id\":267,\"name\":\"Максим Мерзляков\",\"gender\":\"HE\"}],\"tour\":{\"id\":7734,\"number\":2,\"title\":\"\"},\"packId\":1866,\"packTitle\":\"Пряничный домик. Второй этаж\",\"controversials\":[{\"id\":27200,\"answer\":\"футбольный матч\",\"status\":\"D\",\"comment\":\"None\",\"appealJuryComment\":\"None\"},{\"id\":27234,\"answer\":\"теннисный мяч\",\"status\":\"D\",\"comment\":\"None\",\"appealJuryComment\":\"None\"}],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2015-07-21 00:00:00\",\"endDate\":\"2015-06-24 14:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[209],\"complexity\":[23.92],\"correct_answers\":[50],\"tournaments\":[{\"id\":3184,\"title\":\"Пряничный домик. Второй этаж\",\"typeoft\":{\"id\":3,\"title\":\"Синхрон\"}}]},{\"id\":114005,\"number\":12,\"text\":\"Рассуждая о своей будущей смерти, профессор из романа СалмАна РУшди заявляет, что ТАКИЕ ИКСЫ не рады скучным СЯКИМ ИКСАМ. Что мы заменили словами \\\"ТАКОЙ ИКС\\\" и \\\"СЯКОЙ ИКС\\\"?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Могильный червь, книжный червь.\",\"answerPic\":\"\",\"zachet\":\"Земляной червь, книжный червь.\",\"nezachet\":\"\",\"comment\":\"Книжными червями иронично называют начитанных людей, библиофилов. Профессор считал, что книжными червями могильные не питаются.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"С. Рушди. Ярость. http://www.flibusta.net/b/237883/read\",\"authors\":[{\"id\":99,\"name\":\"Илья Кукушкин\",\"gender\":\"HE\"}],\"editors\":[{\"id\":99,\"name\":\"Илья Кукушкин\",\"gender\":\"HE\"},{\"id\":267,\"name\":\"Максим Мерзляков\",\"gender\":\"HE\"},{\"id\":319,\"name\":\"Евгений Половой\",\"gender\":\"HE\"}],\"tour\":{\"id\":7836,\"number\":1,\"title\":\"\"},\"packId\":1885,\"packTitle\":\"Не стыдно показать\",\"controversials\":[{\"id\":26508,\"answer\":\"могильные книжные\",\"status\":\"D\",\"comment\":\"\",\"appealJuryComment\":\"None\"}],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2015-07-14 00:00:00\",\"endDate\":\"2015-05-12 18:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[55],\"complexity\":[16.36],\"correct_answers\":[9],\"tournaments\":[{\"id\":3309,\"title\":\"Не стыдно показать\",\"typeoft\":{\"id\":3,\"title\":\"Синхрон\"}}]},{\"id\":125752,\"number\":9,\"text\":\"В математическом анекдоте Фурье умирает, и вскоре из его могилы начинают доноситься странные звуки, что-то вроде: \\\"Синус икс... плюс два косинус икс... плюс три пятых синус двух икс...\\\" и так далее. Вызванный на место происшествия профессор успокаивает публику. Закончите его фразу одним словом: \\\"Ничего страшного, это просто...\\\".\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Разложение.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Анекдот основан на двух смыслах слова \\\"разложение\\\": разложение функции в ряд Фурье и разложение мёртвого тела.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"http://koteljnik.livejournal.com/702771.html?thread=21575987#t21575987\",\"authors\":[{\"id\":707,\"name\":\"Юрий Выменец\",\"gender\":\"HE\"}],\"editors\":[{\"id\":707,\"name\":\"Юрий Выменец\",\"gender\":\"HE\"}],\"tour\":{\"id\":8529,\"number\":1,\"title\":\"\"},\"packId\":2014,\"packTitle\":\"Кубок 359\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2015-03-06 00:00:00\",\"endDate\":\"2015-02-02 23:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[262],\"complexity\":[72.9],\"correct_answers\":[191],\"tournaments\":[{\"id\":3034,\"title\":\"Кубок 359\",\"typeoft\":{\"id\":3,\"title\":\"Синхрон\"}}]},{\"id\":126052,\"number\":31,\"text\":\"[Ведущему: кавычки не озвучивать.]\\\\nПрофессор Белецкий пишет, что изначально ОНА \\\"поселилась в Дрездене\\\", но могла бы погибнуть, если бы своевременно не побывала в Москве. Перед НЕЙ преклонялись Жуковский, Пушкин, Гоголь, Белинский, Гончаров, Герцен — если всех перечислять, то пальцев на руке не хватит. Назовите ЕЕ.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"\\\"Сикстинская Мадонна\\\".\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"По окончании Второй мировой войны московские реставраторы вернули знаменитому шедевру Рафаэля первозданную красу. Мы неслучайно упомянули именно шестерых ценителей \\\"Мадонны\\\", ведь распространено заблуждение, будто имя \\\"Сикст\\\" означает \\\"шесть\\\" и на картине якобы есть шестипалая рука.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. П. Бiлецький. Рафаель. — К.: Мистецтво, 1990. — С. 14.\\\\nhttp://www.refine.org.ua/pageid-3462-2.html\\\\n2. http://ru.wikipedia.org/wiki/Сикстинская_Мадонна\\\\n3. http://www.powerwriter.ru/picture0393.htm\",\"authors\":[{\"id\":790,\"name\":\"Виктор Мялов\",\"gender\":\"HE\"}],\"editors\":[{\"id\":790,\"name\":\"Виктор Мялов\",\"gender\":\"HE\"}],\"tour\":{\"id\":8549,\"number\":3,\"title\":\"\"},\"packId\":2019,\"packTitle\":\"Корабль Тесея\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2015-03-01 00:00:00\",\"endDate\":\"2015-01-20 17:55:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[124],\"complexity\":[45.16],\"correct_answers\":[56],\"tournaments\":[{\"id\":3123,\"title\":\"Корабль Тесея\",\"typeoft\":{\"id\":3,\"title\":\"Синхрон\"}}]},{\"id\":135622,\"number\":25,\"text\":\"СавАнты — это люди с отклонениями в развитии, имеющие, однако, выдающиеся способности в какой-то области. Большинство савАнтов не может объяснить, как им удается использовать свою феноменальные способности. Говоря об уникальности савАнта Дэниела ТАммета, профессор Аллан Снайдер сравнивает ТАммета с НИМ. ЕГО инвентарный номер — EA [и-эй] 24. Назовите ЕГО.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Розеттский камень.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Изучение того, как работает мозг ТАммета, может помочь лучше понять природу савАнтов, подобно тому как Розеттский камень помог разгадать египетские иероглифы. EA — Egyptian Antiques [иджИпшан антИкс] — египетские древности.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. http://en.wikipedia.org/wiki/Daniel_Tammet\\\\n2. http://ru.wikipedia.org/wiki/Розеттский_камень\",\"authors\":[{\"id\":48,\"name\":\"Анвар Мухаметкалиев\",\"gender\":\"HE\"}],\"editors\":[{\"id\":48,\"name\":\"Анвар Мухаметкалиев\",\"gender\":\"HE\"},{\"id\":251,\"name\":\"Александр Толесников\",\"gender\":\"HE\"},{\"id\":484,\"name\":\"Наиль Фарукшин\",\"gender\":\"HE\"}],\"tour\":{\"id\":9150,\"number\":2,\"title\":\"\"},\"packId\":2155,\"packTitle\":\"Гран-при. 1 этап\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2014-11-09 00:00:00\",\"endDate\":\"2014-10-27 23:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[218],\"complexity\":[11.47],\"correct_answers\":[25],\"tournaments\":[{\"id\":2930,\"title\":\"Гран-при. 1 этап\",\"typeoft\":{\"id\":3,\"title\":\"Синхрон\"}}]},{\"id\":146823,\"number\":57,\"text\":\"Описывая знаменитый портрет Фрэнсиса Дрейка, профессор Джереми Айдельман говорит, что положение правой руки мореплавателя символизирует могущество британского флота, и в шутку замечает, что сам Дрейк никогда не занимался ИКСОМ. ИКС является детищем другого преподавателя. Какое слово мы заменили ИКСОМ?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Баскетбол.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Дрейк держит правую руку на глобусе, в наше время такое положение руки на круглом предмете характерно для фотографий спортсменов, держащих мяч. Баскетбол зародился в конце XIX века благодаря профессору Нейсмиту.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. https://class.coursera.org/wh1300-002/lecture/27\\\\n2. http://en.wikipedia.org/wiki/Basketball\\\\n3. http://en.wikipedia.org/wiki/James_Naismith\",\"authors\":[{\"id\":3717,\"name\":\"Владимир Пономарёв\",\"gender\":\"HE\"}],\"editors\":[{\"id\":309,\"name\":\"Иван Карбовник\",\"gender\":\"HE\"},{\"id\":567,\"name\":\"Константин Науменко\",\"gender\":\"HE\"},{\"id\":3717,\"name\":\"Владимир Пономарёв\",\"gender\":\"HE\"}],\"tour\":{\"id\":9785,\"number\":5,\"title\":\"\"},\"packId\":2311,\"packTitle\":\"Пущинские дали\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":1,\"pubDate\":\"2014-08-11 00:00:00\",\"endDate\":\"2014-07-12 23:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[29],\"complexity\":[62.07],\"correct_answers\":[18],\"tournaments\":[{\"id\":2939,\"title\":\"Пущинские дали\",\"typeoft\":{\"id\":2,\"title\":\"Обычный\"}}]},{\"id\":67715,\"number\":60,\"text\":\"Профессор Сергей Мамонтов пишет, что ИКС и его семья должны были болеть примерно 500 заболеваниями, вызываемыми паразитами. Назовите ИКСА.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Ной.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Иначе паразиты бы не сохранились.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"http://www.isps.su/rez/vertyanov.html\",\"authors\":[{\"id\":72,\"name\":\"Александр Коробейников\",\"gender\":\"HE\"}],\"editors\":[{\"id\":24,\"name\":\"Дмитрий Башук\",\"gender\":\"HE\"},{\"id\":72,\"name\":\"Александр Коробейников\",\"gender\":\"HE\"}],\"tour\":{\"id\":4745,\"number\":1,\"title\":\"Групповой этап. Первый круг\"},\"packId\":1231,\"packTitle\":\"XVI Чемпионат Украины по брэйн-рингу (Николаев)\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2017-03-28 00:00:00\",\"endDate\":\"2014-06-08 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":158868,\"number\":41,\"text\":\"Автор допускает, что для взятия этого вопроса трезвый способ мышления необязателен.\\\\nАмериканский профессор рассказывает, что для получения материала фосфорена ученые использовали ЕЕ. ОНА была нужна, чтобы отделить тончайшие слои черного фосфора. Этот метод получил название ИКС-техника. Какое слово мы заменили на ИКС?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Скотч.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"ОНА — клейкая лента. С ее помощью отделяли тонкие слои этих материалов вручную. Скотч — не только клейкая лента, но и разновидность виски. \\\"Нетрезвый способ мысли\\\" на него и намекает.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"http://www.nauka21vek.ru/archives/55817\",\"authors\":[{\"id\":685,\"name\":\"Дмитрий Некрылов\",\"gender\":\"HE\"}],\"editors\":[{\"id\":685,\"name\":\"Дмитрий Некрылов\",\"gender\":\"HE\"},{\"id\":897,\"name\":\"Мария Клименко\",\"gender\":\"HE\"},{\"id\":898,\"name\":\"Евгений Сибиряк\",\"gender\":\"HE\"}],\"tour\":{\"id\":10442,\"number\":3,\"title\":\"\"},\"packId\":2455,\"packTitle\":\"31 февраля\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2014-04-28 00:00:00\",\"endDate\":\"2014-03-29 22:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[61],\"complexity\":[19.67],\"correct_answers\":[12],\"tournaments\":[{\"id\":2793,\"title\":\"31 февраля\",\"typeoft\":{\"id\":3,\"title\":\"Синхрон\"}}]},{\"id\":161857,\"number\":11,\"text\":\"Профессор-искусствовед А. Липков углубился в изучение некоторых подробностей культуры быта средневековой Европы и был, надо сказать, шокирован некоторыми из них. По итогам изучения вопроса он издал первый в России тематический труд \\\"ИКС к ИГРЕКУ\\\". Воспроизведите название, если авторы вопроса считают, что ИКС является наиболее характерным местом ИГРЕКА.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"\\\"Толчок к размышлению\\\".\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"http://modernlib.ru/books/lipkov_aleksandr/tolchok_k_razmishleniyu/read_1/\",\"authors\":[{\"id\":6731,\"name\":\"Варвара Секова\",\"gender\":\"HE\"}],\"editors\":[],\"tour\":{\"id\":10640,\"number\":10,\"title\":\"10 тур. \\\"Пацаны ваще котята\\\"\"},\"packId\":2493,\"packTitle\":\"Окский марафон - 2014 (Пущино)\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2014-03-21 00:00:00\",\"endDate\":\"2014-02-01 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":175992,\"number\":9,\"text\":\"Википедия отмечает, что героя комиксов Профессора Икс, мечтавшего о мирном сосуществовании между людьми и мутантами, часто сравнивают с ПЕРВЫМ, в то время как радикально настроенного Магнето — со ВТОРЫМ. Назовите ПЕРВОГО и ВТОРОГО.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"[Мартин Лютер] Кинг, [Малькольм] Икс.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Мартин Лютер Кинг тоже много мечтал, ну а Малькольма Икса фамилия обязывает.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"http://ru.wikipedia.org/wiki/Люди_Икс\",\"authors\":[{\"id\":228,\"name\":\"Юрий Вашкулат\",\"gender\":\"HE\"}],\"editors\":[{\"id\":228,\"name\":\"Юрий Вашкулат\",\"gender\":\"HE\"},{\"id\":540,\"name\":\"Александр Чижов\",\"gender\":\"HE\"}],\"tour\":{\"id\":11418,\"number\":3,\"title\":\"Отборочный этап. 3 тур\"},\"packId\":2675,\"packTitle\":\"Чемпионат мира по ЧГК (Дубна, 2013)\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2013-09-29 00:00:00\",\"endDate\":\"2013-09-14 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":165825,\"number\":51,\"text\":\"Внимание, слово \\\"ИКС\\\" — замена.\\\\nВо время путешествия Байрон сравнил один из ИКСОВ с \\\"хвостом коня-гиганта, на котором в виденье Иоанна мчится Смерть\\\". Другой ИКС известен, в том числе, в связи со смертью ученого. Назовите этого ученого.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"[Профессор Джеймс] Мориарти.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Речь идет о водопадах. Профессор Мориарти из произведений о Шерлоке Холмсе погиб в Рейхенбахском водопаде, который, кстати, находится неподалеку от водопада, описанного Байроном.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. http://www.c-portal.ru/books/read/501/21\\\\n2. http://novopedia.net/wiki/Профессор_Мориарти\",\"authors\":[{\"id\":1801,\"name\":\"Евгений Ярков\",\"gender\":\"HE\"}],\"editors\":[{\"id\":1818,\"name\":\"Сергей Ефимов\",\"gender\":\"HE\"}],\"tour\":{\"id\":10816,\"number\":5,\"title\":\"\"},\"packId\":2544,\"packTitle\":\"Black Sea Open\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2014-01-11 00:00:00\",\"endDate\":\"2013-07-27 23:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[56],\"complexity\":[51.79],\"correct_answers\":[29],\"tournaments\":[{\"id\":2183,\"title\":\"Black Sea Open\",\"typeoft\":{\"id\":2,\"title\":\"Обычный\"}}]},{\"id\":167865,\"number\":71,\"text\":\"Во второй книге Паралипоменон говорится, что среди прочих украшений в иерусалимском храме было ТАКОЕ море — \\\"от края до края десять локтей, и шнурок в тридцать локтей обнимал его\\\". Эту цитату профессор Сэмюэл Дикс приводит, пародируя требования креационистов изучать не только эволюционную теорию. Напишите слово, которое мы заменили на \\\"ТАКОЕ\\\".\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Круглое.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Несложно посчитать, что библейское Пи равняется ровно трем. Профессор Дикс говорит, что раз креационисты требуют изучать библейскую теорию наряду с эволюционной, то нужно посвятить должное время и изучению библейской математики, в которой Пи не будет иррациональным числом.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. 2 Паралипоменон 4:2. http://www.gmpage.com/library/bible/14.htm#4\\\\n2. J.L. Berggren, Jonathan M. Borwein, Peter Borwein. Pi: A Source\\\\nBook. P. 458-459. http://books.google.ru/books?id=QlbzjN_5pDoC\",\"authors\":[{\"id\":40,\"name\":\"Михаил Иванов\",\"gender\":\"HE\"}],\"editors\":[{\"id\":40,\"name\":\"Михаил Иванов\",\"gender\":\"HE\"}],\"tour\":{\"id\":10947,\"number\":5,\"title\":\"\"},\"packId\":2574,\"packTitle\":\"Саратов\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2013-12-15 00:00:00\",\"endDate\":\"2013-05-10 23:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[37],\"complexity\":[35.14],\"correct_answers\":[13],\"tournaments\":[{\"id\":2287,\"title\":\"Саратов\",\"typeoft\":{\"id\":2,\"title\":\"Обычный\"}}]},{\"id\":186579,\"number\":9,\"text\":\"Во второй книге Паралипоменон говорится, что среди прочих украшений в иерусалимском храме было ТАКОЕ море — \\\"от края до края десять локтей, и снурок в тридцать локтей обнимал его\\\". Эту цитату профессор Сэмюэл Дикс упоминает, пародируя требование креационистов изучать не только эволюционную теорию. Какое слово мы заменили на \\\"ТАКОЕ\\\"?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Круглое.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Несложно посчитать, что библейское Пи равняется ровно трем. Профессор Дикс говорит, что раз креационисты требуют изучать библейскую теорию наряду с эволюционной, то нужно посвятить должное время и изучению библейской математики, в которой Пи не будет иррациональным числом.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. http://www.gmpage.com/library/bible/14.htm#4 (2 Паралипоменон\\\\n4:2)\\\\n2. J.L. Berggren, Jonathan M. Borwein, Peter Borwein. Pi: A Source\\\\nBook. P. 458-459.\\\\nhttp://books.google.ru/books?id=QlbzjN_5pDoC\\u0026printsec=frontcover\\u0026hl=ru\",\"authors\":[{\"id\":40,\"name\":\"Михаил Иванов\",\"gender\":\"HE\"}],\"editors\":[{\"id\":40,\"name\":\"Михаил Иванов\",\"gender\":\"HE\"}],\"tour\":{\"id\":11962,\"number\":2,\"title\":\"\"},\"packId\":2826,\"packTitle\":\"Молодежный чемпионат Украины по ЧГК (Одесса)\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2013-06-16 00:00:00\",\"endDate\":\"2013-05-02 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":188058,\"number\":84,\"text\":\"Профессор Ларднер из Лондонского университета доказал, что для любой точки внутри прямоугольника сумма площадей квадратов, обозначенных красным, равна сумме площадей квадратов, обозначенных синим. Для доказательства нужно провести перпендикуляры к четырем сторонам. Это утверждение называется теоремой ИКСА. Какое имя есть в английском названии ИКСА?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"/pics/2858/188058_razdatka.jpg\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Джек.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"После проведения перпендикуляров чертеж становится похожим на британский флаг.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. http://en.wikipedia.org/wiki/British_flag_theorem\\\\n2. http://books.google.lv/books?id=5INRAAAAYAAJ\\u0026pg=PA87\",\"authors\":[{\"id\":3327,\"name\":\"Юрий Шатц\",\"gender\":\"HE\"}],\"editors\":[{\"id\":795,\"name\":\"Александр Ведехин\",\"gender\":\"HE\"},{\"id\":3327,\"name\":\"Юрий Шатц\",\"gender\":\"HE\"},{\"id\":4830,\"name\":\"Вадим Ермак\",\"gender\":\"HE\"}],\"tour\":{\"id\":12070,\"number\":6,\"title\":\"\"},\"packId\":2858,\"packTitle\":\"Студенческий чемпионат России\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2013-05-09 00:00:00\",\"endDate\":\"2013-04-20 23:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[51],\"complexity\":[64.71],\"correct_answers\":[33],\"tournaments\":[{\"id\":2245,\"title\":\"Студенческий чемпионат России\",\"typeoft\":{\"id\":2,\"title\":\"Обычный\"}}]},{\"id\":190062,\"number\":44,\"text\":\"Внимание, в вопросе ИКС заменяет два слова.\\\\nПрофессор Иэн Стюарт сравнил ИКС с одеялом. Статья о каком режиссере называется \\\"ИКС\\\"?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"[Франсуа] Озон.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"ИКС — озоновый слой — своего рода защитное одеяло Земли.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. Д/ф \\\"How To Grow The Planet\\\", 2012 г.\\\\n2. http://www.snigirevka.info/load/ozonovyj_sloj_chast_1/117-1-0-1145\",\"authors\":[{\"id\":72,\"name\":\"Александр Коробейников\",\"gender\":\"HE\"}],\"editors\":[{\"id\":72,\"name\":\"Александр Коробейников\",\"gender\":\"HE\"},{\"id\":540,\"name\":\"Александр Чижов\",\"gender\":\"HE\"},{\"id\":1483,\"name\":\"Дмитрий Стрильчук\",\"gender\":\"HE\"}],\"tour\":{\"id\":12172,\"number\":3,\"title\":\"\"},\"packId\":2888,\"packTitle\":\"Кубок Хайфы\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2013-04-13 00:00:00\",\"endDate\":\"2013-01-12 22:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[26],\"complexity\":[15.39],\"correct_answers\":[4],\"tournaments\":[{\"id\":2250,\"title\":\"Кубок Хайфы\",\"typeoft\":{\"id\":2,\"title\":\"Обычный\"}}]},{\"id\":187165,\"number\":2,\"text\":\"Герой Владислава Крапивина профессор Чайнозаварский предлагал сделать ИКСЫ частью школьной формы. По его мнению, после этого сразу же будут решены проблемы с дисциплиной и успеваемостью. Назовите известное произведение, героиня которого на практике испытала с полдюжины ИКСОВ и ее выводы были прямо противоположны мнению Чайнозаварского.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"\\\"Мартышка и очки\\\".\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"ИКСЫ — очки; \\\"А проку на-волос нет в них\\\", — пришла к выводу Мартышка в басне И.А. Крылова.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. В. Крапивин. Возвращение клипера \\\"Кречет\\\"\\\\n(http://www.litmir.net/br/?b=89230\\u0026p=6).\\\\n2. И. Крылов. Мартышка и очки\\\\n(http://www.kinderbooks.ru/publications/view/28/page/1095).\",\"authors\":[{\"id\":790,\"name\":\"Виктор Мялов\",\"gender\":\"HE\"}],\"editors\":[{\"id\":24,\"name\":\"Дмитрий Башук\",\"gender\":\"HE\"},{\"id\":224,\"name\":\"Игорь Волобуев\",\"gender\":\"HE\"}],\"tour\":{\"id\":12004,\"number\":1,\"title\":\"\"},\"packId\":2841,\"packTitle\":\"Школьный чемпионат Беларуси\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2013-05-11 00:00:00\",\"endDate\":\"2012-04-21 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":195285,\"number\":7,\"text\":\"Серия рекламных плакатов утверждает, что ИКСЫ делают из доступной женщины — недоступную, из водителя грузовика — профессора, из байкера — модного дизайнера. Известная героиня однажды раздобыла с полдюжины ИКСОВ. Что такое ИКСЫ?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Очки.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Упомянутая героиня — Мартышка из басни Крылова.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. http://www.adme.ru/kreativnyj-obzor/vse-genialnoe-prosto-275955/\\\\n2. http://www.kinderbooks.ru/publications/view/28/page/1095\",\"authors\":[{\"id\":553,\"name\":\"Андрий Бойко\",\"gender\":\"HE\"}],\"editors\":[{\"id\":24,\"name\":\"Дмитрий Башук\",\"gender\":\"HE\"},{\"id\":224,\"name\":\"Игорь Волобуев\",\"gender\":\"HE\"}],\"tour\":{\"id\":12497,\"number\":5,\"title\":\"Старшая возрастная группа. Игры основного этапа\"},\"packId\":2971,\"packTitle\":\"Чемпионат Украины по брэйн-рингу среди школьников (Ялта)\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2013-02-07 00:00:00\",\"endDate\":\"2012-03-26 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":224078,\"number\":14,\"text\":\"О профессоре Челленджере говорили, что он способен перессорить даже ИКСОВ на собрании. \\\"ИКС\\\" — прозвище предводителя хулиганов в произведении Владислава Крапивина. Какое слово мы заменили \\\"ИКСОМ\\\"?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Квакер.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Квакеры — представители религиозного течения, люди очень смирные. Прозвище отрицательного персонажа Крапивина перекликается с фамилией Миши Квакина из повести Гайдара \\\"Тимур и его команда\\\".\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. А. Конан Дойль. Отравленный пояс.\\\\nhttp://www.flibusta.net/b/66726/read\\\\n2. В. Крапивин. Гваделорка. http://www.flibusta.net/b/242167/read\\\\n3. А. Гайдар. Тимур и его команда.\\\\nhttp://www.flibusta.net/b/103588/read\",\"authors\":[{\"id\":267,\"name\":\"Максим Мерзляков\",\"gender\":\"HE\"}],\"editors\":[{\"id\":220,\"name\":\"Александр Либер\",\"gender\":\"HE\"},{\"id\":1818,\"name\":\"Сергей Ефимов\",\"gender\":\"HE\"}],\"tour\":{\"id\":13988,\"number\":4,\"title\":\"\"},\"packId\":3289,\"packTitle\":\"Чемпионат Украины по ЧГК сезона 2011/12. Высшая и первая лиги, 2 этап (Харьковская область)\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2012-04-11 00:00:00\",\"endDate\":\"2012-03-10 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":136770,\"number\":23,\"text\":\"В рассказе о знаменитом потомке захолустных помещиков фигурирует альпийский ОН, где нашел смерть ИКС. Однако в 1980 году роль альпийского ЕГО сыграл абхазский. Мы не спрашиваем вас о НЕМ. Назовите ИКСА.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Мориарти.\",\"answerPic\":\"\",\"zachet\":\"Профессор Мориарти, Джеймс Мориарти.\",\"nezachet\":\"\",\"comment\":\"ОН — это водопад. В рассказе \\\"Последнее дело Холмса\\\" фигурирует Рейхенбахский водопад, который находится в Швейцарии. Враг Холмса — Мориарти гибнет в водопаде. В \\\"роли\\\" Рейхенбахского водопада в знаменитом советском фильме \\\"Приключения Шерлока Холмса и доктора Ватсона\\\" \\\"снялся\\\" Гегский водопад в Абхазской АССР. А в рассказе \\\"Случай с переводчиком\\\" Холмс рассказывает: \\\"Предки мои были захолустными помещиками...\\\".\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. http://ru.wikipedia.org/wiki/Рейхенбахский_водопад\\\\n2. http://www.221b.ru/geoPart4.htm\\\\n3. http://ru.wikipedia.org/wiki/Шерлок_Холмс\",\"authors\":[{\"id\":5946,\"name\":\"Александр Ермаков\",\"gender\":\"HE\"}],\"editors\":[],\"tour\":{\"id\":9201,\"number\":13,\"title\":\"13 тур. \\\"Чаатал-Хуюк\\\" (Коломна)\"},\"packId\":2161,\"packTitle\":\"Окский марафон - 2012 (Пущино)\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2014-11-07 00:00:00\",\"endDate\":\"2012-01-28 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":136772,\"number\":1,\"text\":\"В ответ на предложение профессора Фарнсворта воссоздать условия, предшествовавшие Большому Взрыву, и высказанное им сожаление о том, что он уже слишком стар, чтоб дожить до конца этого эксперимента, Туранга Лила ответила: \\\"Я удивлена, что вы дожили до ИКСА\\\". В ИКСЕ есть \\\"синхрофазотрон\\\". Какие три слова мы заменили ИКСОМ?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Конец этого предложения.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"В конце предложения \\\"В конце этого предложения есть \\\"синхрофазотрон\\\"\\\" действительно есть \\\"синхрофазотрон\\\". А мы решили начать свой тур с конца.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"http://www.theinfosphere.org/Transcript:Reincarnation\",\"authors\":[],\"editors\":[],\"tour\":{\"id\":9202,\"number\":14,\"title\":\"14 тур. \\\"Биркиркара\\\" (Москва)\"},\"packId\":2161,\"packTitle\":\"Окский марафон - 2012 (Пущино)\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2014-11-07 00:00:00\",\"endDate\":\"2012-01-28 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":401127,\"number\":44,\"text\":\"Громоздкие рога взрослого оленя мешают ему передвигаться и являются малоэффективным оружием. Однако они внушают молодым оленям боязливое почтение. В одном романе такие рога сравниваются с ИКСОМ. Известно, что ИКС был в ранце солдат наполеоновской армии. Назовите ИКС двумя словами.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"маршальский жезл\",\"answerPic\":\"\",\"zachet\":\"точный ответ.\",\"nezachet\":\"\",\"comment\":\"«И профессор, … провел параллель между оленьим рогом и маршальским жезлом, который, будучи весьма слабым оружием в бою, тем не менее, делает своего обладателя физически неприкосновенным, ибо внушает трепет и почтение окружающим».\\\\nИзвестно высказывание Наполеона о том, что каждый солдат его армии носит в ранце маршальский жезл.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"http://tapirr.narod.ru/texts/hudlit/tournier/turn_ltzar.html\\\\nhttp://ru.wikipedia.org/wiki/Маршальский_жезл\",\"authors\":[{\"id\":66,\"name\":\"Алексей Полевой\",\"gender\":\"HE\"}],\"editors\":[{\"id\":66,\"name\":\"Алексей Полевой\",\"gender\":\"HE\"}],\"tour\":{\"id\":25348,\"number\":3,\"title\":\"\"},\"packId\":5954,\"packTitle\":\"Школьный синхронный Чемпионат Беларуси\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":1,\"pubDate\":\"2024-08-22 16:27:10.665234\",\"endDate\":\"2012-01-22 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":197877,\"number\":7,\"text\":\"Внимание, в вопросе словом \\\"ИКС\\\" заменено другое слово.\\\\nИКС героя произведений Конан Дойла профессора Челленджера напоминал колючую проволоку. Репортер Мелоун имел возможность убедиться в этом непосредственно перед тем, как узнал о согласии профессора принять его у себя дома. Какое слово мы обозначили как ИКС?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Почерк.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"О приглашении Мелоун узнал из письма профессора.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"А. Конан Дойл. Затерянный мир\\\\n(http://lib.kharkov.ua/AKONANDOJL/lostwrld.txt).\",\"authors\":[{\"id\":223,\"name\":\"Татьяна Лещенко\",\"gender\":\"HE\"}],\"editors\":[{\"id\":2735,\"name\":\"Михаил Серопян\",\"gender\":\"HE\"}],\"tour\":{\"id\":12629,\"number\":1,\"title\":\"\"},\"packId\":2989,\"packTitle\":\"Кубок губернатора Краснодарского края (Краснодар)\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2013-01-08 00:00:00\",\"endDate\":\"2011-12-03 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":254477,\"number\":35,\"text\":\"Чтобы наблюдать развитие болезни в прозрачной среде, профессор Конгейм вводил бактерии в ИКСы. Надеемся, вам знакома строчка 1906 года, в которой упоминаются ИКСы. Процитируйте ее.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"И пьяницы с глазами кроликов.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"ИКСы — глаза кроликов. Строчка — из стихотворения Блока \\\"Незнакомка\\\".\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. Крюи П. де. Охотники за микробами. — СПб.: Амфора, 2006. — С. 131.\\\\n2. http://www.litera.ru/stixiya/authors/blok/po-vecheram-nad.html\",\"authors\":[{\"id\":71,\"name\":\"Борис Моносов\",\"gender\":\"HE\"}],\"editors\":[{\"id\":71,\"name\":\"Борис Моносов\",\"gender\":\"HE\"}],\"tour\":{\"id\":15394,\"number\":3,\"title\":\"\"},\"packId\":3622,\"packTitle\":\"Монос вызга\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2011-10-12 00:00:00\",\"endDate\":\"2011-09-17 23:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[535],\"complexity\":[13.83],\"correct_answers\":[74],\"tournaments\":[{\"id\":1906,\"title\":\"Монос вызга\",\"typeoft\":{\"id\":3,\"title\":\"Синхрон\"}}]},{\"id\":122546,\"number\":10,\"text\":\"Анекдот из серии \\\"Физики шутят\\\":\\\\nБежит студент со всех ног по коридору. Из-за угла неожиданно выходит профессор, и студент в него врезается, да так, что профессор валится на пол. Профессор поднимается и говорит: \\\"хорошо, что пополам\\\".\\\\n— Что пополам? — спрашивает ошарашенный студент.\\\\n— ИКС.\\\\nУкажите в правильном порядке три символа, которые мы заменили на ИКС.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"mv^2 [эм вэ квадрат].\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"mv^2/2 — формула кинетической энергии.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"Анекдот.\",\"authors\":[{\"id\":5575,\"name\":\"Маргарита Фатина\",\"gender\":\"HE\"}],\"editors\":[{\"id\":5562,\"name\":\"Юлия Малютина\",\"gender\":\"HE\"}],\"tour\":{\"id\":8340,\"number\":6,\"title\":\"3.2. \\\"ZaNova\\\"\"},\"packId\":1971,\"packTitle\":\"Вторая лига Москвы сезона 2010/11 гг. Дивизион \\\"Бауманка\\\"\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2015-04-12 00:00:00\",\"endDate\":\"2011-02-26 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":122623,\"number\":5,\"text\":\"Если вы страдаете цветовой слепотой, перед вами будет лишь набор бессмысленных пикселей. Если у вас всё в порядке, Вы сможете различить персонажей известного мультсериала. Какого?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"/pics/1971/122623_razdatka.jpg\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"\\\"Футурама\\\".\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"На картинке можно узнать следующих персонажей (по порядку, слева направо, сверху вниз): Фрай, Бендер, Лила, Эми, доктор Зойдберг, Скаффи, Гермес, профессор Фарнсворт, Зепп Бранниган и Киф Крокер.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. http://www.gadgetblog.ru/4044/\\\\n2. http://ru.wikipedia.org/wiki/Футурама\",\"authors\":[{\"id\":5590,\"name\":\"Дмитрий Плахов\",\"gender\":\"HE\"}],\"editors\":[{\"id\":5565,\"name\":\"Софья Чайкун\",\"gender\":\"HE\"}],\"tour\":{\"id\":8347,\"number\":11,\"title\":\"6.1. \\\"Дождик\\\"\"},\"packId\":1971,\"packTitle\":\"Вторая лига Москвы сезона 2010/11 гг. Дивизион \\\"Бауманка\\\"\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2015-04-12 00:00:00\",\"endDate\":\"2011-02-26 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":154285,\"number\":16,\"text\":\"Профессор Фигуровский разработал систему ТАКИХ ИКСОВ, что потребовало немалых исторических изысканий. В нее вошли, например, богемий и короний. Примечательно, что несколько ТАКИХ ИКСОВ появились благодаря Дмитрию Ивановичу. Что мы заменили словами \\\"ТАКИЕ ИКСЫ\\\"?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Ирреальные/ошибочные/ложные элементы.\",\"answerPic\":\"\",\"zachet\":\"По смыслу.\",\"nezachet\":\"\",\"comment\":\"\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"М.Г. Воронков, А.Ю. Рулев. О химии с улыбкой, или Основы пегниохимии. —\\\\nМ.: Наука, 1999.\",\"authors\":[{\"id\":2445,\"name\":\"Данила Аладин\",\"gender\":\"HE\"}],\"editors\":[],\"tour\":{\"id\":10208,\"number\":23,\"title\":\"23 тур. \\\"Южное Подмосковье\\\" (Пущино - Серпухов)\"},\"packId\":2408,\"packTitle\":\"Окский марафон - 2011 (Пущино)\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2014-06-27 00:00:00\",\"endDate\":\"2011-01-29 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":260935,\"number\":11,\"text\":\"Продолжим. Засчитывается только правильный ответ. Шутка.\\\\nВ систематике в названии растений нередки случаи использования фамилий. Например: пихта Нордмана (финский профессор), или раффлезия Арнольда (Арнольд — доктор в экспедиции Раффлза из прошлого вопроса) и др. Вот и экскурсоводы в районе Демерджи (это не Кавказ, а в Крыму под Алуштой) любят показывать туристам сохранившийся до сих пор \\\"орех ИКСА\\\". ИКС — это фамилия. Назовите ее.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Никулин.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Орех Никулина — с которого в к/ф \\\"Кавказская пленница\\\" Балбес кидался орехами. По задумке относительно веселый тон вопроса настраивал на что-то веселое (на комедию, например). Опять же, Арнольд — \\\"левый\\\" для ботаники человек, значит и ИКС, возможно, стоит искать совсем не среди ботаников. Кроме того, то, что \\\"Кавказская пленница\\\" снималась в Крыму — известная фишка.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"http://www.ecoethics.ru/oreh-nikulina/\",\"authors\":[{\"id\":8993,\"name\":\"Дмитрий Шилко\",\"gender\":\"HE\"}],\"editors\":[{\"id\":8993,\"name\":\"Дмитрий Шилко\",\"gender\":\"HE\"}],\"tour\":{\"id\":15789,\"number\":2,\"title\":\"\"},\"packId\":3698,\"packTitle\":\"Кубок Дракона - 2010 (Минск)\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2011-07-28 00:00:00\",\"endDate\":\"2010-10-31 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":268436,\"number\":10,\"text\":\"В результате масштабных исследований группа профессора Страуса пришла к выводу: чем выше по стране процент семей, в которых практикуют физические наказания, тем ниже средний национальный IQ. Информация об этом в журнале \\\"Вокруг света\\\" озаглавлена \\\"Иван Топчий понижает IQ\\\". Какие два одинаковых по количеству букв существительных мы заменили именем и фамилией?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Метод кнута.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Так что у тренера Топчия (команда \\\"Метод Кнудсена-Пряниксова\\\") подход неправильный. :-)\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"\\\"Вокруг света\\\", 2008, N 12. — С. 174.\",\"authors\":[{\"id\":25,\"name\":\"Леонид Климович\",\"gender\":\"HE\"}],\"editors\":[{\"id\":25,\"name\":\"Леонид Климович\",\"gender\":\"HE\"}],\"tour\":{\"id\":16229,\"number\":5,\"title\":\"\"},\"packId\":3811,\"packTitle\":\"Турнир \\\"Наше всё!\\\" (Гомель)\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2011-06-02 00:00:00\",\"endDate\":\"2010-06-05 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":292313,\"number\":5,\"text\":\"Профессор физики Оксфордского Университета Джошуа Силвер изобрел необычные ИКСЫ, добавив в привычную конструкцию маленький тюбик с силиконовом маслом, которое можно добавлять или выкачивать из полости. Таким образом, каждый сможет настроить их под себя и не придется его со временем менять. Какое слово мы заменили словом ИКСЫ?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Очки.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"В зависимости от количества масла изменяется фокусное расстояние очков, то есть каждый сам сможет под себя их настроить.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"\\\"NATIONAL GEOGRAPHIC Россия\\\", март 2010 г. — С. 28.\",\"authors\":[{\"id\":208,\"name\":\"Георгий Арабули\",\"gender\":\"HE\"}],\"editors\":[{\"id\":732,\"name\":\"Олег Фея\",\"gender\":\"HE\"}],\"tour\":{\"id\":17570,\"number\":1,\"title\":\"\"},\"packId\":4099,\"packTitle\":\"Кубок Физтеха - 2010 (Долгопрудный)\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2010-12-31 00:00:00\",\"endDate\":\"2010-05-29 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":296351,\"number\":3,\"text\":\"По американской статистике, ведущие традиционный образ жизни индейцы навахо часто простужались и страдали заболеваниями дыхательной системы. Выход из положения нашла профессор Джин Шульц: по ее предложению в резервации навахо решили использовать в быту бизонову тыкву, которая позволяет получить ИКС без ИГРЕКА. Назовите ИКС и ИГРЕК в правильном порядке.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Огонь, дым.\",\"answerPic\":\"\",\"zachet\":\"В правильном порядке.\",\"nezachet\":\"\",\"comment\":\"Традиционное жилище навахо — хоган — представляет собой землянку с отверстием в крыше для выхода дыма. Хоган часто наполняется дымом, который раздражает гортань и легкие, отсюда и ослабленная дыхательная система. Корни бизоновой тыквы стали использовать в качестве дров.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"\\\"Вокруг света\\\", 1995, N 8. — С. 65.\",\"authors\":[{\"id\":234,\"name\":\"Дмитрий Борок\",\"gender\":\"HE\"}],\"editors\":[{\"id\":234,\"name\":\"Дмитрий Борок\",\"gender\":\"HE\"}],\"tour\":{\"id\":17824,\"number\":1,\"title\":\"\"},\"packId\":4167,\"packTitle\":\"XIII Кубок Поволжской Лиги. 6 тур. Самара\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2010-11-03 00:00:00\",\"endDate\":\"2010-03-28 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":358209,\"number\":41,\"text\":\"Раздаточный материал:\\\\nМолодая женщина\\\\nЯркие цвета\\\\nГоризонтальные ИКСы\\\\nЧистокровные собаки\\\\nСкаковые лошади| Пожилая женщина\\\\nБлёклые цвета\\\\nВертикальные ИКСы\\\\nДворняжки\\\\nУпряжные лошади\\\\n---|---\\\\nСогласно закономерности, подмеченной гарвардским профессором Дональдом Томпсоном, ИКСЫ, имеющие отношение к левому столбцу, заметно превосходят ИКСы, относящиеся к столбцу правому. По какому параметру?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"по цене.\",\"answerPic\":\"\",\"zachet\":\"по стоимости.\",\"nezachet\":\"\",\"comment\":\"Речь идёт об аукционной стоимости картин. Картины, соответствующие левому столбцу, в среднем заметно дороже.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"http://www.say2day.ru/content/chuchelo-akuly\",\"authors\":[{\"id\":1613,\"name\":\"Анатолий Белкин\",\"gender\":\"HE\"}],\"editors\":[{\"id\":1613,\"name\":\"Анатолий Белкин\",\"gender\":\"HE\"}],\"tour\":{\"id\":21698,\"number\":2,\"title\":\"\"},\"packId\":5020,\"packTitle\":\"VIII турнир \\\"Неспростая весна\\\"\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2022-01-20 00:00:00\",\"endDate\":\"2010-03-27 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":174796,\"number\":2,\"text\":\"Американский историк и антрополог, защитник прав коренного населения континента профессор Жозеф Диксон однажды сделал горькое признание: \\\"Мы, белые люди, никогда не могли понять индейцев, потому что они прислушивались к голосам природы, а мы — к шороху...\\\". Чего?\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Долларов.\",\"answerPic\":\"\",\"zachet\":\"Денег; купюр.\",\"nezachet\":\"\",\"comment\":\"\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"М. Нажин. Мой народ Сиу. — М.: Молодая гвардия, 1964. — С. 6.\\\\nhttp://www.100tomov.ru/prikl_i_istoria/Nazhin_Mato/Moy_narod_siu.gz/2/\",\"authors\":[{\"id\":3376,\"name\":\"Владимир Крикунов\",\"gender\":\"HE\"}],\"editors\":[{\"id\":3273,\"name\":\"Ольга Кузьма\",\"gender\":\"HE\"},{\"id\":3274,\"name\":\"Андрей Кузьма\",\"gender\":\"HE\"}],\"tour\":{\"id\":11350,\"number\":3,\"title\":\"\"},\"packId\":2664,\"packTitle\":\"Школьный Открытый Кубок ГУАП - 2009\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2013-10-07 00:00:00\",\"endDate\":\"2010-01-20 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":295136,\"number\":13,\"text\":\"В 1923 году профессор Каменщиков предложил назвать ИКС в честь Великой Октябрьской Революции, мотивируя это его цветом, а также называя ИКС соперником бога империалистических войн. Назовите ИКС.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Антарес.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Красная звезда. Антарес — \\\"анти-Арес\\\" — против Марса.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"http://www.kommersant.ru/doc.aspx?DocsID=200422\",\"authors\":[{\"id\":141,\"name\":\"Мишель Матвеев\",\"gender\":\"HE\"}],\"editors\":[{\"id\":141,\"name\":\"Мишель Матвеев\",\"gender\":\"HE\"},{\"id\":1818,\"name\":\"Сергей Ефимов\",\"gender\":\"HE\"}],\"tour\":{\"id\":17748,\"number\":1,\"title\":\"\"},\"packId\":4150,\"packTitle\":\"Синхронный турнир \\\"Азовский бриз - 2010\\\"\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2010-11-18 00:00:00\",\"endDate\":\"2010-01-16 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":318867,\"number\":20,\"text\":\"Профессор социологии Мюнхенского университета Ульрих Бек считает ИКС главной приставкой нашего времени для выражения растерянной запутанности в модных веяниях. А газета \\\"Франкфуртер Рундшау\\\" в заметке об англицизмах в немецком языке предполагает, что ИКС — это именно то, чем занимается Incoming-Outgoing-Manager. Что в этом вопросе мы заменили на \\\"ИКС\\\"?\",\"razdatkaText\":\"Incoming-Outgoing-Manager\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Post.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"По мнению Бека, прошлое плюс \\\"post\\\" — вот основной рецепт, который мы в своей многословной и озадаченной непонятливости противопоставляем действительности, распадающейся на наших глазах. Менеджер по приходящему-исходящему — всего лишь тот, кто обрабатывает почту.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"1. Ульрих Бек. Общество риска. На пути к другому модерну. — М.:\\\\nПрогресс-Традиция, 2000. — С. 9.\\\\n2. http://www.fr-online.de/in_und_ausland/politik/meinung/kommentare/1583004_Denglisch-fuer-Anfaenger-I.html\",\"authors\":[{\"id\":306,\"name\":\"Борис Шойхет\",\"gender\":\"HE\"}],\"editors\":[{\"id\":221,\"name\":\"Михаил Перлин\",\"gender\":\"HE\"},{\"id\":306,\"name\":\"Борис Шойхет\",\"gender\":\"HE\"}],\"tour\":{\"id\":19064,\"number\":2,\"title\":\"Основной набор\"},\"packId\":4393,\"packTitle\":\"ЧГК по немецкой тематике, выпуск 5 (Хоббах - 2009)\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2010-01-15 00:00:00\",\"endDate\":\"2009-09-06 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":214295,\"number\":10,\"text\":\"Владимир Маяковский в одном из своих лозунгов для журнала \\\"Даешь\\\" писал (внимание, стихотворная форма с пропусками!):\\\\nПрофессорская братия вроде Ольденбургов\\\\nкнязьям служить и сегодня рада.\\\\nТо, что годилось для царских ИКСОВ,\\\\nмы вырвем с корнем из красных ИГРЕКОВ.\\\\nИКСЫ и ИГРЕКИ — имена собственные во множественном числе. Назовите их в правильном порядке.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Петербурги, Ленинграды.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Никаких комментариев, всё и так понятно.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"http://mayakovsky-reklama.narod.ru/slogany6.htm\",\"authors\":[],\"editors\":[{\"id\":1801,\"name\":\"Евгений Ярков\",\"gender\":\"HE\"}],\"tour\":{\"id\":13482,\"number\":7,\"title\":\"\"},\"packId\":3173,\"packTitle\":\"Тюменский марафон - 2009\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2012-08-02 00:00:00\",\"endDate\":\"2009-05-02 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":301849,\"number\":117,\"text\":\"Внимание, цитата из произведения Станислава Лема \\\"Профессор А. Донда\\\": \\\"Хаувари с большой помпой лично открыл Коррупционный банк, в котором каждый серьезный предприниматель мог получить долгосрочный кредит на ИКСЫ в том случае, если дирекция установит, что его интересы совпадают с государственными\\\". Назовите слово, которое в цитате мы заменили словом \\\"ИКС\\\".\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Взятка.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"С. Лем. Из воспоминаний Ийона Тихого. — М.: Книжная палата, 1990. — С.\\\\n103.\",\"authors\":[{\"id\":118,\"name\":\"Валерий Криволапов\",\"gender\":\"HE\"}],\"editors\":[{\"id\":24,\"name\":\"Дмитрий Башук\",\"gender\":\"HE\"},{\"id\":2701,\"name\":\"Оксана Балазанова\",\"gender\":\"HE\"}],\"tour\":{\"id\":18103,\"number\":2,\"title\":\"Игры основного этапа\"},\"packId\":4211,\"packTitle\":\"III Молодежный чемпионат Украины по брэйн-рингу (Житомир)\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2010-09-02 00:00:00\",\"endDate\":\"2009-03-14 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":203722,\"number\":17,\"text\":\"По словам профессора Мариковского, выборы бургомистра у шведов в Граденбурге проходили так: претенденты на эту должность садились вокруг стола и клали на него свои ИКСЫ. Посредине стола помещалась ОНА. Бургомистром избирался тот, кого она предпочитала всем остальным. Назовите ИКС.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Борода.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Она — блоха.\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"http://invertebrates.geoman.ru/books/item/f00/s00/z0000000/st006.shtml\",\"authors\":[{\"id\":946,\"name\":\"Марианна Выдревич\",\"gender\":\"HE\"}],\"editors\":[{\"id\":707,\"name\":\"Юрий Выменец\",\"gender\":\"HE\"}],\"tour\":{\"id\":12954,\"number\":2,\"title\":\"2 тур. \\\"Дикие бозоны Хиггса\\\"\"},\"packId\":3063,\"packTitle\":\"Весенний чемпионат \\\"Коломны\\\" - 2009\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2012-10-30 00:00:00\",\"endDate\":\"2009-01-01 00:00:00\",\"uploader\":1,\"tags\":[],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]},{\"id\":340994,\"number\":2,\"text\":\"Кое-как расправившись со своим собственным творением, один молодой человек высказал предположение, что именно так ИКСЫ появляются на свет. В литературном произведении, героем которого этот молодой человек также являлся, высказывается мнение, что общественную пользу приносят не ИКСЫ, а как раз их противоположность. Назовите эту противоположность.\",\"razdatkaText\":\"\",\"razdatkaPic\":\"\",\"audio\":\"\",\"commentAudio\":\"\",\"answer\":\"Здоровые сенсации.\",\"answerPic\":\"\",\"zachet\":\"\",\"nezachet\":\"\",\"comment\":\"Фразу \\\"Вот так рождаются нездоровые сенсации\\\" мнс Саша Привалов сказал, вытолкав за окошко созданного им бородатого комара, похожего на профессора Выбегалло. В \\\"Сказке о тройке\\\" фигурирует лозунг \\\"Народу не нужны нездоровые сенсации. Народу нужны здоровые сенсации\\\".\",\"note\":\"\",\"commentPic\":\"\",\"source\":\"А. и Б. Стругацкие \\\"Понедельник начинается в субботу\\\", \\\"Сказка о\\\\nтройке\\\".\",\"authors\":[{\"id\":228,\"name\":\"Юрий Вашкулат\",\"gender\":\"HE\"}],\"editors\":[{\"id\":228,\"name\":\"Юрий Вашкулат\",\"gender\":\"HE\"},{\"id\":372,\"name\":\"Сергей Амлинский\",\"gender\":\"HE\"},{\"id\":660,\"name\":\"Владимир Печерога\",\"gender\":\"HE\"}],\"tour\":{\"id\":20625,\"number\":3,\"title\":\"\"},\"packId\":4757,\"packTitle\":\"Синхронный турнир \\\"Звездный мост - Кубок Средиземья - 2008\\\"\",\"controversials\":[],\"appeals\":[],\"totalLikes\":0,\"totalDislikes\":0,\"pubDate\":\"2008-09-30 00:00:00\",\"endDate\":\"2008-09-13 00:00:00\",\"uploader\":1,\"tags\":[{\"id\":3,\"title\":\"напарные\"}],\"takenDown\":false,\"marked\":false,\"gNum\":0,\"teams\":[],\"complexity\":[],\"correct_answers\":[],\"tournaments\":[]}],\"count\":118,\"highlights\":{\"1140\":{\"text\":\"Существует сюжетная линия, где известному персонажу противостоит злодей по прозвищу «\\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e Сатл», чья фамилия означает «неявный». Назовите этого персонажа двумя словами.\",\"comment\":\"фанаты Капитана Очевидность написали ему комикс-биографию. Согласно этой биографии, супергерой «Капитан Очевидность» противостоит злому \\u003cspan class=\\\"hl\\\"\\u003eпрофессору\\u003c/span\\u003e, чью фамилию можно перевести как «неочевидный».\"},\"2313\":{\"text\":\"\\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e оксфордского университета Брайан Сайкс полагает, что ИМ может быть гибрид полярного и бурого медведей, оказавшийся значительно южнее обычного ареала обитания. Назовите ЕГО несклоняемым словом.\",\"comment\":\"\\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e исследовал ДНК шерсти, обнаруженной в Гималаях, и пришел к выводу, что эта шерсть принадлежит не снежному человеку, а упомянутому гибриду белого и бурого медведей, который мог жить в том регионе некоторое время назад, что и стало поводом для появления легенды о йети. Исследование вполне характерно для британского учёного.\"},\"3998\":{\"text\":\"Будущий нобелевский лауреат мечтал заниматься творчеством, но пошёл по стопам отца-\\u003cspan class=\\\"hl\\\"\\u003eпрофессора\\u003c/span\\u003e и во второй половине XIX века подготовил к изданию \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e. Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e двумя словами, начинающимися на одну и ту же букву.\"},\"4247\":{\"comment\":\"\\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e из комикса «Наука Супермена» изобрел прибор, способный разделять атомы. ФБР заподозрило утечку информации из Манхэттенского проекта, но оказалось, что это лишь потрепавшее нервы совпадение. С греческого асбест переводится как «несгораемый», а атом как «неделимый».\"},\"7086\":{\"text\":\"Около трех веков на территории Оксфордского университета можно было видеть \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e, появившийся здесь благодаря \\u003cspan class=\\\"hl\\\"\\u003eпрофессору\\u003c/span\\u003e, который раньше работал на Ближнем Востоке. Другому \\u003cspan class=\\\"hl\\\"\\u003eИКСу\\u003c/span\\u003e принадлежат слова: \\\"Плавает всё! Красота\\\". Какое слово мы заменили \\u003cspan class=\\\"hl\\\"\\u003eИКСом\\u003c/span\\u003e?\",\"comment\":\"В саду колледжа Крайст-Черч долгое время рос кедр, выращенный \\u003cspan class=\\\"hl\\\"\\u003eпрофессором\\u003c/span\\u003e Эдвардом Пококом из семян, привезенных с Ближнего Востока. “Кедр” — это позывной Юрия Гагарина. Упомянутая в вопросе реплика — реакция Гагарина на состояние невесомости.\"},\"7766\":{\"text\":\"Блиц. 3 вопроса по 20 секунд обсуждения.\\\\n1. После успеха дебютного фильма Джон и Джордж поругались, и Джон сохранил за собой права на словосочетание «ПЕРВЫЕ ВТОРЫЕ». Джон пока ещё ПЕРВЫЙ. Назовите ПЕРВЫХ.\\\\n2. \\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e Шарль Рише считал \\u003cspan class=\\\"hl\\\"\\u003eИКСОВ\\u003c/span\\u003e психопатами, которые страдают от расщепления сознания. Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКСА\\u003c/span\\u003e словом латинского происхождения.\\\\n3. После успеха дебютного фильма Джон и Джордж поругались, и из названий сиквелов Джорджа пропало слово «ПЕРВЫЕ». Джордж стал ВТОРЫМ в 2017 году. Назовите ВТОРЫХ.\"},\"15648\":{\"text\":\"На фотографии 1924 года \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e пока жив и здоров, а \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e – у него на привязи. Назовите имя \\u003cspan class=\\\"hl\\\"\\u003eИКСА\\u003c/span\\u003e.\",\"comment\":\"в кадре \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e Уэ\u0301но играет с привязанным псом. После смерти \\u003cspan class=\\\"hl\\\"\\u003eпрофессора\\u003c/span\\u003e Хатико стал символом привязанности в переносном смысле. В каком-то смысле Хатико повторил судьбу Йозефа Майстера.\"},\"16639\":{\"comment\":\"инопланетянин Громозека, встретив в ресторане старушку с планеты Земля, оставил ей автограф со строками «прекрасной юной землянке», на что \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e Селезнёв резонно возразил, что землянками называют не женщин, а «первобытное жильё, выкопанное в Земле». Уже тогда Булычёв предвосхитил языковые проблемы, которые вызывает неумеренное использование суффикса «–ка» вместо более подходящих «-ша» или «-ха». Отсюда, например, типичные ошибки вроде «спецкорки» или «гримёрки», которые допускают современные феминистки.\"},\"27533\":{\"text\":\"Дуплет.\\\\n1. В 1857 году американский дипломат Эндрю Диксон Уайт прочитал в Йельском университете публичную лекцию, в которой критиковал ЭТО с позиций экономики и морали. Назовите ЭТО двумя словами.\\\\n2. В 1857 году \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e Дмитрий Каченовский читал в Харьковском университете публичные лекции, в которых критиковал ЭТО с позиций экономики и морали. Назовите ЭТО одним словом.\"},\"34177\":{\"text\":\"Задача о сортировке шаров трех разных цветов, сформулированная \\u003cspan class=\\\"hl\\\"\\u003eпрофессором\\u003c/span\\u003e Эйндховенского университета Эдсгером Дейкстрой, носит название \\\"Проблема \\u003cspan class=\\\"hl\\\"\\u003eИКСА\\u003c/span\\u003e\\\". Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e двумя словами.\",\"comment\":\"Эдсгер \\u003cspan class=\\\"hl\\\"\\u003eДейкстра\\u003c/span\\u003e — нидерландский ученый. Для примера он использовал цвета национального флага: красный, белый и синий.\"},\"42016\":{\"text\":\"\\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e геологического факультета МГУ Николай Короновский, рассказывая о мощности отложений соли в Прикаспийской низменности, упоминает двадцать четвертый \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e. Какие слова мы заменили \\u003cspan class=\\\"hl\\\"\\u003eИКСОМ\\u003c/span\\u003e?\"},\"52280\":{\"text\":\"В 1899 году палеонтолог Владимир АмалИцкий раскопал в песчаниках останки доисторических животных. Для того чтобы привести их в \\\"музейный\\\" вид, ему пришлось обратиться к \\u003cspan class=\\\"hl\\\"\\u003eИКСАМ\\u003c/span\\u003e. Назовите немецкоязычный роман, заголовок которого — продукт деятельности \\u003cspan class=\\\"hl\\\"\\u003eИКСОВ\\u003c/span\\u003e.\",\"comment\":\"Чтобы высвободить окаменелости из песчаника, \\u003cspan class=\\\"hl\\\"\\u003eпрофессору\\u003c/span\\u003e пришлось обратиться к кладбищенским каменотесам, вырезающим надгробные плиты. Мастера буквально выдолбили кость за костью уникальные скелеты. Не всегда точно, с некоторыми потерями, но результат был достигнут. В романе \\\"Черный обелиск\\\" Эриха Марии Ремарка главный герой работает в фирме по продаже надгробий.\"},\"52451\":{\"text\":\"Британский ученый описывает ситуацию в маленьком городке: среди жителей всего один \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e, и остальные считают, что \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e должен оставаться таковым ради всеобщего блага. Ведь иначе властям придется сделать \\u003cspan class=\\\"hl\\\"\\u003eИКСАМИ\\u003c/span\\u003e нескольких других жителей. А что, как правило, ищут \\u003cspan class=\\\"hl\\\"\\u003eИКСЫ\\u003c/span\\u003e?\",\"comment\":\"Если единственный безработный найдет работу, то станет не нужна городская служба занятости. Описывает этот курьезный случай экономист Ха Джун Чан — действительно кембриджский \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e корейского происхождения.\"},\"54606\":{\"text\":\"\\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e ГЕзер отмечает, что в свое время кавалеры отращивали пышную растительность на лице, чтоб показать, что у них нет \\u003cspan class=\\\"hl\\\"\\u003eИКСА\\u003c/span\\u003e. Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e.\"},\"58649\":{\"text\":\"Герой Акунина считает, что на Сталина плохо влияет некий \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e, после чего заявляет, что готов стать красным Феликсом Дзержинским. Какое слово мы заменили в предыдущем предложении?\",\"comment\":\"Этого \\u003cspan class=\\\"hl\\\"\\u003eпрофессора\\u003c/span\\u003e герой сравнивает с Распутиным, после чего говорит, что готов попытаться спасти Отечество и убить \\u003cspan class=\\\"hl\\\"\\u003eпрофессора\\u003c/span\\u003e, подобно тому как князь Феликс Юсупов убил \\\"святого старца\\\".\"},\"64934\":{\"text\":\"ТАКОЙ \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e — это цветок с длинными заостренными листьями серого цвета. В некоторых фанфиках ТАКОЙ \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e есть у известного голландского \\u003cspan class=\\\"hl\\\"\\u003eпрофессора\\u003c/span\\u003e. Что мы заменили словами \\\"ТАКОЙ \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e\\\"?\",\"comment\":\"Голландский \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e — это Абрахам ван Хельсинг — охотник на вампиров. Серебряный меч — это очень редкое растение, эндемик Гавайских островов. Название связано с тем, что у листьев мечевидная форма и серебристый оттенок.\"},\"67362\":{\"text\":\"Внимание, слова \\\"ИГРЕК\\\" и \\\"ЗЕТ\\\" в вопросе являются заменами.\\\\nГероиня романа Элис Рэндалл — \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e филологии афроамериканского происхождения. Своему сыну она дала имя ИГРЕК ЗЕТ. Описывая барышню с туго перетянутой талией, ИГРЕК использует сравнение с ЗЕТОМ. Напишите слова, которые мы заменили ИГРЕКОМ и ЗЕТОМ.\",\"answer\":\"Пушкин, \\u003cspan class=\\\"hl\\\"\\u003eИкс\\u003c/span\\u003e.\",\"comment\":\"Сына зовут Пушкин \\u003cspan class=\\\"hl\\\"\\u003eИкс\\u003c/span\\u003e. Имя \\u003cspan class=\\\"hl\\\"\\u003eИкс\\u003c/span\\u003e популярно среди американских негров еще со времен Малькольма \\u003cspan class=\\\"hl\\\"\\u003eИкса\\u003c/span\\u003e. А так как она филолог, то дала сыну еще одно имя — в честь писателя частично африканского происхождения.\"},\"67715\":{\"text\":\"\\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e Сергей Мамонтов пишет, что \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e и его семья должны были болеть примерно 500 заболеваниями, вызываемыми паразитами. Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКСА\\u003c/span\\u003e.\"},\"69241\":{\"text\":\"\\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e — это замена.\\\\nМосковский \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e Александр Петров является выпускником авиационного института. Но \\u003cspan class=\\\"hl\\\"\\u003eИКСОМ\\u003c/span\\u003e его называют вовсе не по этой причине, а потому что он родом из... Какого украинского города?\"},\"71707\":{\"text\":\"Федор СтепУн, впоследствии занимавший место \\u003cspan class=\\\"hl\\\"\\u003eпрофессора\\u003c/span\\u003e социологии в университете Дрездена, воспользовался поездом. Несмотря на это, Татьяна ВОльтская в своей статье \\\"\\\"\\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e\\\" как зло и спасение\\\" ошибочно упоминает Степуна. Назовите \\\"\\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e\\\".\"},\"73249\":{\"text\":\"Внимание, в вопросе есть замены.\\\\n\\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e Оксфордского университета утверждал, что \\u003cspan class=\\\"hl\\\"\\u003eИКСЫ\\u003c/span\\u003e не умеют делать красивых вещей. Возможно, это и так, но один \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e с помощью \\\"Божьей искры\\\" так переиначил результат трудов \\u003cspan class=\\\"hl\\\"\\u003eпрофессора\\u003c/span\\u003e, что заставил смеяться миллионы. Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКСА\\u003c/span\\u003e.\"},\"79272\":{\"text\":\"Татьяна Толстая признаётся, что любит \\u003cspan class=\\\"hl\\\"\\u003eИКСЫ\\u003c/span\\u003e, и рассказывает, как угощала свою подругу, \\u003cspan class=\\\"hl\\\"\\u003eпрофессора\\u003c/span\\u003e университета, огурчиками. Подруга заметила, что в ее семье никогда не употребляли \\u003cspan class=\\\"hl\\\"\\u003eИКСЫ\\u003c/span\\u003e, т.к. это считалось мещанством. \\\"И ведь действительно, — рассуждает Толстая, — дворянин не будет себе огурчики солить и банки закатывать с помидорчиками. И картошечку он не будет себе жарить. \\u003c...\\u003e А мещанин и закатает, и поджарит, и угостит, и почирикает, и попоет над этой едой\\\". Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКСЫ\\u003c/span\\u003e двумя словами.\",\"answer\":\"Уменьшительные \\u003cspan class=\\\"hl\\\"\\u003eсуффиксы\\u003c/span\\u003e.\",\"zachet\":\"Уменьшительно-ласкательные \\u003cspan class=\\\"hl\\\"\\u003eсуффиксы\\u003c/span\\u003e; Уменьшительные формы;\\\\nУменьшительно-ласкательные формы; Уменьшительно-ласкательные слова.\"},\"79677\":{\"text\":\"На одном шарже \\u003cspan class=\\\"hl\\\"\\u003eКукрыниксов\\u003c/span\\u003e изображен Николай, который смотрит в зеркало и видит там Александра, Ивана и Дмитрия Илларионовича. Мы не просим вас назвать ни прозвища, ни фамилии троих последних. Напишите фамилию Николая.\",\"comment\":\"Великий русский актер Николай Константинович Черкасов видит в зеркале своих героев — Александра Невского, Ивана Грозного (из одноименных фильмов) и \\u003cspan class=\\\"hl\\\"\\u003eпрофессора\\u003c/span\\u003e Полежаева (героя фильма \\\"Депутат Балтики\\\").\"},\"89352\":{\"text\":\"Около трех веков на территории Оксфордского университета можно было видеть \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e, появившийся здесь благодаря \\u003cspan class=\\\"hl\\\"\\u003eпрофессору\\u003c/span\\u003e, который раньше работал на Ближнем Востоке. Другому \\u003cspan class=\\\"hl\\\"\\u003eИКСУ\\u003c/span\\u003e принадлежат слова: \\\"Плавает всё! Красота\\\". Какое слово мы заменили \\u003cspan class=\\\"hl\\\"\\u003eИКСОМ\\u003c/span\\u003e?\",\"comment\":\"В саду колледжа Крайст-Чёрч долгое время рос кедр, выращенный \\u003cspan class=\\\"hl\\\"\\u003eпрофессором\\u003c/span\\u003e Эдвардом Пококом из семян, привезенных с Ближнего Востока. \\\"Кедр\\\" — это позывной Юрия Гагарина. Упомянутая в вопросе реплика — реакция Гагарина на состояние невесомости.\"},\"96651\":{\"text\":\"Оксфордский \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e Ричард Докинз считает \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e одним из наиболее неудачных изобретений человечества и предлагает хотя бы располовинить и запараллелить. Сквернослов РОулэнд Дженкс был вероятным источником эпидемии сыпного тифа, убившей в 1577 году более трехсот человек. Ее название обычно переводится на русский язык как \\\"Черный оксфордский \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e\\\". Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e двумя словами.\"},\"96740\":{\"text\":\"\\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e ПиншОт предложил использовать для разведения китов \\u003cspan class=\\\"hl\\\"\\u003eИКСы\\u003c/span\\u003e. Лев КассИль сравнил с \\u003cspan class=\\\"hl\\\"\\u003eИКСом\\u003c/span\\u003e волосы пожилого персонажа. Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e.\",\"comment\":\"\\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e представляет собой неплохую заготовку загона для кита. Цитата из Кассиля: \\\"Вокруг лысины росли торчком бурые волосы, лысина его была подобна лагуне в коралловом атолле\\\".\"},\"112788\":{\"text\":\"В 1991 году состоялось заседание британской палаты лордов, посвященное новым возможностям химии и промышленности. Предмет обсуждения, по словам \\u003cspan class=\\\"hl\\\"\\u003eпрофессора\\u003c/span\\u003e КрОто из Сассекского университета, был во столько же раз меньше \\u003cspan class=\\\"hl\\\"\\u003eИКСА\\u003c/span\\u003e, во сколько раз \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e меньше земного шара. Догадавшись, что именно обсуждалось, назовите \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e двумя словами.\"},\"114005\":{\"text\":\"Рассуждая о своей будущей смерти, \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e из романа СалмАна РУшди заявляет, что ТАКИЕ \\u003cspan class=\\\"hl\\\"\\u003eИКСЫ\\u003c/span\\u003e не рады скучным СЯКИМ \\u003cspan class=\\\"hl\\\"\\u003eИКСАМ\\u003c/span\\u003e. Что мы заменили словами \\\"ТАКОЙ \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e\\\" и \\\"СЯКОЙ \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e\\\"?\",\"comment\":\"Книжными червями иронично называют начитанных людей, библиофилов. \\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e считал, что книжными червями могильные не питаются.\"},\"122546\":{\"text\":\"Анекдот из серии \\\"Физики шутят\\\":\\\\nБежит студент со всех ног по коридору. Из-за угла неожиданно выходит \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e, и студент в него врезается, да так, что \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e валится на пол. \\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e поднимается и говорит: \\\"хорошо, что пополам\\\".\\\\n— Что пополам? — спрашивает ошарашенный студент.\\\\n— \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e.\\\\nУкажите в правильном порядке три символа, которые мы заменили на \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e.\"},\"122623\":{\"text\":\"Если вы страдаете цветовой слепотой, перед вами будет лишь набор бессмысленных \\u003cspan class=\\\"hl\\\"\\u003eпикселей\\u003c/span\\u003e. Если у вас всё в порядке, Вы сможете различить персонажей известного мультсериала. Какого?\",\"comment\":\"На картинке можно узнать следующих персонажей (по порядку, слева направо, сверху вниз): Фрай, Бендер, Лила, Эми, доктор Зойдберг, Скаффи, Гермес, \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e Фарнсворт, Зепп Бранниган и Киф Крокер.\"},\"125752\":{\"text\":\"В математическом анекдоте Фурье умирает, и вскоре из его могилы начинают доноситься странные звуки, что-то вроде: \\\"Синус \\u003cspan class=\\\"hl\\\"\\u003eикс\\u003c/span\\u003e... плюс два косинус \\u003cspan class=\\\"hl\\\"\\u003eикс\\u003c/span\\u003e... плюс три пятых синус двух \\u003cspan class=\\\"hl\\\"\\u003eикс\\u003c/span\\u003e...\\\" и так далее. Вызванный на место происшествия \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e успокаивает публику. Закончите его фразу одним словом: \\\"Ничего страшного, это просто...\\\".\"},\"126052\":{\"text\":\"[Ведущему: кавычки не озвучивать.]\\\\n\\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e Белецкий пишет, что изначально ОНА \\\"поселилась в Дрездене\\\", но могла бы погибнуть, если бы своевременно не побывала в Москве. Перед НЕЙ преклонялись Жуковский, Пушкин, Гоголь, Белинский, Гончаров, Герцен — если всех перечислять, то пальцев на руке не хватит. Назовите ЕЕ.\",\"answer\":\"\\\"\\u003cspan class=\\\"hl\\\"\\u003eСикстинская\\u003c/span\\u003e Мадонна\\\".\",\"comment\":\"По окончании Второй мировой войны московские реставраторы вернули знаменитому шедевру Рафаэля первозданную красу. Мы неслучайно упомянули именно шестерых ценителей \\\"Мадонны\\\", ведь распространено заблуждение, будто имя \\\"\\u003cspan class=\\\"hl\\\"\\u003eСикст\\u003c/span\\u003e\\\" означает \\\"шесть\\\" и на картине якобы есть шестипалая рука.\"},\"135622\":{\"text\":\"СавАнты — это люди с отклонениями в развитии, имеющие, однако, выдающиеся способности в какой-то области. Большинство савАнтов не может объяснить, как им удается использовать свою феноменальные способности. Говоря об уникальности савАнта Дэниела ТАммета, \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e Аллан Снайдер сравнивает ТАммета с НИМ. ЕГО инвентарный номер — EA [и-эй] 24. Назовите ЕГО.\",\"comment\":\"Изучение того, как работает мозг ТАммета, может помочь лучше понять природу савАнтов, подобно тому как Розеттский камень помог разгадать египетские иероглифы. EA — Egyptian Antiques [иджИпшан \\u003cspan class=\\\"hl\\\"\\u003eантИкс\\u003c/span\\u003e] — египетские древности.\"},\"136770\":{\"text\":\"В рассказе о знаменитом потомке захолустных помещиков фигурирует альпийский ОН, где нашел смерть \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e. Однако в 1980 году роль альпийского ЕГО сыграл абхазский. Мы не спрашиваем вас о НЕМ. Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКСА\\u003c/span\\u003e.\",\"zachet\":\"\\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e Мориарти, Джеймс Мориарти.\"},\"136772\":{\"text\":\"В ответ на предложение \\u003cspan class=\\\"hl\\\"\\u003eпрофессора\\u003c/span\\u003e Фарнсворта воссоздать условия, предшествовавшие Большому Взрыву, и высказанное им сожаление о том, что он уже слишком стар, чтоб дожить до конца этого эксперимента, Туранга Лила ответила: \\\"Я удивлена, что вы дожили до \\u003cspan class=\\\"hl\\\"\\u003eИКСА\\u003c/span\\u003e\\\". В \\u003cspan class=\\\"hl\\\"\\u003eИКСЕ\\u003c/span\\u003e есть \\\"синхрофазотрон\\\". Какие три слова мы заменили \\u003cspan class=\\\"hl\\\"\\u003eИКСОМ\\u003c/span\\u003e?\"},\"146823\":{\"text\":\"Описывая знаменитый портрет Фрэнсиса Дрейка, \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e Джереми Айдельман говорит, что положение правой руки мореплавателя символизирует могущество британского флота, и в шутку замечает, что сам Дрейк никогда не занимался \\u003cspan class=\\\"hl\\\"\\u003eИКСОМ\\u003c/span\\u003e. \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e является детищем другого преподавателя. Какое слово мы заменили \\u003cspan class=\\\"hl\\\"\\u003eИКСОМ\\u003c/span\\u003e?\",\"comment\":\"Дрейк держит правую руку на глобусе, в наше время такое положение руки на круглом предмете характерно для фотографий спортсменов, держащих мяч. Баскетбол зародился в конце XIX века благодаря \\u003cspan class=\\\"hl\\\"\\u003eпрофессору\\u003c/span\\u003e Нейсмиту.\"},\"154285\":{\"text\":\"\\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e Фигуровский разработал систему ТАКИХ \\u003cspan class=\\\"hl\\\"\\u003eИКСОВ\\u003c/span\\u003e, что потребовало немалых исторических изысканий. В нее вошли, например, богемий и короний. Примечательно, что несколько ТАКИХ \\u003cspan class=\\\"hl\\\"\\u003eИКСОВ\\u003c/span\\u003e появились благодаря Дмитрию Ивановичу. Что мы заменили словами \\\"ТАКИЕ \\u003cspan class=\\\"hl\\\"\\u003eИКСЫ\\u003c/span\\u003e\\\"?\"},\"158868\":{\"text\":\"Автор допускает, что для взятия этого вопроса трезвый способ мышления необязателен.\\\\nАмериканский \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e рассказывает, что для получения материала фосфорена ученые использовали ЕЕ. ОНА была нужна, чтобы отделить тончайшие слои черного фосфора. Этот метод получил название \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e-техника. Какое слово мы заменили на \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e?\"},\"161857\":{\"text\":\"\\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e-искусствовед А. Липков углубился в изучение некоторых подробностей культуры быта средневековой Европы и был, надо сказать, шокирован некоторыми из них. По итогам изучения вопроса он издал первый в России тематический труд \\\"\\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e к ИГРЕКУ\\\". Воспроизведите название, если авторы вопроса считают, что \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e является наиболее характерным местом ИГРЕКА.\"},\"165825\":{\"text\":\"Внимание, слово \\\"\\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e\\\" — замена.\\\\nВо время путешествия Байрон сравнил один из \\u003cspan class=\\\"hl\\\"\\u003eИКСОВ\\u003c/span\\u003e с \\\"хвостом коня-гиганта, на котором в виденье Иоанна мчится Смерть\\\". Другой \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e известен, в том числе, в связи со смертью ученого. Назовите этого ученого.\",\"answer\":\"[\\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e Джеймс] Мориарти.\",\"comment\":\"Речь идет о водопадах. \\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e Мориарти из произведений о Шерлоке Холмсе погиб в Рейхенбахском водопаде, который, кстати, находится неподалеку от водопада, описанного Байроном.\"},\"167865\":{\"text\":\"Во второй книге Паралипоменон говорится, что среди прочих украшений в иерусалимском храме было ТАКОЕ море — \\\"от края до края десять локтей, и шнурок в тридцать локтей обнимал его\\\". Эту цитату \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e Сэмюэл Дикс приводит, пародируя требования креационистов изучать не только эволюционную теорию. Напишите слово, которое мы заменили на \\\"ТАКОЕ\\\".\",\"comment\":\"Несложно посчитать, что библейское Пи равняется ровно трем. \\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e Дикс говорит, что раз креационисты требуют изучать библейскую теорию наряду с эволюционной, то нужно посвятить должное время и изучению библейской математики, в которой Пи не будет иррациональным числом.\"},\"174796\":{\"text\":\"Американский историк и антрополог, защитник прав коренного населения континента \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e Жозеф Диксон однажды сделал горькое признание: \\\"Мы, белые люди, никогда не могли понять индейцев, потому что они прислушивались к голосам природы, а мы — к шороху...\\\". Чего?\"},\"175992\":{\"text\":\"Википедия отмечает, что героя комиксов \\u003cspan class=\\\"hl\\\"\\u003eПрофессора\\u003c/span\\u003e \\u003cspan class=\\\"hl\\\"\\u003eИкс\\u003c/span\\u003e, мечтавшего о мирном сосуществовании между людьми и мутантами, часто сравнивают с ПЕРВЫМ, в то время как радикально настроенного Магнето — со ВТОРЫМ. Назовите ПЕРВОГО и ВТОРОГО.\",\"answer\":\"[Мартин Лютер] Кинг, [Малькольм] \\u003cspan class=\\\"hl\\\"\\u003eИкс\\u003c/span\\u003e.\",\"comment\":\"Мартин Лютер Кинг тоже много мечтал, ну а Малькольма \\u003cspan class=\\\"hl\\\"\\u003eИкса\\u003c/span\\u003e фамилия обязывает.\"},\"186579\":{\"text\":\"Во второй книге Паралипоменон говорится, что среди прочих украшений в иерусалимском храме было ТАКОЕ море — \\\"от края до края десять локтей, и снурок в тридцать локтей обнимал его\\\". Эту цитату \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e Сэмюэл Дикс упоминает, пародируя требование креационистов изучать не только эволюционную теорию. Какое слово мы заменили на \\\"ТАКОЕ\\\"?\",\"comment\":\"Несложно посчитать, что библейское Пи равняется ровно трем. \\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e Дикс говорит, что раз креационисты требуют изучать библейскую теорию наряду с эволюционной, то нужно посвятить должное время и изучению библейской математики, в которой Пи не будет иррациональным числом.\"},\"187165\":{\"text\":\"Герой Владислава Крапивина \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e Чайнозаварский предлагал сделать \\u003cspan class=\\\"hl\\\"\\u003eИКСЫ\\u003c/span\\u003e частью школьной формы. По его мнению, после этого сразу же будут решены проблемы с дисциплиной и успеваемостью. Назовите известное произведение, героиня которого на практике испытала с полдюжины \\u003cspan class=\\\"hl\\\"\\u003eИКСОВ\\u003c/span\\u003e и ее выводы были прямо противоположны мнению Чайнозаварского.\",\"comment\":\"\\u003cspan class=\\\"hl\\\"\\u003eИКСЫ\\u003c/span\\u003e — очки; \\\"А проку на-волос нет в них\\\", — пришла к выводу Мартышка в басне И.А. Крылова.\"},\"188058\":{\"text\":\"\\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e Ларднер из Лондонского университета доказал, что для любой точки внутри прямоугольника сумма площадей квадратов, обозначенных красным, равна сумме площадей квадратов, обозначенных синим. Для доказательства нужно провести перпендикуляры к четырем сторонам. Это утверждение называется теоремой \\u003cspan class=\\\"hl\\\"\\u003eИКСА\\u003c/span\\u003e. Какое имя есть в английском названии \\u003cspan class=\\\"hl\\\"\\u003eИКСА\\u003c/span\\u003e?\"},\"190062\":{\"text\":\"Внимание, в вопросе \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e заменяет два слова.\\\\n\\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e Иэн Стюарт сравнил \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e с одеялом. Статья о каком режиссере называется \\\"\\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e\\\"?\",\"comment\":\"\\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e — озоновый слой — своего рода защитное одеяло Земли.\"},\"195285\":{\"text\":\"Серия рекламных плакатов утверждает, что \\u003cspan class=\\\"hl\\\"\\u003eИКСЫ\\u003c/span\\u003e делают из доступной женщины — недоступную, из водителя грузовика — \\u003cspan class=\\\"hl\\\"\\u003eпрофессора\\u003c/span\\u003e, из байкера — модного дизайнера. Известная героиня однажды раздобыла с полдюжины \\u003cspan class=\\\"hl\\\"\\u003eИКСОВ\\u003c/span\\u003e. Что такое \\u003cspan class=\\\"hl\\\"\\u003eИКСЫ\\u003c/span\\u003e?\"},\"197877\":{\"text\":\"Внимание, в вопросе словом \\\"\\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e\\\" заменено другое слово.\\\\n\\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e героя произведений Конан Дойла \\u003cspan class=\\\"hl\\\"\\u003eпрофессора\\u003c/span\\u003e Челленджера напоминал колючую проволоку. Репортер Мелоун имел возможность убедиться в этом непосредственно перед тем, как узнал о согласии \\u003cspan class=\\\"hl\\\"\\u003eпрофессора\\u003c/span\\u003e принять его у себя дома. Какое слово мы обозначили как \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e?\",\"comment\":\"О приглашении Мелоун узнал из письма \\u003cspan class=\\\"hl\\\"\\u003eпрофессора\\u003c/span\\u003e.\"},\"203722\":{\"text\":\"По словам \\u003cspan class=\\\"hl\\\"\\u003eпрофессора\\u003c/span\\u003e Мариковского, выборы бургомистра у шведов в Граденбурге проходили так: претенденты на эту должность садились вокруг стола и клали на него свои \\u003cspan class=\\\"hl\\\"\\u003eИКСЫ\\u003c/span\\u003e. Посредине стола помещалась ОНА. Бургомистром избирался тот, кого она предпочитала всем остальным. Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e.\"},\"214295\":{\"text\":\"Владимир Маяковский в одном из своих лозунгов для журнала \\\"Даешь\\\" писал (внимание, стихотворная форма с пропусками!):\\\\nПрофессорская братия вроде Ольденбургов\\\\nкнязьям служить и сегодня рада.\\\\nТо, что годилось для царских \\u003cspan class=\\\"hl\\\"\\u003eИКСОВ\\u003c/span\\u003e,\\\\nмы вырвем с корнем из красных ИГРЕКОВ.\\\\n\\u003cspan class=\\\"hl\\\"\\u003eИКСЫ\\u003c/span\\u003e и ИГРЕКИ — имена собственные во множественном числе. Назовите их в правильном порядке.\"},\"224078\":{\"text\":\"О \\u003cspan class=\\\"hl\\\"\\u003eпрофессоре\\u003c/span\\u003e Челленджере говорили, что он способен перессорить даже \\u003cspan class=\\\"hl\\\"\\u003eИКСОВ\\u003c/span\\u003e на собрании. \\\"\\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e\\\" — прозвище предводителя хулиганов в произведении Владислава Крапивина. Какое слово мы заменили \\\"\\u003cspan class=\\\"hl\\\"\\u003eИКСОМ\\u003c/span\\u003e\\\"?\"},\"254477\":{\"text\":\"Чтобы наблюдать развитие болезни в прозрачной среде, \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e Конгейм вводил бактерии в \\u003cspan class=\\\"hl\\\"\\u003eИКСы\\u003c/span\\u003e. Надеемся, вам знакома строчка 1906 года, в которой упоминаются \\u003cspan class=\\\"hl\\\"\\u003eИКСы\\u003c/span\\u003e. Процитируйте ее.\",\"comment\":\"\\u003cspan class=\\\"hl\\\"\\u003eИКСы\\u003c/span\\u003e — глаза кроликов. Строчка — из стихотворения Блока \\\"Незнакомка\\\".\"},\"260935\":{\"text\":\"Продолжим. Засчитывается только правильный ответ. Шутка.\\\\nВ систематике в названии растений нередки случаи использования фамилий. Например: пихта Нордмана (финский \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e), или раффлезия Арнольда (Арнольд — доктор в экспедиции Раффлза из прошлого вопроса) и др. Вот и экскурсоводы в районе Демерджи (это не Кавказ, а в Крыму под Алуштой) любят показывать туристам сохранившийся до сих пор \\\"орех \\u003cspan class=\\\"hl\\\"\\u003eИКСА\\u003c/span\\u003e\\\". \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e — это фамилия. Назовите ее.\",\"comment\":\"Орех Никулина — с которого в к/ф \\\"Кавказская пленница\\\" Балбес кидался орехами. По задумке относительно веселый тон вопроса настраивал на что-то веселое (на комедию, например). Опять же, Арнольд — \\\"левый\\\" для ботаники человек, значит и \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e, возможно, стоит искать совсем не среди ботаников. Кроме того, то, что \\\"Кавказская пленница\\\" снималась в Крыму — известная фишка.\"},\"268436\":{\"text\":\"В результате масштабных исследований группа \\u003cspan class=\\\"hl\\\"\\u003eпрофессора\\u003c/span\\u003e Страуса пришла к выводу: чем выше по стране процент семей, в которых практикуют физические наказания, тем ниже средний национальный IQ. Информация об этом в журнале \\\"Вокруг света\\\" озаглавлена \\\"Иван Топчий понижает IQ\\\". Какие два одинаковых по количеству букв существительных мы заменили именем и фамилией?\",\"comment\":\"Так что у тренера Топчия (команда \\\"Метод Кнудсена-\\u003cspan class=\\\"hl\\\"\\u003eПряниксова\\u003c/span\\u003e\\\") подход неправильный. :-)\"},\"292313\":{\"text\":\"\\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e физики Оксфордского Университета Джошуа Силвер изобрел необычные \\u003cspan class=\\\"hl\\\"\\u003eИКСЫ\\u003c/span\\u003e, добавив в привычную конструкцию маленький тюбик с силиконовом маслом, которое можно добавлять или выкачивать из полости. Таким образом, каждый сможет настроить их под себя и не придется его со временем менять. Какое слово мы заменили словом \\u003cspan class=\\\"hl\\\"\\u003eИКСЫ\\u003c/span\\u003e?\"},\"295136\":{\"text\":\"В 1923 году \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e Каменщиков предложил назвать \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e в честь Великой Октябрьской Революции, мотивируя это его цветом, а также называя \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e соперником бога империалистических войн. Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e.\"},\"296351\":{\"text\":\"По американской статистике, ведущие традиционный образ жизни индейцы навахо часто простужались и страдали заболеваниями дыхательной системы. Выход из положения нашла \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e Джин Шульц: по ее предложению в резервации навахо решили использовать в быту бизонову тыкву, которая позволяет получить \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e без ИГРЕКА. Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e и ИГРЕК в правильном порядке.\"},\"301849\":{\"text\":\"Внимание, цитата из произведения Станислава Лема \\\"\\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e А. Донда\\\": \\\"Хаувари с большой помпой лично открыл Коррупционный банк, в котором каждый серьезный предприниматель мог получить долгосрочный кредит на \\u003cspan class=\\\"hl\\\"\\u003eИКСЫ\\u003c/span\\u003e в том случае, если дирекция установит, что его интересы совпадают с государственными\\\". Назовите слово, которое в цитате мы заменили словом \\\"\\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e\\\".\"},\"318867\":{\"text\":\"\\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e социологии Мюнхенского университета Ульрих Бек считает \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e главной приставкой нашего времени для выражения растерянной запутанности в модных веяниях. А газета \\\"Франкфуртер Рундшау\\\" в заметке об англицизмах в немецком языке предполагает, что \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e — это именно то, чем занимается Incoming-Outgoing-Manager. Что в этом вопросе мы заменили на \\\"\\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e\\\"?\"},\"340994\":{\"text\":\"Кое-как расправившись со своим собственным творением, один молодой человек высказал предположение, что именно так \\u003cspan class=\\\"hl\\\"\\u003eИКСЫ\\u003c/span\\u003e появляются на свет. В литературном произведении, героем которого этот молодой человек также являлся, высказывается мнение, что общественную пользу приносят не \\u003cspan class=\\\"hl\\\"\\u003eИКСЫ\\u003c/span\\u003e, а как раз их противоположность. Назовите эту противоположность.\",\"comment\":\"Фразу \\\"Вот так рождаются нездоровые сенсации\\\" мнс Саша Привалов сказал, вытолкав за окошко созданного им бородатого комара, похожего на \\u003cspan class=\\\"hl\\\"\\u003eпрофессора\\u003c/span\\u003e Выбегалло. В \\\"Сказке о тройке\\\" фигурирует лозунг \\\"Народу не нужны нездоровые сенсации. Народу нужны здоровые сенсации\\\".\"},\"354436\":{\"text\":\"Уже в 1893 году Карл Стёрмер подходил к людям поздороваться, после чего дёргал за цепочку в кармане жилетки. Карла Стёрмера считают одним из первых \\u003cspan class=\\\"hl\\\"\\u003eИКСов\\u003c/span\\u003e. Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКСа\\u003c/span\\u003e словом с удвоенной согласной.\",\"comment\":\"в кармане Стёрмера была скрытая камера, которая и приводилась в действие цепочкой. Он подходил к знаменитым жителям Осло и фотографировал их. Многие не догадывались о его цели, но один \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e всё же понял его замысел и дал резкий отпор, хотя Стёрмер успел его сфотографировать, и фото даже сохранилось. Сам термин «папарацци» появился уже спустя 67 лет, когда в фильме Фелли\u0301ни «Сладкая жизнь» был показан фотограф с такой фамилией.\"},\"356915\":{\"text\":\"В 1884 году \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e Уильям Пе\u0301нкост выбрал самого красивого студента, и тот стал одним из первых \\u003cspan class=\\\"hl\\\"\\u003eИКСов\\u003c/span\\u003e в истории. \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e Джоэл Маки\u0301рнан смог освободиться от регулярных платежей только через Верховный суд США. Какие два слова мы заменили словом «\\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e»?\"},\"358209\":{\"text\":\"Раздаточный материал:\\\\nМолодая женщина\\\\nЯркие цвета\\\\nГоризонтальные \\u003cspan class=\\\"hl\\\"\\u003eИКСы\\u003c/span\\u003e\\\\nЧистокровные собаки\\\\nСкаковые лошади| Пожилая женщина\\\\nБлёклые цвета\\\\nВертикальные \\u003cspan class=\\\"hl\\\"\\u003eИКСы\\u003c/span\\u003e\\\\nДворняжки\\\\nУпряжные лошади\\\\n---|---\\\\nСогласно закономерности, подмеченной гарвардским \\u003cspan class=\\\"hl\\\"\\u003eпрофессором\\u003c/span\\u003e Дональдом Томпсоном, \\u003cspan class=\\\"hl\\\"\\u003eИКСЫ\\u003c/span\\u003e, имеющие отношение к левому столбцу, заметно превосходят \\u003cspan class=\\\"hl\\\"\\u003eИКСы\\u003c/span\\u003e, относящиеся к столбцу правому. По какому параметру?\"},\"362870\":{\"text\":\"В одном издании романа «Гарри Поттер и философский камень» чтобы подчеркнуть, например, аккуратность \\u003cspan class=\\\"hl\\\"\\u003eпрофессора\\u003c/span\\u003e Макгонагалл и прямолинейность Хагрида, использовались разные \\u003cspan class=\\\"hl\\\"\\u003eИКСЫ\\u003c/span\\u003e. Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e словом немецкого происхождения.\"},\"364174\":{\"text\":\"\\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e — это замена.\\\\nВ песне Максима Леонидова есть слова: «Нашу родную ширь туман превратил в \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e». Одним из увлечений уроженца \\u003cspan class=\\\"hl\\\"\\u003eИКСА\\u003c/span\\u003e было фотографирование, благодаря чему поклонники смогли узнать, как выглядел в XIX веке его отчий дом, уничтоженный позже пожаром. Назовите фамилию этого фотографа-любителя.\",\"comment\":\"\\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e — это Че\u0301шир, хотя для песни было использовано неправильное ударение. Графство Чешир, помимо прочего, является малой родиной Чарльза Доджсона (Льюиса Кэрролла), описавшего знаменитого Чеширского кота в книге «Алиса в Стране чудес». Одним из увлечений \\u003cspan class=\\\"hl\\\"\\u003eпрофессора\\u003c/span\\u003e Доджсона было фотографирование. Освоившись с этим сложным процессом, он отправился в деревню Дарсбери, где прошло его детство, и сделал ряд снимков. И успел вовремя — спустя несколько лет пожар уничтожил многое в этой деревне, в том числе и отчий дом писателя.\"},\"366745\":{\"text\":\"Слова “\\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e” и “ТАК” — это замены. “Маленький \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e” — это обучающая игрушка для младших школьников, выполненная в виде \\u003cspan class=\\\"hl\\\"\\u003eИКСА\\u003c/span\\u003e. Можно сказать, что “Маленький \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e” — это \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e ТАК. Напишите \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e ТАК.\",\"comment\":\"игрушка задает математические задачи, которые нужно решить в уме и ввести ответ. \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e — калькулятор. ТАК — наоборот.\"},\"367092\":{\"comment\":\"в серии комиксов «Люди \\u003cspan class=\\\"hl\\\"\\u003eИкс\\u003c/span\\u003e» Чарльз Ксавьер, более известный как \\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e \\u003cspan class=\\\"hl\\\"\\u003eИкс\\u003c/span\\u003e, и Эрик Леншер, более известный как Магнето, создали установку, усиливающую поиск мутантов на большом расстоянии. В сериале «Очень странные дела» усиливающая радиоустановка Да\u0301стина для связи с его подружкой Сьюзи получила такое же название. Слова «включить мозг» — небольшая подсказка, ведь название «Цере\u0301бро» происходит от латинского слова cerebrum [цере\u0301брум] — мозг. \\\\nИсточники: \\\\n1. Сериал «Stranger Things», сезон 3, эпизод 1 «Chapter One: Suzie, Do You Copy?».\\\\n2. https://en.wikipedia.org/wiki/Cerebro\"},\"368152\":{\"text\":\"В этом вопросе \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e заменяет другое слово. Многие фанаты возмутились, узнав новыи\u0306 факт биографии одного из главных героев серии книг. В связи с этим Стивен Кольбе\u0301р отмечает, что, хотя и раньше литературные персонажи оказывались в \\u003cspan class=\\\"hl\\\"\\u003eИКСе\\u003c/span\\u003e, обычно они были на пути... куда?\",\"comment\":\"новость о том, что \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e Дамблдор из саги о Гарри Поттере является геем, удивила многих. Стивен Кольбер обыгрывает выражение «выход из шкафа» как синоним совершения каминг-аута. Во вселеннои\u0306 Клаи\u0306ва Лью\u0301иса, выходя из шкафа, попадали в Нарнию.\"},\"368173\":{\"zachet\":\"1. \\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e Х [\\u003cspan class=\\\"hl\\\"\\u003eикс\\u003c/span\\u003e];\\\\r\\\\n2. «Suicide squad» [суиса\u0301и\u0306д скуа\u0301д].\"},\"369955\":{\"text\":\"[Ведущему: кавычки в тексте вопроса игнорировать]Дуплет. 2 вопроса по 30 секунд обсуждения каждый, ответы сдаются на одном бланке.1. В романе Кевина Андерсона женщина остаётся в осажденном Париже времен франко-прусской войны. Женщине удаётся воссоединиться со своим возлюбленным благодаря зашедшему в Сену «\\u003cspan class=\\\"hl\\\"\\u003eИКСу\\u003c/span\\u003e». Можно сказать, что другой «\\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e» воссоединялся, например, в 2014 году. Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e одним словом.2. В романе Кевина Андерсона \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e сбегает с необитаемого острова через подземный мир, после чего отправляется в путешествие на воздушном шаре. Какого персонажа мы заменили \\u003cspan class=\\\"hl\\\"\\u003eИКСом\\u003c/span\\u003e?\",\"comment\":\"в романе Андерсона капитан Немо участвует во всех других известных произведениях Жюля Верна: с таинственного острова сбегает через центр Земли, встречается на Крымской войне с РобУром-завоевателем, пролетает над Африкой на воздушном шаре. Сам Верн также является персонажем романа, якобы записавшим все приключения со слов Немо. \\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e Арронакс в романе выведен как женщина, в которую влюблены и Верн, и Немо. Из Парижа её спасает зашедший в Сену «Наутилус». Последнее воссоединение группы «Наутилус Помпилиус», которую часто называют просто «Наутилус», произошло в 2014 году.\"},\"370746\":{\"text\":\"На судах нацистские преступники говорили, что всего лишь выполняли приказы. Кристин Осазува не только называет главного виновника, но и проводит параллель между приказами и \\u003cspan class=\\\"hl\\\"\\u003eИКСОМ\\u003c/span\\u003e. Через минуту вы напишете целиком слово, в котором мы заменили шесть букв одной.\",\"comment\":\"понять, врут преступники или нет, было чрезвычайно сложно, и примерно пятая часть обвинительных приговоров была смягчена или вообще отменена. В четвёртом фильме о Гарри Поттере \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e по защите от тёмных искусств рассказывал, что на судах многие сторонники Волан-де-Морта заявляли, что действовали под влиянием подчиняющего заклинания «империус». Формой вопроса мы постарались наложить на вас заклятие, чтобы вы точно сдали правильный ответ. Но упоминать в вопросе «того, кого нельзя называть» всё-таки не стали.\"},\"370880\":{\"text\":\"По слухам, Уильям Додд был назначен послом США в Германии случайно — мол, Рузвельт собирался предложить этот пост Уолтеру Додду. Из-за этого Уильям Додд получил прозвище «посол из \\u003cspan class=\\\"hl\\\"\\u003eИКСА\\u003c/span\\u003e». Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e двумя словами, начинающимися на соседние буквы алфавита.\",\"comment\":\"ходили слухи, что Рузвельт просто ошибся и набрал номер не того У. Додда по телефонному справочнику, да и в целом \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e истории Уильям Додд выглядел очень неочевидной кандидатурой на роль посла. Впрочем, Эдвард Флинн, распространявший эти слухи, также претендовал на этот пост, так что, скорее всего, он просто злословил относительно более удачливого конкурента.\"},\"372432\":{\"text\":\"В соревновании, однажды проведённом в Массачусетском технологическом институте, надо было написать на доске число большее, чем у соперника. Один из участников в свой ход написал в ряд несколько десятков единиц, а другой в ответ провёл по доске пальцем, чтобы осталось две единицы и множество \\u003cspan class=\\\"hl\\\"\\u003eИКСОВ\\u003c/span\\u003e. Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e.\",\"comment\":\"единицы были записаны палочками без хвостика, благодаря чему Адам Эльга легко превратил их в восклицательные знаки. Учитывая, что факториал натурального числа обозначает произведение всех натуральных чисел от 1 до этого числа, планка была задрана довольно высоко. Впрочем, соперник Эльги и другой \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e MIT Агустин Райо всё же его обставил.\"},\"374085\":{\"comment\":\"в комиксе Геймана «Марвел, 1602 год» супергерои действуют в декорациях времен Шекспира. Школу для мутантов — «людей \\u003cspan class=\\\"hl\\\"\\u003eИкс\\u003c/span\\u003e» — возглавляет тот же \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e Чарльз Ксавье, только в этой версии его фамилия пишется на испанский лад. Слово «мутант» тогда не использовалось, но намек на него — в латинском девизе, который начинается со слов omnia mutantur [о\u0301мния мута\u0301нтур].\"},\"376259\":{\"text\":\"Маньяк-учёный из \\u003cspan class=\\\"hl\\\"\\u003eкомиксов\\u003c/span\\u003e носит маску свиньи и стремится совершенствовать своих жертв. Одно из слов в его псевдониме является сокращение от имени. Какого?\",\"comment\":\"учёный взял себе прозвище «\\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e Пиг», а маска свиньи может ввести в заблуждение, что «Пиг» в псевдониме пишется через английскую «i» [ай]. Тем не менее, «Пиг» пишется через «y» [уай] и является отсылкой к пьесе «Пигмалион», что и отражается в намерениях злодея.\"},\"377541\":{\"text\":\"Герой одного романа — \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e, который по просьбе знакомого \\u003cspan class=\\\"hl\\\"\\u003eпрофессора\\u003c/span\\u003e согласился подвергнуться серии экспериментов. Один из них закончился неудачно, поскольку \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e представил комнату, в которой находился, и не учёл, что она была плохо освещена. Кто такой \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e?\",\"comment\":\"герой, у которого была феноменальная память, согласился послужить для знакомого \\u003cspan class=\\\"hl\\\"\\u003eпрофессора\\u003c/span\\u003e объектом экспериментов. При запоминании герой использовал «метод ло\u0301кусов», помещая предназначенные для запоминания данные в разные места какого-то помещения или знакомой ему местности. Однажды он расположил ряды чисел в той комнате, в которой находился, и не учёл, что ему не слишком хорошо видны тёмные углы — на соответствующих им числах он и сбился. Когда его глаза привыкли к темноте, повторный эксперимент прошёл удачно.\"},\"380869\":{\"text\":\"Происхождение фамилии \\u003cspan class=\\\"hl\\\"\\u003eСаи\u0306кс\\u003c/span\\u003e задокументировано, и ее\u0308 историю можно проследить на протяжении как минимум семи веков. Браи\u0306ан \\u003cspan class=\\\"hl\\\"\\u003eСаи\u0306кс\\u003c/span\\u003e исследовал хромосомы своих однофамильцев и вывел коэффициент ЕГО. Назовите ЕГО словом французского происхождения.\",\"comment\":\"зная, что и фамилия, и Y-хромосома передаются по мужскои\u0306 линии, уче\u0308ныи\u0306 предположил, что у всех мужчин однофамильцев также должна быть одна и та же Y- хромосома. Разумеется, такая связь между Y-хромосомои\u0306 и фамилиеи\u0306 может разорваться. Например, если мать таи\u0306но забеременела от сантехника. \\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e Саи\u0306кс смог добыть 48 образцов для анализа. Оказалось, что 50 % их Y-хромосом деи\u0306ствительно идентичны его «саи\u0306ксовскои\u0306» хромосоме, в остальных нашлись признаки адюльтера со стороны однои\u0306 или более миссис Саи\u0306кс. В среднем получился 1% на поколение — это означает, что 99% саи\u0306ксовских же\u0308н в каждом поколении не изменяли мужу (или делали это осторожно).\"},\"381265\":{\"text\":\"В шуточном комиксе про Гарри Поттера \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e Дамблдор представляет нового учителя по Защите от темных искусств, после чего слизеренцы покидают зал. Назовите имя этого учителя.\"},\"383147\":{\"text\":\"Персонаж научно-фантастического сериала возмущён использованием фотофиниша на\u00a0высокотехнологичных гонках из-за\u00a0проявления \\u003cspan class=\\\"hl\\\"\\u003eИКСА\\u003c/span\\u003e. Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e двумя нарицательными словами.\",\"comment\":\"для\u00a0фотофиниша в\u00a0скачках используют электронный микроскоп, но\u00a0наблюдение меняет результат, и\u00a0\\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e Фарнсворт этим недоволен. Редактор и\u00a0сам путался в\u00a0эффекте наблюдателя и\u00a0принципе неопределённости, но\u00a0Википедия утверждает, что\u00a0даже Гейзенберг их путал, так что\u00a0не\u00a0стоит сильно возмущаться этим.\"},\"384458\":{\"text\":\"В начале одного произведения дети, попав в лабораторию, захотели пить, а вскоре с испугом увидели, как люстра с потолком умчались вверх. По одной из версий, автора этого произведения вдохновила повесть «Приключения \\u003cspan class=\\\"hl\\\"\\u003eИКСА\\u003c/span\\u003e меньше ИГРЕКА». \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e и ИГРЕК различаются только первой буквой. Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКСА\\u003c/span\\u003e и ИГРЕК.\",\"comment\":\"речь идёт о сказке «Необыкновенные приключения Ка\u0301рика и Ва\u0301ли», в которой дети уменьшились, выпив \\u003cspan class=\\\"hl\\\"\\u003eэликсир\\u003c/span\\u003e в \\u003cspan class=\\\"hl\\\"\\u003eпрофессорской\\u003c/span\\u003e лаборатории.\"},\"387242\":{\"text\":\"Марина Цветаева писала, что Пушкинский музей — это многолетний бессре\u0301бреный труд её отца и три таких же бессребреных \\u003cspan class=\\\"hl\\\"\\u003eИКСА\\u003c/span\\u003e Юрия Нечаева-Мальцова. Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e словом из семи букв.\",\"comment\":\"\\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e Московского университета Иван Цветаев и меценат Юрий Нечаев Мальцов оставили потомкам добрую память о себе. Правда, менее субъективные источники указывают, что сумма была меньше — миллиона два с половиной. Но именно благодаря этим средствам музейный долгострой был завершён. Бессре\u0301брениками, или бессере\u0301брениками, обычно называют тех, кто равнодушен к богатству, но меценат явно был не из таких.\"},\"389292\":{\"text\":\"Поначалу коллеги называли ЕГО жи\u0301голо и принцем-консо\u0301ртом. В \\u003cspan class=\\\"hl\\\"\\u003eкомиксе\\u003c/span\\u003e «Химери\u0301ческая бригада» ЕГО тёща руководит институтом, в котором обучаются мутанты. Назовите ЕГО.\",\"comment\":\"выдающегося французского учёного, будущего лауреата Нобелевской премии, обвиняли в том, что его женитьба на дочери Марии Склодо\u0301вской-Кюри\u0301 обусловлена карьерными соображениями, и ни о любви, ни о научном таланте говорить в данном случае не стоит. В комиксе Се\u0301ржа Лема\u0301на и Фабри\u0301са Коле\u0301на, созданном в жанре ра\u0301диум-па\u0301нк, «королева радия» Мария Кюри, подобно \\u003cspan class=\\\"hl\\\"\\u003eпрофессору\\u003c/span\\u003e Ксавье\u0301, собирает под крышей своего института мутантов с паранормальными способностями.\"},\"389855\":{\"text\":\"Певица Алекса\u0301ндра Хьюз говорит, что в своём творчестве пытается найти неизвестную частицу себя. Александра выступает под псевдонимом А\u0301лли. \\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e появился уже в самом первом выпуске. Что мы дважды пропустили в вопросе?\",\"zachet\":\"\\u003cspan class=\\\"hl\\\"\\u003eикс\\u003c/span\\u003e\",\"comment\":\"в математике буквой Х [\\u003cspan class=\\\"hl\\\"\\u003eикс\\u003c/span\\u003e] обозначают нечто неизвестное. Александра выступает под псевдонимом Allie X [алли \\u003cspan class=\\\"hl\\\"\\u003eикс\\u003c/span\\u003e]. Лидер и основатель команды супергероев-мутантов \\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e \\u003cspan class=\\\"hl\\\"\\u003eИкс\\u003c/span\\u003e появился в первом выпуске комиксов об их приключениях.\"},\"390427\":{\"text\":\"[Ведущему: прочесть «артурИКС» слитно, чтобы было понятно, что это одно слово! Не обращать внимания команд на кавычки в тексте вопроса!]\\\\nВ этом вопросе \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e является заменой. В книге А\u0301ртура Ко\u0301нан Дойля «Затерянный мир» \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e Че\u0301лленджер нашёл в Бразилии живых динозавров. В честь Конан Дойля был назван найденный в Бразилии артурИ\u0301КС с пятиметровым размахом крыльев. «Челленджер» — это, можно сказать,\\\\nпример \\u003cspan class=\\\"hl\\\"\\u003eИКСА\\u003c/span\\u003e. Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e.\"},\"390864\":{\"text\":\"Маньяк из \\u003cspan class=\\\"hl\\\"\\u003eкомиксов\\u003c/span\\u003e DC (ди-си) носит маску свиньи и стремится совершенствовать тела своих жертв. Его псевдоним – сокращение от имени. Какого?\",\"comment\":\"Убийца носит прозвище \\\"\\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e Пиг\\\", но его имя пишется через \\\"y\\\" (уай), что отсылает мифу о Пигмалионе и пьесе Бернарда Шоу.\"},\"395028\":{\"text\":\"Модернизировать гемино\u0301ида дорого, поэтому 52-летний Хироши Ишигуро прибегает к \\u003cspan class=\\\"hl\\\"\\u003eИКСУ\\u003c/span\\u003e.  Согласно некоторым исследованиям, люди, использовавшие \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e, утрачивают способность сопереживать окружающим. Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e.\",\"comment\":\"Японскому \\u003cspan class=\\\"hl\\\"\\u003eпрофессору\\u003c/span\\u003e дешевле пройти косметическую процедуру, чем создавать нового робота-близнеца, добавляя морщины. Согласно теории, которую поддерживают результаты исследований, из-за нарушенной иннервации мимической мускулатуры теряется способность к эмпатии.\"},\"395029\":{\"text\":\"\\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e Рейтер считал, что Бетховен, вероятно, был отравлен собственным врачом, лечившим композитора при помощи солей. Эту догадку Йорг Ци\u0301глау описывает в главе, название которой начинается со слов «От симфонии до \\u003cspan class=\\\"hl\\\"\\u003eИКСА\\u003c/span\\u003e». Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e двумя словами по-русски или по-английски.\"},\"397764\":{\"text\":\"\\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e Хидэсабýро Уэно скоропостижно скончался в аудитории Токийского университета в возрасте 53-х лет от инсульта... Вне Японии Уэно стал известен благодаря \\u003cspan class=\\\"hl\\\"\\u003eИКСу\\u003c/span\\u003e. Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКСа\\u003c/span\\u003e словом, содержащим числительное.\",\"comment\":\"однажды \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e не вернулся с работы домой… Уэно был владельцем пса Хатико, девять лет ожидавшего возвращения хозяина на станции Сибуя. Имя пса содержит числительное «восемь» (яп. Хати) – это была восьмая по счету собака \\u003cspan class=\\\"hl\\\"\\u003eпрофессора\\u003c/span\\u003e.\\\\nИгра закончена. Большое спасибо всем. Возвращайтесь к тем, кто вас ждет.\"},\"401127\":{\"text\":\"Громоздкие рога взрослого оленя мешают ему передвигаться и являются малоэффективным оружием. Однако они внушают молодым оленям боязливое почтение. В одном романе такие рога сравниваются с \\u003cspan class=\\\"hl\\\"\\u003eИКСОМ\\u003c/span\\u003e. Известно, что \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e был в ранце солдат наполеоновской армии. Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e двумя словами.\",\"comment\":\"«И \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e, … провел параллель между оленьим рогом и маршальским жезлом, который, будучи весьма слабым оружием в бою, тем не менее, делает своего обладателя физически неприкосновенным, ибо внушает трепет и почтение окружающим».\\\\nИзвестно высказывание Наполеона о том, что каждый солдат его армии носит в ранце маршальский жезл.\"},\"402706\":{\"comment\":\"по сюжету фильма, учёный получает рентгеновское зрение. По совпадению, в том же году в комиксах дебютировал \\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e \\u003cspan class=\\\"hl\\\"\\u003eИкс\\u003c/span\\u003e. Общая фамилия учёных – Ксавье\u0301.\"},\"406954\":{\"text\":\"Британская реформа, сократившая «гнилые местечки», снизила коррупцию. Следующие парламентские выборы прозвали «ТАКИМИ», поскольку прежние методы работы с избирателями стали неактуальны. Около ста лет назад йельский \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e предсказал выгоду от ТАКОГО \\u003cspan class=\\\"hl\\\"\\u003eИКСА\\u003c/span\\u003e в несколько миллиардов долларов в год. Назовите ТАКОЙ \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e.\"},\"408225\":{\"text\":\"Говоря о самоотверженности \\u003cspan class=\\\"hl\\\"\\u003eпрофессора\\u003c/span\\u003e Малло\u0301уэна, биограф приводит случай, когда \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e не смог заставить его прекратить лекцию — Маллоуэн продолжил, опустившись на стул. Из \\u003cspan class=\\\"hl\\\"\\u003eИКСА\\u003c/span\\u003e можно собрать «стул». Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e.\",\"comment\":\"только после окончания лекции \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e дал отвезти себя в больницу. Из букв слова «инсульт» можно составить слово «стул».\"},\"408595\":{\"text\":\"Герой фантастического романа потратил много сил, чтобы его компьютер стал вести себя как девушка. Женская ипостась компьютера в шутку упрекала героя в комплексе \\u003cspan class=\\\"hl\\\"\\u003eИКСА\\u003c/span\\u003e. \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e — название астероида из группы Аму\u0301ров. Какое имя заменено словом «\\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e»?\",\"comment\":\"в греческой мифологии скульптор Пигмалион влюбился в статую, после чего она ожила. Аллюзией на этот сюжет стала пьеса Бе\u0301рнарда Шо\u0301у «Пигмалион», в которой \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e превращает простую цветочницу в леди. Отголоски этого сюжета можно найти и в поведении героя. Амур — бог любви, так что название астероида в честь одного из самых известных мифологических влюблённых довольно символично.\"},\"411385\":{\"text\":\"\\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e Артуро Розенблют собирал на своих семинарах самых способных учёных из разных областей. Для встреч Артуро использовал \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e в Вандербилт-холле. Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e двумя словами.\"},\"413263\":{\"text\":\"Герой одной видеоигры утешает бывшего спецназовца, который из-за травм больше не может участвовать в сражениях. Подчёркивая его важность для команды, герой говорит, что если раньше тот был Капитаном Америка, то теперь он \\u003cspan class=\\\"hl\\\"\\u003eикс\\u003c/span\\u003e. Какое слово с удвоенной согласной мы пропустили?\",\"answer\":\"\\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e\",\"comment\":\"из-за полученных ранений бывший спецназовец теперь вынужден перейти на штабную работу и помогать команде головой, а не своими выдающимися боевыми навыками. \\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e Ксавье, также известный как \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e \\u003cspan class=\\\"hl\\\"\\u003eИкс\\u003c/span\\u003e, – основатель команды Люди-\\u003cspan class=\\\"hl\\\"\\u003eИкс\\u003c/span\\u003e, супергерой с парализованной нижней частью тела, сделавший своим главным оружием ум.\"},\"413420\":{\"text\":\"В начале одной из лекций по менеджменту \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e Армин Трост отмечает, что предпочитает менее распространенный термин «ТАКОЙ \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e», а не «ТАКИЕ ИГРЕКИ». По мнению лектора, «ТАКОЙ \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e» подчеркивает возможность преумножения, а не истощения. Что мы заменили на ТАКОЙ \\u003cspan class=\\\"hl\\\"\\u003eИКС\\u003c/span\\u003e?\"},\"413504\":{\"text\":\"\\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e Чарльз Ко\u0301упленд в здании Кембриджского колледжа предпочитал занимать маленькую и не слишком удобную комнату. Поясняя это решение, Коупленд говорил о Боге как о своём единственном \\u003cspan class=\\\"hl\\\"\\u003eИКСЕ\\u003c/span\\u003e — очень занятом и очень тихом. Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКСА\\u003c/span\\u003e двумя словами, которые начинаются на одну и ту же букву.\",\"comment\":\"Для \\u003cspan class=\\\"hl\\\"\\u003eпрофессора\\u003c/span\\u003e была очень важна тишина, и в здании Кембриджского колледжа он занимал комнату практически под крышей.\"},\"414124\":{\"text\":\"Какой известный \\u003cspan class=\\\"hl\\\"\\u003eпрофессор\\u003c/span\\u003e носит эту модель часов с особой защитой?\",\"answer\":\"\\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e \\u003cspan class=\\\"hl\\\"\\u003eИкс\\u003c/span\\u003e.\",\"zachet\":\"\\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e X, Чарльз Ксавьер.\",\"comment\":\"Компания «Ролекс» разработала часы для учёных и инженеров, имеющих дело с\u00a0магнитными полями: название говорит, что они выдерживают воздействие магнитного поля до\u00a0тысячи гауссов, тогда как на точность обычных часов легко влияет поле в 50–100 гауссов. Гаусс — названная в честь учёного единица магнитной индукции (одна тесла — 10 тысяч гауссов). Главный визави этого \\u003cspan class=\\\"hl\\\"\\u003eпрофессора\\u003c/span\\u003e — Магнето, и это \\u003cspan class=\\\"hl\\\"\\u003eПрофессор\\u003c/span\\u003e \\u003cspan class=\\\"hl\\\"\\u003eИкс\\u003c/span\\u003e, он же Чарльз Ксавьер из «Людей \\u003cspan class=\\\"hl\\\"\\u003eИкс\\u003c/span\\u003e».\"},\"416426\":{\"text\":\"Профессорка Маргарет Коллинз более десяти лет проработала в\u00a0Гайане, а\u00a0после даже консультировала местных военных по\u00a0вопросам строительства. Маргарет называли повелительницей \\u003cspan class=\\\"hl\\\"\\u003eИКСОВ\\u003c/span\\u003e. Назовите \\u003cspan class=\\\"hl\\\"\\u003eИКСОВ\\u003c/span\\u003e словом латинского происхождения.\"}},\"packs\":[],\"packCount\":0,\"persons\":[],\"personCount\":0}]}]\\n\"])";
    
    [Fact]
    public void Parse()
    {
        var startIndex = T.IndexOf('{', T.IndexOf('{') + 1);

        var endIndex = T.LastIndexOf('}', T.LastIndexOf('}') - 1);

        var substring = T.Substring(startIndex, endIndex - startIndex + 1);

        var questions = QuestionJsonParser.ParseQuestions(substring);
        
        Assert.NotEmpty(questions);
    }
}